#[test]
fn apply_follows_eval_c_proper_list_contract() {
    let mut interp = Interpreter::new();
    let mut env = Env::new();

    let zero_argument_call = Value::list([Value::symbol("list")]);
    assert_eq!(
        call(&mut interp, "apply", &[zero_argument_call], &mut env,)
            .expect("one-element apply list calls its function with no arguments"),
        Value::Nil
    );

    let vector = Value::vector([Value::Integer(1)]);
    match call(
        &mut interp,
        "apply",
        &[Value::symbol("list"), vector],
        &mut env,
    )
    .map_err(LispError::into_kind)
    {
        Err(LispErrorKind::WrongTypeArgument(predicate, value)) => {
            assert_eq!(predicate, "listp");
            assert_eq!(value, vector);
        }
        other => panic!("apply must reject a vector spread argument, got {other:?}"),
    }
}

fn upstream_primitive_contract_output(program: &str) -> String {
    crate::test_support::mark_process_test();
    let binary = upstream_emacs_repo().join("src/emacs");
    let program = crate::test_support::oracle_program_ascii(program);
    let output = std::process::Command::new(&binary)
        .args(["--batch", "-Q", "--eval", &program])
        .output()
        .unwrap_or_else(|error| {
            panic!(
                "run primitive-contract oracle {}: {error}",
                binary.display()
            )
        });
    assert!(
        output.status.success(),
        "primitive-contract oracle failed: {}",
        String::from_utf8_lossy(&output.stderr)
    );
    String::from_utf8_lossy(&output.stdout).into_owned()
}

#[test]
fn backquote_shorthand_prints_only_the_reader_s_symbols_within_a_backquote() {
    // print.c: Qbackquote, Qcomma and Qcomma_at are the symbols named
    // "`", "," and ",@"; the symbols named `backquote', `comma' and
    // `comma-at' print as themselves (bytecomp.el's `(require 'backquote)'
    // reached a native compilation unit's constants as "`").  The comma
    // shorthand is printed only inside a backquote, one nesting level
    // each (`new_backquote_output').
    assert_oracle_contract_matches_interpreter(
        r#"(list (prin1-to-string 'backquote)
                 (prin1-to-string '(backquote x))
                 (prin1-to-string (list (intern "backquote") 1 2))
                 (prin1-to-string '\`)
                 (prin1-to-string '(\` x))
                 (prin1-to-string '(\` x y))
                 (prin1-to-string 'comma)
                 (prin1-to-string '(\, x))
                 (prin1-to-string '(\,@ x))
                 (prin1-to-string '(\` (a (\, x) (\,@ y))))
                 (prin1-to-string '(\` (\` (\, (\, x)))))
                 (prin1-to-string '(\` (\, (\, x))))
                 (prin1-to-string '(\` (comma x)))
                 (prin1-to-string '(backquote (\, x))))"#,
        r#"("backquote" "(backquote x)" "(backquote 1 2)" "\\`" "`x" "(\\` x y)" "comma" "(\\, x)" "(\\,@ x)" "`(a ,x ,@y)" "``,,x" "`,(\\, x)" "`(comma x)" "(backquote (\\, x))")"#,
        "backquote shorthand",
    );
}

fn assert_upstream_primitive_contract(program: &str, expected: &str) {
    assert_eq!(
        upstream_primitive_contract_output(program),
        expected,
        "oracle disagreed; program sent was:\n{program}"
    );
}

#[test]
fn always_local_slots_are_each_buffers_own_like_buffer_c() {
    // buffer.c: an index -1 DEFVAR_PER_BUFFER slot is every buffer's own
    // from reset_buffer on; buffer_defaults only answers default-value.
    assert_oracle_contract_matches_interpreter(
        r#"(with-temp-buffer
             (let ((other (generate-new-buffer " other")))
               (unwind-protect
                   (list
                    (default-value 'mode-name)
                    (default-value 'default-directory)
                    (progn (setq mode-name "M") (kill-local-variable 'mode-name) mode-name)
                    (progn (setq local-minor-modes '(x) mark-active t mode-name "N")
                           (kill-all-local-variables)
                           (list local-minor-modes mark-active mode-name))
                    (progn (setq-default mode-name "D")
                           (prog1 (list mode-name (with-current-buffer other mode-name)
                                        (with-temp-buffer mode-name))
                             (setq-default mode-name nil)))
                    (let ((mark-active 'zz))
                      (list mark-active (default-value 'mark-active)
                            (buffer-local-value 'mark-active other)))
                    (with-current-buffer other
                      (setq buffer-file-name "/tmp/x")
                      (prog1 (with-temp-buffer (buffer-local-value 'buffer-file-name other))
                        (setq buffer-file-name nil)))
                    (mapcar (lambda (e) (if (consp e) (car e) e))
                            (buffer-local-variables other)))
                 (kill-buffer other))))"#,
        "(nil nil \"M\" ((x) t \"Fundamental\") (\"Fundamental\" \"Fundamental\" \"Fundamental\") \
         (zz nil nil) \"/tmp/x\" (buffer-undo-list buffer-display-time buffer-display-count \
         buffer-invisibility-spec buffer-file-truename point-before-scroll \
         buffer-auto-save-file-format buffer-file-format enable-multibyte-characters mark-active \
         mode-name local-minor-modes major-mode buffer-read-only buffer-auto-save-file-name \
         buffer-saved-size buffer-backed-up default-directory buffer-file-name))",
        "always-local slots",
    );
}

