#[test]
fn mapatoms_honors_dynamic_obarrays_legacy_conversion_and_function_cells() {
    assert_oracle_contract_matches_interpreter(
        r#"(mapcar
          (lambda (form) (condition-case err (eval form t) (error err)))
          '((let ((obarray (obarray-make)) seen)
              (intern "first" obarray)
              (intern "second" obarray)
              (mapatoms (lambda (symbol) (push (symbol-name symbol) seen)))
              (sort seen #'string<))
            (mapatoms 42 (obarray-make))
            (mapatoms 42 17)
            (let ((table (vector 0)))
              (list (mapatoms 42 table) (obarrayp (aref table 0))))
            (let ((table (obarray-make)) (callback (make-symbol "callback")) (count 0))
              (intern "first" table)
              (intern "second" table)
              (fset callback
                    (lambda (_)
                      (setq count (1+ count))
                      (fset callback (lambda (_) (setq count (+ count 10))))))
              (mapatoms callback table)
              count)))"#,
        r#"(("first" "second") nil (wrong-type-argument obarrayp 17) (nil t) 11)"#,
        "mapatoms obarray and callback contract",
    );
}

#[test]
fn native_mapatoms_preserves_collection_redefinition_and_nonlocal_exit() {
    assert_oracle_contract_matches_interpreter(
        r#"(progn
          (require 'comp)
          (let* ((comp-no-spawn nil)
                 (comp-running-batch-compilation t)
                 (native-comp-jit-compilation nil)
                 (caller (native-compile
                          '(lambda (function table) (mapatoms function table))))
                 (native-callback (native-compile
                                   '(lambda (symbol)
                                      (garbage-collect)
                                      (set symbol 1))))
                 (table (obarray-make))
                 (first (intern "first" table))
                 (second (intern "second" table))
                 (callback (make-symbol "callback"))
                 (count 0))
            (list
             (native-comp-function-p caller)
             (native-comp-function-p native-callback)
             (progn (funcall caller native-callback table)
                    (list (symbol-value first) (symbol-value second)))
             (progn
               (fset callback
                     (lambda (_)
                       (garbage-collect)
                       (setq count (1+ count))
                       (fset callback (lambda (_) (setq count (+ count 10))))))
               (funcall caller callback table)
               count)
             (catch 'done (funcall caller (lambda (_) (throw 'done 42)) table))
             (funcall caller 42 (obarray-make))
             (condition-case err (funcall caller 42 table) (error (car err))))))"#,
        "(t t (1 1) 11 42 nil invalid-function)",
        "native mapatoms callback contract",
    );
}

/// Ask the pinned oracle a question and return its stdout verbatim.  For
/// contract elements that are properties of the oracle's OWN build or host
/// libraries (configure-time paths, linked-library versions, per-build
/// fboundp), the honest expectation is the oracle's live answer, not a
/// literal transcribed from whichever container the test was written on.
fn upstream_oracle_stdout(program: &str) -> String {
    crate::test_support::mark_process_test();
    let binary = upstream_emacs_repo().join("src/emacs");
    let program = crate::test_support::oracle_program_ascii(program);
    let output = std::process::Command::new(&binary)
        .args(["--batch", "-Q", "--eval", &program])
        .output()
        .unwrap_or_else(|error| panic!("run oracle probe {}: {error}", binary.display()));
    assert!(
        output.status.success(),
        "oracle probe failed: {}",
        String::from_utf8_lossy(&output.stderr)
    );
    String::from_utf8_lossy(&output.stdout).into_owned()
}

fn assert_upstream_primitive_contract_with_stdin(program: &str, stdin: &str, expected: &str) {
    crate::test_support::mark_process_test();
    let binary = upstream_emacs_repo().join("src/emacs");
    let program = crate::test_support::oracle_program_ascii(program);
    let mut child = std::process::Command::new(&binary)
        .args(["--batch", "-Q", "--eval", &program])
        .stdin(std::process::Stdio::piped())
        .stdout(std::process::Stdio::piped())
        .stderr(std::process::Stdio::piped())
        .spawn()
        .unwrap_or_else(|error| {
            panic!(
                "run primitive-contract oracle {}: {error}",
                binary.display()
            )
        });
    child
        .stdin
        .as_mut()
        .expect("GNU primitive-contract stdin should be piped")
        .write_all(stdin.as_bytes())
        .expect("write GNU primitive-contract stdin");
    let output = child
        .wait_with_output()
        .expect("wait for GNU primitive-contract oracle");
    assert!(
        output.status.success(),
        "primitive-contract oracle failed: {}",
        String::from_utf8_lossy(&output.stderr)
    );
    assert_eq!(String::from_utf8_lossy(&output.stdout), expected);
}

#[test]
fn record_literal_detection_does_not_traverse_vector_storage() {
    let vector = Value::vector([Value::Integer(1), Value::Integer(2)]);
    let Kind::Vector(vector_storage) = vector.kind() else {
        panic!("vector syntax must construct a GNU-class vector object")
    };
    // Even a cyclic payload leaves the object class unchanged. The former
    // raw mutable slice did not enforce a borrow or detect traversal.
    vector_storage.set(0, vector);
    assert!(record_literal_items(&vector).is_none());
}

#[test]
fn character_table_literal_materializes_nested_bytecode_decoder() {
    let decoder = Value::ReaderForm(crate::lisp::alloc::VectorlikeRef::allocate(
        crate::lisp::types::ReaderForm::Closure {
            kind: crate::lisp::types::ReaderClosureKind::ByteCode,
            slots: vec![
                Value::Integer(0),
                Value::String(String::new().into()),
                Value::vector([]),
                Value::Integer(0),
            ],
        },
    ));
    let mut fields = vec![Value::Nil; 70];
    fields[2] = Value::symbol("char-code-property-table");
    fields[68] = Value::symbol("name");
    fields[69] = decoder;
    let literal = Value::ReaderForm(crate::lisp::alloc::VectorlikeRef::allocate(
        crate::lisp::types::ReaderForm::CharTable { fields },
    ));

    let mut interp = Interpreter::new();
    let mut env = Env::new();
    let Kind::CharTable(table_id) =
        materialize_read_char_table_literals(&mut interp, &literal, &mut env)
            .expect("materialize a character table with a bytecode decoder")
            .kind()
    else {
        panic!("character-table syntax must produce a typed table");
    };
    let Some(Kind::Closure(decoder)) = interp.char_table_extra_slot(table_id, 1).map(|v| v.kind())
    else {
        panic!("the nested decoder must be a typed byte-code-function object");
    };
    assert!(decoder.is_bytecode());
}

