#[test]
fn bytecode_closure_aref_and_func_arity_preserve_gnu_argument_descriptors() {
    // GNU 30.2 data.c:Faref returns CLOSURE_ARGLIST verbatim, while
    // eval.c:lambda_arity delegates integer descriptors to
    // bytecode.c:get_byte_code_arity.  Cover packed fixed/rest descriptors
    // and the legacy dynamic-binding arglist independently.
    let contract = r#"
        (let ((zero (make-byte-code 0 "" [] 0))
              (fixed (make-byte-code 513 "" [] 0))
              (rest (make-byte-code 128 "" [] 0))
              (legacy
               (make-byte-code '(a &optional b &rest c) "" [] 0)))
          (list (aref zero 0) (func-arity zero)
                (aref fixed 0) (func-arity fixed)
                (aref rest 0) (func-arity rest)
                (aref legacy 0) (func-arity legacy)))
    "#;
    let expected = "(0 (0 . 0) 513 (1 . 2) 128 (0 . many) (a &optional b &rest c) (1 . many))";
    assert_upstream_primitive_contract(&format!("(prin1 {contract})"), expected);

    let mut interp = Interpreter::new();
    let form = Reader::new(contract)
        .read()
        .expect("bytecode argument descriptor contract should parse")
        .expect("bytecode argument descriptor contract should contain a form");
    assert_eq!(
        interp
            .eval(&form, &mut crate::lisp::types::Env::new())
            .expect("bytecode argument descriptor contract should evaluate")
            .to_string(),
        expected
    );
}

#[test]
fn func_arity_uses_gnu_symbolp_for_positioned_symbols() {
    let mut interp = Interpreter::new();
    let mut env = Env::new();
    interp.set_symbol_value_cell("symbols-with-pos-enabled", Value::T);
    let positioned = |interp: &mut Interpreter, name: &str, position: i64, env: &mut Env| {
        call(
            interp,
            "position-symbol",
            &[Value::Symbol(name.into()), Value::Integer(position)],
            env,
        )
        .expect("construct a positioned symbol")
    };

    let positioned_car = positioned(&mut interp, "car", 1, &mut env);
    assert_eq!(
        call(&mut interp, "func-arity", &[positioned_car], &mut env)
            .expect("resolve a positioned function name"),
        Value::cons(Value::Integer(1), Value::Integer(1))
    );

    let optional = positioned(&mut interp, "&optional", 2, &mut env);
    let argument = positioned(&mut interp, "argument", 3, &mut env);
    let closure = Value::allocated_closure(&[
        Value::list([optional, argument]),
        Value::string("unexecuted argument descriptor probe"),
        Value::vector([]),
        Value::Integer(1),
    ]);
    assert_eq!(
        call(&mut interp, "func-arity", &[closure], &mut env)
            .expect("read positioned byte-code argument descriptors"),
        Value::cons(Value::Integer(0), Value::Integer(1))
    );

    let macro_tag = positioned(&mut interp, "macro", 4, &mut env);
    let macro_function = Value::cons(macro_tag, Value::lambda(Vec::new(), Vec::new(), Value::Nil));
    assert_eq!(
        call(&mut interp, "func-arity", &[macro_function], &mut env)
            .expect("unwrap a positioned macro tag"),
        Value::cons(Value::Integer(0), Value::Integer(0))
    );

    let closure_parameters = Value::list([
        positioned(&mut interp, "number", 5, &mut env),
        positioned(&mut interp, "value", 6, &mut env),
    ]);
    let interpreted = call(
        &mut interp,
        "make-interpreted-closure",
        &[
            closure_parameters,
            Value::list([Value::Nil]),
            Value::list([Value::T]),
        ],
        &mut env,
    )
    .expect("construct an interpreted closure with positioned parameters");
    let Kind::Closure(lambda) = interpreted.kind() else {
        panic!("make-interpreted-closure must return a lambda")
    };
    let visible_parameters = lambda.parameters();
    assert_eq!(
        call(
            &mut interp,
            "eq",
            &[visible_parameters, closure_parameters],
            &mut env,
        )
        .expect("compare GNU-visible argument-list identity"),
        Value::T
    );
    assert_eq!(
        call(&mut interp, "func-arity", &[interpreted], &mut env)
            .expect("read an interpreted closure's positioned argument list"),
        Value::cons(Value::Integer(2), Value::Integer(2))
    );
}

#[test]
fn defvar_and_defconst_use_gnu_check_symbol_for_positioned_names() {
    let mut interp = Interpreter::new();
    let mut env = Env::new();
    interp.set_symbol_value_cell("symbols-with-pos-enabled", Value::T);

    for (form, name, value, position) in [
        ("defvar", "positioned-variable", 17, 1),
        ("defconst", "positioned-constant", 29, 2),
    ] {
        let positioned = call(
            &mut interp,
            "position-symbol",
            &[Value::Symbol(name.into()), Value::Integer(position)],
            &mut env,
        )
        .expect("construct a positioned definition name");
        let definition = Value::list([
            Value::Symbol(form.into()),
            positioned,
            Value::Integer(value),
        ]);
        assert_eq!(
            interp
                .eval(&definition, &mut env)
                .expect("evaluate a positioned variable definition"),
            positioned
        );
        assert_eq!(
            interp
                .lookup(name, &env)
                .expect("look up the bare definition name"),
            Value::Integer(value)
        );
    }
}

#[test]
fn compiled_time_string_results_keep_text_property_mutation() {
    // GNU timefns.c allocates mutable Lisp strings: multibyte for
    // Fformat_time_string and unibyte for Fcurrent_time_string.  A
    // byte-compiled lexical local does not pass through the interpreter's
    // value-storage upgrade, so returning immutable host text here silently
    // discarded ERC's timestamp properties.
    let program = r#"
        (progn
          (require 'bytecomp)
          (funcall
           (byte-compile
            (lambda ()
              (let ((formatted (format-time-string "%H:%M" 704591940 t))
                    (current (current-time-string 704591940 t)))
                (dolist (s (list formatted current))
                  (put-text-property 0 (length s) 'invisible 'timestamp s))
                (list
                 (list (get-text-property 0 'invisible formatted)
                       (object-intervals formatted)
                       (multibyte-string-p formatted))
                 (list (get-text-property 0 'invisible current)
                       (object-intervals current)
                       (multibyte-string-p current))))))))
    "#;
    let expected = concat!(
        "((timestamp ((0 5 (invisible timestamp))) t) ",
        "(timestamp ((0 24 (invisible timestamp))) nil))"
    );
    assert_upstream_primitive_contract(&format!("(prin1 {program})"), expected);

    let mut interp = crate::test_support::initialized_upstream_batch_interpreter();
    let form = Reader::new(program)
        .read_all()
        .expect("read compiled time-string program")
        .remove(0);
    let result = interp
        .eval(&form, &mut crate::lisp::types::Env::new())
        .expect("evaluate compiled time-string program");
    assert_eq!(result.to_string(), expected);
}

#[test]
fn compare_buffer_substrings_reads_both_ranges_in_place_like_editfns() {
    // editfns.c compares the two ranges character by character in the
    // buffers themselves. The ranges here cross the gap, which an edit
    // leaves inside them, in a multibyte buffer and in an ASCII one, come
    // reversed or whole, and
    // fold case through the current buffer's `case-fold-search'. A range
    // outside a buffer's accessible region signals `args-out-of-range'
    // with the original bounds; Emaxx clamped it and compared what was
    // left.
    let program = r#"
        (with-temp-buffer
          (dotimes (i 400) (insert (format "line %03d é\n" i)))
          (goto-char 1700) (insert "x") (delete-char -1)
          (let ((other (generate-new-buffer " other")))
            (unwind-protect
                (progn
                  (with-current-buffer other
                    (dotimes (i 400) (insert (format "line %03d e\n" i)))
                    (goto-char 1100) (insert "x") (delete-char -1))
                  (list (compare-buffer-substrings nil 1 2000 nil 1 2000)
                        (compare-buffer-substrings nil 1 2000 other 1 2000)
                        (compare-buffer-substrings nil 2000 1 other 1 2000)
                        (compare-buffer-substrings nil 1500 3000 nil 1500 2999)
                        (compare-buffer-substrings other 900 1300 other 13 413)
                        (compare-buffer-substrings other 1 4401 other nil nil)
                        (compare-buffer-substrings other 1000 4000 other 1012 4012)
                        (progn (goto-char (point-max)) (insert "LINE")
                               (let ((case-fold-search t))
                                 (compare-buffer-substrings nil (- (point-max) 4) (point-max) nil 1 5)))
                        (let ((case-fold-search nil))
                          (compare-buffer-substrings nil (- (point-max) 4) (point-max) nil 1 5))
                        (condition-case err (compare-buffer-substrings other 1 4402 nil 1 5)
                          (error err))
                        (condition-case err (compare-buffer-substrings nil 1 5 nil 0 5)
                          (error err))
                        (save-restriction
                          (narrow-to-region 10 20)
                          (list (compare-buffer-substrings nil nil nil nil 10 20)
                                (condition-case err (compare-buffer-substrings nil 9 20 nil 10 20)
                                  (error err))
                                (condition-case err (compare-buffer-substrings nil 10 20 nil 21 10)
                                  (error err))))))
              (kill-buffer other))))"#;
    assert_oracle_contract_matches_interpreter(
        program,
        "(0 10 10 1500 -1 0 1 0 -1 (args-out-of-range 1 4402) (args-out-of-range 0 5) (0 (args-out-of-range 9 20) (args-out-of-range 21 10)))",
        "compare-buffer-substrings ranges",
    );
}

#[test]
fn compare_buffer_substrings_compares_short_ascii_ranges_like_editfns() {
    // Short ranges of ASCII buffers lie on one side of the gap and are compared
    // as bytes: equal, differing, prefix either way, empty and reversed
    // ranges, another buffer, and case kept with case-fold-search nil.
    let program = r#"(with-temp-buffer
  (insert "abcdef abcxyz abc ab ABC")
  (let ((case-fold-search nil) (other (generate-new-buffer " cmp")))
    (unwind-protect
        (progn
          (with-current-buffer other (insert "abd"))
          (list (compare-buffer-substrings nil 1 4 nil 8 11)
                (compare-buffer-substrings nil 1 7 nil 8 14)
                (compare-buffer-substrings nil 8 14 nil 1 7)
                (compare-buffer-substrings nil 1 4 nil 19 21)
                (compare-buffer-substrings nil 19 21 nil 1 4)
                (compare-buffer-substrings nil 3 3 nil 5 5)
                (compare-buffer-substrings nil 4 1 nil 11 8)
                (compare-buffer-substrings nil 1 4 other nil nil)
                (compare-buffer-substrings nil 22 25 nil 1 4)))
      (kill-buffer other))))"#;
    assert_oracle_contract_matches_interpreter(
        program,
        "(0 -4 4 3 -3 0 0 -3 -1)",
        "compare-buffer-substrings of short ASCII ranges",
    );
}

