#[test]
fn sort_calls_the_numeric_lambda_with_its_arguments_bound() {
    // GNU sort.c calls the predicate. The old local test instead required
    // body recognition that skipped the call and broke its semantics.
    assert_oracle_contract_matches_interpreter(
        "(let ((seen nil)) (list (sort (list 3 1 2) (lambda (left right) (setq seen (+ left right)) (< left right))) (numberp seen)))",
        "((1 2 3) t)",
        "numeric sort comparator argument binding",
    );
}

#[test]
fn sort_sorts_in_place_only_when_asked_or_called_with_two_arguments() {
    // fns.c:Fsort: (sort SEQ PREDICATE) sorts in place; the keyword form
    // sorts a copy unless :in-place is non-nil.  Two arguments are always
    // the old call, so a lone keyword is the predicate; another even count
    // or an unknown keyword is an error (signal_error splices a list).
    assert_oracle_contract_matches_interpreter(
        r#"(let ((v (vector 3 1 2)) (l (list 3 1 2)) (w (vector 2 1)) (m (list 2 1)))
             (list (sort v :lessp #'<) v (sort l :lessp #'<) l (sort w #'<) w
                   (sort m :in-place t) m (sort (list 5 4) :reverse t)
                   (condition-case err (sort l :lessp) (error err))
                   (condition-case err (sort l :foo 1) (error err))
                   (condition-case err (sort l (list 'a 'b) 1) (error err))
                   (condition-case err (sort 5 :lessp #'<) (error err))))"#,
        "([1 2 3] [3 1 2] (1 2 3) (3 1 2) [1 2] [1 2] (1 2) (1 2) (5 4) \
         (void-function :lessp) (error \"Invalid keyword argument\" :foo) \
         (error \"Invalid keyword argument\" a b) (wrong-type-argument list-or-vector-p 5))",
        "sort argument forms",
    );
}

#[test]
fn sort_calls_the_predicate_in_timsorts_order() {
    // sort.c's Timsort: every comparison of a short sort in order, then
    // the count and a positional checksum of the comparisons and of the
    // result for a long scrambled list with equal keys (runs, binary
    // insertion and merges), a reversed sort, a vector, and runs that
    // interleave in blocks (galloping).  A predicate sees these exact
    // calls, so its side effects and its answers for an inconsistent
    // order follow GNU's.
    assert_oracle_contract_matches_interpreter(
        r#"(let* ((state 7)
                  (rand (lambda (m)
                          (setq state (% (+ (* state 1103515245) 12345) 2147483648))
                          (% (/ state 65536) m)))
                  (keyed (lambda (n m)
                           (let ((i -1) l)
                             (dotimes (_ n) (push (cons (funcall rand m) (setq i (1+ i))) l))
                             l)))
                  (log nil)
                  (pred (lambda (a b) (push (list (cdr a) (cdr b)) log) (< (car a) (car b))))
                  (sum (lambda (items)
                         (let ((sum 0))
                           (dolist (item items sum)
                             (setq sum (% (+ (* sum 31)
                                             (if (consp item)
                                                 (+ (* 1009 (car item)) (cadr item))
                                               item))
                                          1000000007))))))
                  (traced (lambda (sorted)
                            (prog1 (list (length log) (funcall sum (nreverse log))
                                         (funcall sum (mapcar #'cdr sorted)))
                              (setq log nil)))))
             (list
              (progn (sort (funcall keyed 12 4) pred) (prog1 (nreverse log) (setq log nil)))
              (funcall traced (sort (funcall keyed 300 10) pred))
              (funcall traced (sort (funcall keyed 100 3) :lessp pred :reverse t))
              (funcall traced (append (sort (vconcat (funcall keyed 150 1000)) :lessp pred) nil))
              (funcall traced
                       (sort (mapcar (lambda (k) (cons k k))
                                     (append (number-sequence 0 200 2)
                                             (number-sequence 1 201 2)
                                             (number-sequence 300 250 -1)))
                             pred))))"#,
        "(((10 11) (9 10) (9 11) (9 10) (8 9) (8 11) (7 8) (7 11) (6 8) (6 11) (6 7) (5 7) \
         (5 9) (5 8) (4 5) (4 6) (4 11) (3 7) (3 11) (3 6) (2 7) (2 8) (2 9) (2 10) (1 7) \
         (1 11) (1 3) (0 7) (0 9) (0 10) (0 2)) (1873 894399106 682825943) \
         (488 235025414 924669266) (892 327427164 362282841) (476 832379101 213032295))",
        "Timsort comparison schedule",
    );
}

#[test]
fn a_signal_from_the_predicate_leaves_a_vector_as_timsort_left_it() {
    // sort.c works in a vector's own slots.  A signal while a merge's
    // temporary run sits in the C stack array abandons the run, leaving
    // stale copies (994 distinct values of 1,000 here); once a merge has
    // outgrown that array, the cleanup puts the run back.  A list is sorted
    // in a copy (fns.c:sort_list) and keeps its order.
    assert_oracle_contract_matches_interpreter(
        r#"(let* ((orig (mapcar (lambda (i) (% (* i 37) 1001)) (number-sequence 1 1000)))
                  (sum (lambda (items)
                         (let ((s 0))
                           (dolist (x items s) (setq s (% (+ (* s 31) x) 1000000007))))))
                  (run (lambda (stop)
                         (let ((v (vconcat orig)) (l (copy-sequence orig)) (n 0))
                           (list (condition-case nil
                                     (progn (sort v (lambda (a b)
                                                      (when (= (setq n (1+ n)) stop)
                                                        (error "Stop"))
                                                      (< a b)))
                                            'done)
                                   (error n))
                                 (funcall sum (append v nil))
                                 (length (delete-dups (append v nil)))
                                 (progn (setq n 0)
                                        (condition-case nil
                                            (sort l (lambda (a b)
                                                      (when (= (setq n (1+ n)) stop)
                                                        (error "Stop"))
                                                      (< a b)))
                                          (error nil))
                                        (equal l orig)))))))
             (mapcar run '(50 1500 9000)))"#,
        "((50 329895207 1000 t) (1500 402671903 994 t) (done 436778830 1000 nil))",
        "vector after a sort predicate's signal",
    );
}

#[test]
fn native_kill_emacs_is_noncatchable_runs_hooks_and_preserves_c_exit_mapping() {
    let mut interp = crate::test_support::initialized_gnu_early_lisp_interpreter();
    let form = Reader::new(
        r#"(progn
             (setq emaxx-kill-seen nil)
             (setq kill-emacs-hook
                   (list
                    (lambda ()
                      (setq emaxx-kill-seen
                            (cons 'first emaxx-kill-seen)))
                    (lambda () (error "ignored shutdown error"))
                    (lambda ()
                      (setq emaxx-kill-seen
                            (cons 'third emaxx-kill-seen)))))
             (unwind-protect
                 (condition-case nil
                     (kill-emacs 7)
                   (t
                    (setq emaxx-kill-seen
                          (cons 'caught emaxx-kill-seen))))
               (setq emaxx-kill-seen
                     (cons 'cleanup emaxx-kill-seen))))"#,
    )
    .read_all()
    .expect("read kill-emacs nonlocal-control contract")
    .remove(0);
    let error = interp
        .eval(&form, &mut crate::lisp::types::Env::new())
        .expect_err("kill-emacs must not return into Lisp");
    assert!(matches!(
        error.kind(),
        LispErrorKind::Terminate(EmacsTermination {
            exit_code: 7,
            restart: false
        })
    ));
    assert_eq!(
        interp.lookup_var("emaxx-kill-seen", &crate::lisp::types::Env::new()),
        Some(Value::list([
            Value::symbol("third"),
            Value::symbol("first")
        ])),
        "ordinary hook errors are demoted, while condition handlers and unwind cleanup never run"
    );
    assert_eq!(
        interp.take_pending_termination(),
        Some(EmacsTermination {
            exit_code: 7,
            restart: false,
        })
    );

    let termination_for = |args: &[Value]| {
        let mut interp = Interpreter::new();
        match call(
            &mut interp,
            "kill-emacs",
            args,
            &mut crate::lisp::types::Env::new(),
        )
        .expect_err("native kill-emacs must request process termination")
        .into_kind()
        {
            LispErrorKind::Terminate(termination) => termination,
            other => panic!("unexpected kill-emacs outcome: {other}"),
        }
    };
    assert_eq!(
        termination_for(&[]),
        EmacsTermination {
            exit_code: 0,
            restart: false,
        }
    );
    assert_eq!(
        termination_for(&[Value::Integer(-1)]),
        EmacsTermination {
            exit_code: -1,
            restart: false,
        }
    );
    assert_eq!(
        termination_for(&[Value::Integer((1 << 61) - 1)]),
        EmacsTermination {
            exit_code: i32::MAX,
            restart: false,
        },
        "most-positive-fixnum masked to INT_MAX"
    );
    assert_eq!(
        termination_for(&[Value::Integer(i64::MAX)]),
        EmacsTermination {
            exit_code: 0,
            restart: false,
        },
        "past most-positive-fixnum make_int gives a bignum, which FIXNUMP rejects"
    );
    assert_eq!(
        termination_for(&[Value::big_integer(BigInt::from(i64::MAX) + 1)]),
        EmacsTermination {
            exit_code: 0,
            restart: false,
        },
        "emacs.c uses FIXNUMP, so a bignum is not an exit status"
    );
    assert_eq!(
        termination_for(&[Value::String("terminal input".into()), Value::T]),
        EmacsTermination {
            exit_code: 0,
            restart: true,
        }
    );
}

#[test]
fn native_user_ptr_predicate_is_exhaustive_over_the_module_free_value_model() {
    let mut interp = crate::test_support::initialized_gnu_early_lisp_interpreter();
    let mut env = crate::lisp::types::Env::new();
    let string_object = interp
        .eval(
            &Reader::new("\"heap string\"")
                .read_all()
                .expect("read string literal")
                .remove(0),
            &mut env,
        )
        .expect("evaluate string literal");
    let lambda = interp
        .eval(
            &Reader::new("(lambda (value) value)")
                .read_all()
                .expect("read lambda")
                .remove(0),
            &mut env,
        )
        .expect("evaluate lambda");
    let representatives = vec![
        Value::Nil,
        Value::T,
        Value::Integer(1),
        Value::big_integer(BigInt::from(i64::MAX) + 1),
        Value::float(1.5),
        Value::String("inline string".into()),
        string_object,
        Value::symbol("symbol"),
        Value::cons(Value::Integer(1), Value::Nil),
        Value::BuiltinFunc("car".into()),
        lambda,
        Value::buffer(1, "*scratch*"),
        Value::Marker(crate::lisp::types::MarkerRef::new()),
        Value::Overlay(crate::overlay::OverlayRef::new(false, false)),
        Value::CharTable(crate::lisp::types::CharTableRef::new(
            Value::Nil,
            Value::Nil,
            0,
        )),
        interp.create_record("representative", Vec::new()),
        Value::Finalizer(crate::lisp::alloc::FinalizerRef::new(Value::Nil)),
        Value::Unbound,
    ];

    for value in representatives {
        assert_eq!(
            call(
                &mut interp,
                "user-ptrp",
                std::slice::from_ref(&value),
                &mut env,
            )
            .unwrap_or_else(|error| panic!("user-ptrp rejected {value}: {error}")),
            Value::Nil,
            "module-free Emaxx cannot construct GNU's PVEC_USER_PTR"
        );
    }
}

#[test]
fn native_comp_pure_introspection_family_matches_gnu_and_the_backend_boundary() {
    // comp.c: `comp--subr-signature' prints the primitive's arity, and the
    // capability helpers report the libgccjit backend GNU was built with;
    // this build carries the same backend (the oracle answers the same
    // libgccjit version, since both link the host library).
    let program = r#"
        (list
         (mapcar (lambda (name) (comp--subr-signature (symbol-function name)))
                 '(car + concat if let))
         (native-comp-available-p)
         (comp-native-driver-options-effective-p)
         (comp-native-compiler-options-effective-p)
         (comp-libgccjit-version))"#;
    let (major, minor, patch) = crate::lisp::native_comp::NativeCompilerState::version()
        .expect("the configured native backend must load libgccjit");
    let expected = format!(
        r#"(("car(1 . 1)" "+(0 . many)" "concat(0 . many)" "if(2 . unevalled)" "let(1 . unevalled)") t t t ({major} {minor} {patch}))"#,
    );
    assert_oracle_contract_matches_interpreter(program, &expected, "native-comp introspection");
}

