#[test]
fn md5_coding_endpoints_and_noerror_follow_gnu_in_native_calls() {
    assert_oracle_contract_matches_interpreter(
        r#"(progn
(require 'comp)
(list
 (mapcar (lambda (args) (condition-case e (apply #'md5 args) (error e)))
  (list (list "abc" nil nil nil nil)
        (list "éX" nil nil 'utf-8 nil)
        (list "éX" 0 1 'utf-8 nil)
        (list "éX" -1 nil 'utf-8 nil)
        (list (unibyte-string 233 88) nil nil 'utf-8 nil)
        (list "éX" nil nil 'invalid-coding nil)
        (list "éX" nil nil 'invalid-coding t)
        (list "abc" 2 1 nil nil)))
 (let ((last-coding-system-used 'sentinel))
   (md5 "é" nil nil 'utf-8) last-coding-system-used)
 (with-temp-buffer
   (insert "aéZ")
   (let ((coding-system-for-write 'utf-8) (select-safe-coding-system-function nil))
     (list (md5 (current-buffer) 3 2 nil nil)
           (let ((coding-system-for-write 'invalid-coding))
             (condition-case e (md5 (current-buffer)) (error e)))
           (let ((coding-system-for-write 'invalid-coding))
             (md5 (current-buffer) nil nil nil t))
           (progn (narrow-to-region 2 3) (md5 (current-buffer))))))
 (let ((coding-system-for-write nil) (select-safe-coding-system-function nil))
   (with-temp-buffer (set-buffer-multibyte nil) (insert (unibyte-string 233 88))
     (md5 (current-buffer) nil nil 'invalid-coding)))
 (let ((comp-running-batch-compilation t) (comp-no-spawn nil))
   (let ((f (native-compile '(lambda (text) (md5 text)))))
     (list (native-comp-function-p f) (funcall f "abc"))))))"#,
        r#"(("900150983cd24fb0d6963f7d28e17f72" "5b843fe5ddd9a9f224c494d9632ab2c4" "d78276f56f8ec8d4f8cca375e4534366" "02129bb861061d1a052c592e2dc6b383" "d91dcdf22c90ea773491c6e29245d406" (coding-system-error invalid-coding) "5b843fe5ddd9a9f224c494d9632ab2c4" (args-out-of-range "abc" 2 1)) sentinel ("66ddcd97cfdeabb2f6fb8a999b4bc76f" (coding-system-error invalid-coding) "197a44322718570659ef9da515ff2d51" "66ddcd97cfdeabb2f6fb8a999b4bc76f") "d91dcdf22c90ea773491c6e29245d406" (t "900150983cd24fb0d6963f7d28e17f72"))"#,
        "md5 native and interpreted contract",
    );
}

#[test]
fn native_cleanup_can_exit_to_a_handler_inside_the_original_target() {
    // eval.c:unwind_to_catch leaves each inner handler active while
    // executing its cleanup, including when the original exit bypasses it.
    assert_oracle_contract_matches_interpreter(
        r#"(progn
(require 'comp)
(let ((comp-no-spawn nil) (comp-running-batch-compilation t))
 (let ((function
  (native-compile
   '(lambda ()
      (list
       (catch 'outer
        (catch 'inner
         (unwind-protect (throw 'outer 'body)
          (throw 'inner 'cleanup))))
       (catch 'outer
        (condition-case nil
         (unwind-protect (throw 'outer 'body)
          (error "cleanup"))
         (error 'handled))))))))
  (list (native-comp-function-p function) (funcall function)))))"#,
        "(t (cleanup handled))",
        "native cleanup handler ordering",
    );
}

#[test]
fn native_cleanup_retires_popped_handlers_before_interpreted_calls() {
    assert_oracle_contract_matches_interpreter(
        r#"(progn (require 'comp)
(let ((comp-no-spawn nil) (comp-running-batch-compilation t))
 (let ((function (native-compile
   '(lambda (body cleanup)
      (unwind-protect
          (catch 'defer (funcall body))
        (funcall cleanup)))))
       (cleanup (eval '(lambda () (throw 'defer 'cleanup)) t)))
  (list (native-comp-function-p function)
        (native-comp-function-p cleanup)
        (catch 'defer (funcall function (eval '(lambda () (throw 'defer 'body)) t) cleanup))))))"#,
        "(t nil cleanup)",
        "native cleanup with an interpreted throw",
    );
}

#[test]
fn primitive_minimum_arities_match_gnu() {
    assert_oracle_contract_matches_interpreter(
        r#"(progn (require 'comp)
          (let* ((comp-no-spawn nil) (comp-running-batch-compilation t)
                 (cases '((redirect-debugging-output) (set-window-margins nil)
                          (move-to-window-line) (self-insert-command)
                          (get-buffer-process) (selected-window nil)))
                 (native (native-compile
                          '(lambda (call)
                             (condition-case e (apply (car call) (cdr call)) (error e))))))
            (list (native-comp-function-p native)
                  (mapcar (lambda (call)
                            (condition-case e (apply (car call) (cdr call)) (error e))) cases)
                  (mapcar (lambda (call) (condition-case e (eval call) (error e))) cases)
                  (mapcar native cases))))"#,
        "(t ((wrong-number-of-arguments #<subr redirect-debugging-output> 0) (wrong-number-of-arguments #<subr set-window-margins> 1) (wrong-number-of-arguments #<subr move-to-window-line> 0) (wrong-number-of-arguments #<subr self-insert-command> 0) (wrong-number-of-arguments #<subr get-buffer-process> 0) (wrong-number-of-arguments #<subr selected-window> 1)) ((wrong-number-of-arguments redirect-debugging-output 0) (wrong-number-of-arguments set-window-margins 1) (wrong-number-of-arguments move-to-window-line 0) (wrong-number-of-arguments self-insert-command 0) (wrong-number-of-arguments get-buffer-process 0) (wrong-number-of-arguments selected-window 1)) ((wrong-number-of-arguments #<subr redirect-debugging-output> 0) (wrong-number-of-arguments #<subr set-window-margins> 1) (wrong-number-of-arguments #<subr move-to-window-line> 0) (wrong-number-of-arguments #<subr self-insert-command> 0) (wrong-number-of-arguments #<subr get-buffer-process> 0) (wrong-number-of-arguments #<subr selected-window> 1)))",
        "source, funcall, and native primitive arities",
    );
}

#[test]
fn native_comp_source_names_hash_canonical_paths_and_real_contents() {
    let root = std::env::temp_dir().join(format!(
        "emaxx-native-comp-names-{}",
        SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .expect("system time after epoch")
            .as_nanos()
    ));
    fs::create_dir_all(&root).expect("create native-comp name fixture");
    let source = root.join("sample.el");
    let compressed = root.join("sample.el.gz");
    let missing = root.join("missing.el");
    let base = root.join("eln-cache");
    let contents = b"(message \"native source\")\n";
    fs::write(&source, contents).expect("write native-comp source fixture");
    let mut encoder = flate2::write::GzEncoder::new(
        fs::File::create(&compressed).expect("create compressed native-comp source"),
        flate2::Compression::default(),
    );
    encoder
        .write_all(contents)
        .expect("compress native-comp source");
    encoder.finish().expect("finish compressed source");

    let relative_name = |path: &Path| {
        let canonical = fs::canonicalize(path).expect("canonicalize native-comp source");
        let canonical = canonical.display().to_string();
        let hash_path = canonical.strip_suffix(".gz").unwrap_or(&canonical);
        let path_hash = crate::lisp::md5::md5_hex(hash_path.as_bytes());
        let content_hash = crate::lisp::md5::md5_hex(contents);
        format!("sample-{}-{}.eln", &path_hash[..8], &content_hash[..8])
    };
    let source_relative = relative_name(&source);
    let compressed_relative = relative_name(&compressed);
    let absolute = base.join("test-abi").join(&source_relative);
    let program = format!(
        r#"
        (let ((comp-native-version-dir "test-abi"))
          (list
           (comp-el-to-eln-rel-filename {source:?})
           (comp-el-to-eln-rel-filename {compressed:?})
           (comp-el-to-eln-filename {source:?} {base:?})
           (condition-case error-data
               (comp-el-to-eln-rel-filename 42)
             (error error-data))
           (condition-case error-data
               (comp-el-to-eln-rel-filename {missing:?})
             (error error-data))))"#,
        source = source.display().to_string(),
        compressed = compressed.display().to_string(),
        base = base.display().to_string(),
        missing = missing.display().to_string(),
    );
    let expected = format!(
        "({source_relative:?} {compressed_relative:?} {absolute:?} \
         (wrong-type-argument stringp 42) (file-missing {missing:?}))",
        absolute = absolute.display().to_string(),
        missing = missing.display().to_string(),
    );
    assert_upstream_primitive_contract(&format!("(prin1 {program})"), &expected);

    let mut interp = Interpreter::new();
    let mut env = crate::lisp::types::Env::new();
    let form = Reader::new(&program)
        .read()
        .expect("native-comp filename contract should parse")
        .expect("native-comp filename contract should contain a form");
    let actual = interp
        .eval(&form, &mut env)
        .expect("native-comp filename contract should evaluate");
    let expected_value = Reader::new(&expected)
        .read()
        .expect("native-comp expected filenames should parse")
        .expect("native-comp expected filenames should exist");
    assert!(
        values_equal(&interp, &actual, &expected_value).expect("equal"),
        "native-comp filename result differs from GNU:\nactual: {actual:?}\nexpected: {expected_value:?}"
    );

    fs::remove_dir_all(root).expect("remove native-comp name fixture");
}

#[test]
fn native_comp_context_and_loader_entry_points_follow_comp_c() {
    // comp.c: `comp--init-ctxt' returns t and `comp--release-ctxt' t;
    // `native-elisp-load' of a file that is not a native object fails with
    // dlerror's text, and of a missing file with "file does not exists".
    // (The remaining `comp--*' entry points abort GNU when called without
    // a compilation context, so they are not contracted here.)
    let program = r#"
        (list (comp--release-ctxt)
              (comp--init-ctxt)
              (comp--release-ctxt)
              (condition-case e (native-elisp-load (expand-file-name "lisp/subr.el" source-directory))
                (error (list (car e) (file-name-nondirectory (cadr e)) (if (eq system-type 'darwin)
                    (not (null (string-match-p "not valid mach-o file" (caddr e))))
                  (string-suffix-p "invalid ELF header" (caddr e))))))
              (condition-case e (native-elisp-load "/nonexistent/emaxx-x.eln") (error e)))"#;
    assert_oracle_contract_matches_interpreter(
        program,
        r#"(t t t (native-lisp-load-failed "subr.el" t) (native-lisp-load-failed "file does not exists" "/nonexistent/emaxx-x.eln"))"#,
        "native-comp context and loader",
    );
}

#[test]
fn handler_bind_handlers_run_once_with_the_signaling_frame_innermost() {
    // eval.c signal_or_quit runs `handler-bind' handlers once per signal,
    // from `signal' itself, so `mapbacktrace' inside a handler sees the
    // signaling frame innermost: the unevaluated call for a void function
    // (eval_sub records it before resolving the function cell), the
    // unevaluated `let' for a void variable, the callee frame for a wrong
    // arity (Ffuncall records it before funcall_lambda checks), the
    // in-progress `list' and `car' frames for an error inside an argument.
    // Emaxx dispatches at the innermost frame boundary that sees the error
    // and remembers the object, so the frames it unwinds through afterwards
    // run no handler again; before that, an error the evaluator itself
    // signaled inside interpreted lambdas reached no handler at all, and one
    // raised in a primitive ran the handler again at every enclosing
    // primitive frame (`debug-early--handler' printed the batch backtrace
    // once per frame).
    let program = r#"
        (let* ((frames-of (lambda ()
                            (let (acc)
                              (mapbacktrace (lambda (evald f args _)
                                              (push (list evald (if (symbolp f) f 'fn) (length args)) acc))
                                            'emaxx-hb-handler)
                              (nreverse acc))))
               (upto (lambda (frames)
                       (let ((end (seq-position frames 'handler-bind-1
                                                (lambda (fr sym) (eq (nth 1 fr) sym)))))
                         (and end (seq-subseq frames 1 (1+ end))))))
               (n 0) frames
               (probe (lambda (thunk)
                        (setq n 0 frames nil)
                        (condition-case nil
                            (handler-bind ((error #'emaxx-hb-handler))
                              (funcall thunk))
                          (error (list n (funcall upto frames)))))))
          (defalias 'emaxx-hb-handler
            (lambda (_) (setq n (1+ n)) (setq frames (funcall frames-of))))
          (defalias 'emaxx-hb-one-arg (lambda (a) a))
          (list (funcall probe (lambda () (let ((x 1)) (car x))))
                (funcall probe (lambda () (undefined-fn-xyz 1 2)))
                (funcall probe (lambda () (let ((y 2)) undefined-var-xyz)))
                (funcall probe (lambda () (emaxx-hb-one-arg)))
                (funcall probe (lambda () (signal 'wrong-type-argument (list 'listp 1))))
                (funcall probe (lambda () (car (list undefined-var-xyz))))))"#;
    assert_oracle_contract_matches_interpreter(
        program,
        "((1 ((t car 1) (nil let 2) (t fn 0) (t funcall 1) (t fn 0) (t handler-bind-1 3))) \
         (1 ((nil undefined-fn-xyz 2) (t fn 0) (t funcall 1) (t fn 0) (t handler-bind-1 3))) \
         (1 ((nil let 2) (t fn 0) (t funcall 1) (t fn 0) (t handler-bind-1 3))) \
         (1 ((t emaxx-hb-one-arg 0) (t fn 0) (t funcall 1) (t fn 0) (t handler-bind-1 3))) \
         (1 ((t signal 2) (t fn 0) (t funcall 1) (t fn 0) (t handler-bind-1 3))) \
         (1 ((nil list 1) (nil car 1) (t fn 0) (t funcall 1) (t fn 0) (t handler-bind-1 3))))",
        "handler-bind dispatch",
    );
}

#[test]
fn json_serialize_treats_a_vector_as_an_array() {
    // json.c lisp_to_json: a vector is a JSON array, a list an object
    // (plist or alist) whose keys must be symbols.  The merged vector
    // representation reached `json-serialize' as `Value::Vector' while the
    // serializer only knew the older `vector-literal' list, so every
    // vector was rejected as `(wrong-type-argument json-value "vector")'
    // and jsonrpc could not send a request.
    // (The JSON strings' double quotes become apostrophes so the expected
    // text needs no escaping.)
    let program = r#"
        (let ((q (lambda (text) (string-replace "\"" "'" text))))
          (require 'json)
          (list (funcall q (json-serialize [1 2]))
                (funcall q (json-serialize (list :a [1 "x"] :b [])))
                (funcall q (json-serialize (vector)))
                (funcall q (json-serialize [:null :false t]))
                (funcall q (json-serialize (list :a (vector "x" 1.5 [nil]))))
                (json-parse-string "[1,[2]]")
                (json-parse-string "[1,[2]]" :array-type 'list)
                (funcall q (json-encode [1 2]))
                (condition-case e (json-serialize (list :a (list 1 2))) (error e))
                (condition-case e (json-serialize [(1 2)]) (error e))
                (funcall q (json-serialize (list (cons :a 1) (cons 'b 2))))
                (funcall q (json-serialize (list :a 1 :a 2 'a 3)))
                (condition-case e (json-serialize (list :a)) (error e))
                (condition-case e (json-serialize (cons (cons 'a 1) 2)) (error e))
                (funcall q (json-serialize (list (cons 'a nil) (cons 'b (list :c 1)))))
                (condition-case e (json-serialize '#1=((a . 1) . #1#)) (error (car e)))
                (condition-case e (json-serialize '#2=(:a 1 . #2#)) (error (car e)))
                (condition-case e (json-serialize '(abc)) (error e))
                (condition-case e (json-serialize '((a 1))) (error e))
                (condition-case e (json-serialize '((a . 1) . b)) (error e))
                (funcall q (json-serialize '((a . 1) (b . 2) (a . 3))))))"#;
    assert_oracle_contract_matches_interpreter(
        program,
        r#"("[1,2]" "{'a':[1,'x'],'b':[]}" "[]" "[null,false,true]" "{'a':['x',1.5,[{}]]}" [1 [2]] (1 (2)) "[1,2]" (wrong-type-argument symbolp 1) (wrong-type-argument symbolp 1) "{':a':1,'b':2}" "{'a':1,'a':3}" (wrong-type-argument consp nil) (wrong-type-argument listp ((a . 1) . 2)) "{'a':{},'b':{'c':1}}" circular-list circular-list (wrong-type-argument consp nil) (wrong-type-argument consp nil) (wrong-type-argument listp ((a . 1) . b)) "{'a':1,'b':2}")"#,
        "json-serialize vectors and object keys",
    );
}

#[test]
fn ash_with_a_bignum_count_follows_data_c() {
    // data.c Fash: a COUNT outside the fixnum range shifts 0 to 0, shifts
    // any other value to -1 or 0 by its sign when negative, and signals
    // `overflow-error' when positive; subr.el's `lsh' rides on that.  With
    // the merged 62-bit fixnum range `(* 2 most-positive-fixnum)' is a
    // bignum, and Emaxx rejected it as `number-or-marker-p'
    // (data-tests-ash-lsh).
    let program = r#"
        (list (ash 0 (* 2 most-positive-fixnum))
              (ash 1000 (* 2 most-negative-fixnum))
              (ash -1000 (* 2 most-negative-fixnum))
              (ash (* 2 most-negative-fixnum) (* 2 most-negative-fixnum))
              (ash 0 (* 2 most-negative-fixnum))
              (condition-case e (ash 1 (* 2 most-positive-fixnum)) (error e))
              (condition-case e (ash -1 (* 2 most-positive-fixnum)) (error e))
              (= (ash most-negative-fixnum 1) (* most-negative-fixnum 2))
              (= (ash (* 2 most-negative-fixnum) -1) most-negative-fixnum)
              (with-suppressed-warnings ((suspicious lsh))
                (list (= (lsh most-negative-fixnum 1) (* most-negative-fixnum 2))
                      (= (lsh -1 -1) most-positive-fixnum)
                      (condition-case e (lsh (1- most-negative-fixnum) -1) (error e)))))"#;
    assert_oracle_contract_matches_interpreter(
        program,
        "(0 0 -1 -1 0 (overflow-error) (overflow-error) t t (t t (args-out-of-range -2305843009213693953 -1)))",
        "ash bignum count",
    );
}

#[test]
fn where_is_internal_runs_menu_item_filters_only_for_verified_matches() {
    // keymap.c where_is_internal_1 reads bindings with get_keyelt
    // (binding, 0): a menu-item's `:filter' never runs during the scan.
    // Fwhere_is_internal then verifies candidates shortest first with
    // shadow_lookup (which does run filters) and, with FIRSTONLY, returns
    // the first all-ASCII sequence before touching the rest.  Emaxx ran
    // every filter while scanning, so `substitute-command-keys' during
    // startup evaluated tab-bar's filter and left a modified
    // " *string-pixel-width*" buffer behind.
    let program = r#"
        (progn
          (defvar emaxx-filter-calls 0)
          (defun emaxx-filter (x) (setq emaxx-filter-calls (1+ emaxx-filter-calls)) x)
          (define-key global-map [emaxx-probe] (list 'menu-item "p" 'ignore :filter #'emaxx-filter))
          (define-key global-map [emaxx-probe-2] (list 'menu-item "q" 'forward-char :filter #'emaxx-filter))
          (list (where-is-internal 'forward-char nil t)
                emaxx-filter-calls
                (progn (substitute-command-keys "\\[forward-char]") emaxx-filter-calls)
                (progn (where-is-internal 'ignore (list global-map)) emaxx-filter-calls)
                (get-buffer " *string-pixel-width*")))"#;
    assert_oracle_contract_matches_interpreter(
        program,
        "([6] 0 0 1 nil)",
        "where-is-internal menu-item filters",
    );
}

#[test]
fn current_time_and_a_nil_time_convert_form_follow_current_time_list() {
    // timefns.c make_lisp_time and Ftime_convert: under `current-time-list'
    // (t by default) `current-time' and a nil FORM answer the old-style
    // (HIGH LOW USEC PSEC) list; with it nil they answer (TICKS . HZ),
    // `current-time' always at 1000000000 Hz.  Emaxx answered the pair
    // regardless, so startup.el's `(setq before-init-time (current-time))'
    // left a pair where GNU has a list.  What `time-convert' answers for a
    // rational under a nil `current-time-list' is row 167 of the ledger
    // (GNU keeps the input's HZ, Emaxx reduces the fraction).
    let program = r#"
        (list (type-of (current-time)) (length (current-time))
              (time-convert 1.5 nil) (time-convert '(1 2 3 4) nil) (time-convert 100 nil)
              (time-convert '(1 . 3) nil)
              (let ((current-time-list nil))
                (list (cdr (current-time)) (time-convert 100 nil) (time-convert 1 t)
                      (consp (time-convert nil nil)) (cdr (time-convert nil nil)))))"#;
    assert_oracle_contract_matches_interpreter(
        program,
        "(cons 4 (0 1 500000 0) (1 2 3 4) (0 100 0 0) (0 0 333333 333333) (1000000000 (100 . 1) (1 . 1) t 1000000000))",
        "current-time-list forms",
    );
}

#[test]
fn current_cpu_time_returns_a_readable_tick_pair_in_both_time_modes() {
    assert_oracle_contract_matches_interpreter(
        r#"(mapcar (lambda (current-time-list)
                     (let ((cpu (current-cpu-time)))
                       (list (consp cpu) (integerp (car cpu))
                             (integerp (cdr cpu)) (> (cdr cpu) 0)
                             (floatp (float-time cpu)))))
                   '(nil t))"#,
        "((t t t t t) (t t t t t))",
        "current-cpu-time tick pair",
    );
}

#[test]
fn symbol_fast_paths_preserve_nil_and_t_identity() {
    // fns.c:Fget compares property keys with EQ. lread.c:Fmapatoms hands
    // the actual obarray symbols to the callback, including false nil.
    assert_oracle_contract_matches_interpreter(
        r#"(let ((symbol (make-symbol "symbol-fast-paths")))
             (put symbol nil 11)
             (put symbol t 22)
             (list (get symbol nil) (get symbol t)
                   (let (seen)
                     (mapatoms (lambda (s)
                                 (when (string= (symbol-name s) "nil")
                                   (push (if s 'wrong 'ok) seen))))
                     seen)
                   (let (seen)
                     (mapatoms (lambda (s)
                                 (when (string= (symbol-name s) "nil")
                                   (push (if s 'wrong 'ok) seen)))
                               obarray)
                     seen)))"#,
        "(11 22 (ok) (ok))",
        "symbol fast paths preserve nil and t",
    );
}

#[test]
fn garbage_collect_maybe_reads_the_counters_the_last_collection_left() {
    // alloc.c:Fgarbage_collect_maybe compares `since_gc' with the
    // `gc_threshold' the last collection computed; only maybe_garbage_collect
    // retunes that threshold from `gc-cons-threshold'.  A let-bound small
    // threshold therefore changes nothing until the counter goes negative
    // against the old threshold, and `(identity nil)' in between does not
    // collect either.  garbage_collect runs `post-gc-hook' once.  The merged
    // port retuned the threshold inside Fgarbage_collect_maybe, so factor 1
    // answered t whenever consing since the last collection exceeded the
    // let-bound value; and the ordinary interpreter never collected on its
    // own, so `since_gc' grew without bound.  The large factor keeps the
    // positive cases clear of the live-heap size, which differs between
    // the editors and feeds the threshold through `gc-cons-percentage'.
    let program = r#"
        (list (let ((gc-cons-threshold 10000)) (make-list 2000 nil) (garbage-collect-maybe 100000))
              (let ((gc-cons-threshold 10000)) (make-list 2000 nil) (garbage-collect-maybe 1))
              (progn (garbage-collect) (garbage-collect-maybe 1))
              (let ((gc-cons-threshold 10000)) (make-list 2000 nil) (identity nil)
                   (garbage-collect-maybe 100000))
              (let ((n 0))
                (let ((post-gc-hook (list (lambda () (setq n (1+ n))))))
                  (let ((gc-cons-threshold 10000))
                    (make-list 2000 nil) (identity nil) (make-list 2000 nil) (identity nil)
                    (garbage-collect)))
                n))"#;
    assert_oracle_contract_matches_interpreter(program, "(t nil nil t 1)", "garbage-collect-maybe");
}

#[test]
fn interning_after_unintern_makes_a_fresh_symbol_in_a_private_obarray() {
    // lread.c:intern_driver allocates a new symbol on every obarray miss;
    // Funintern only drops the old one from the table, which keeps its
    // cells.  Emaxx keyed a private obarray's symbol by its name, so the
    // re-interned name was the old symbol, still bound.  Semantic's
    // preprocessor pushes a macro argument (`intern' + `set'), pops it
    // (`unintern') and pushes it again on the next expansion; the second
    // push then saw a bound symbol, treated it as an outer binding to
    // stack, and the argument name survived as a macro (six
    // semantic-utest-ia completions).
    let program = r#"
        (let* ((ob (obarray-make 13)) (s1 (intern "alias" ob)))
          (set s1 5)
          (unintern "alias" ob)
          (let ((s2 (intern "alias" ob)))
            (list (eq s1 s2) (boundp s2) (boundp s1) (symbol-value s1)
                  (progn (set s2 7) (list (symbol-value s1) (symbol-value s2)))
                  (equal (symbol-name s1) (symbol-name s2))
                  (eq (intern-soft "alias" ob) s2)
                  (unintern s1 ob)
                  (eq (intern-soft "alias" ob) s2))))"#;
    assert_oracle_contract_matches_interpreter(
        program,
        "(nil nil t 5 (5 7) t t nil t)",
        "intern after unintern",
    );
}

#[test]
fn variable_cells_follow_data_c() {
    // data.c: find_symbol_value dispatches on the symbol's redirect
    // (PLAINVAL, VARALIAS, LOCALIZED) and set_internal writes through the
    // same redirect; Fsymbol_value and eval_sub signal void-variable with
    // the symbol they were handed, not with the end of an alias chain;
    // two `make-symbol's of one name are two variables; a non-special
    // uninterned symbol binds lexically under lexical-binding.  Emaxx now
    // keeps value, redirect and flags in one per-symbol cell, and this
    // pins the observable contract of that storage against the oracle.
    let program = r#"
        (let ((results nil))
          (push (progn (defvar zz-cell-target 1)
                       (defvaralias 'zz-cell-alias 'zz-cell-target)
                       (list (symbol-value 'zz-cell-alias)
                             (progn (set 'zz-cell-alias 2) zz-cell-target)
                             (indirect-variable 'zz-cell-alias)
                             (special-variable-p 'zz-cell-alias)
                             (boundp 'zz-cell-alias)
                             (default-boundp 'zz-cell-alias)))
                results)
          (push (list (progn (defvaralias 'zz-cell-alias2 'zz-cell-unbound) (boundp 'zz-cell-alias2))
                      (condition-case err (symbol-value 'zz-cell-alias2) (void-variable (cadr err)))
                      (progn (set 'zz-cell-unbound 5) (symbol-value 'zz-cell-alias2))
                      (progn (makunbound 'zz-cell-alias2) (boundp 'zz-cell-unbound)))
                results)
          (push (condition-case err
                    (progn (defvaralias 'zz-cyc-a 'zz-cyc-b) (defvaralias 'zz-cyc-b 'zz-cyc-a))
                  (error err))
                results)
          (push (let ((s1 (make-symbol "zz-u")) (s2 (make-symbol "zz-u")))
                  (set s1 10)
                  (list (symbol-value s1)
                        (boundp s2)
                        (eval `(let ((,s1 20)) (symbol-value ',s1)) t)
                        (eval `(let ((,s1 20)) (symbol-value ',s1)) nil)
                        (symbol-value s1)
                        (default-value s1)
                        (special-variable-p s1)
                        (progn (makunbound s1) (boundp s1))))
                results)
          (push (with-temp-buffer
                  (defvar zz-cell-local 'global)
                  (make-local-variable 'zz-cell-local)
                  (setq zz-cell-local 'local)
                  (list zz-cell-local
                        (default-value 'zz-cell-local)
                        (with-temp-buffer zz-cell-local)
                        (local-variable-p 'zz-cell-local)
                        (progn (kill-local-variable 'zz-cell-local) zz-cell-local)
                        (local-variable-p 'zz-cell-local)))
                results)
          (push (progn (makunbound 'zz-cell-target)
                       (list (boundp 'zz-cell-target)
                             (boundp 'zz-cell-alias)
                             (special-variable-p 'zz-cell-target)
                             (condition-case err zz-cell-alias (void-variable (cadr err)))))
                results)
          (push (let ((f (byte-compile (lambda () (setq zz-cell-target 7)
                                         (list zz-cell-target (symbol-value 'zz-cell-alias))))))
                  (funcall f))
                results)
          (nreverse results))"#;
    assert_oracle_contract_matches_interpreter(
        program,
        "((1 2 zz-cell-target t t t) (nil zz-cell-alias2 5 nil) \
         (cyclic-variable-indirection zz-cyc-a) (10 nil 10 20 10 10 nil nil) \
         (local global global t global nil) (nil nil t zz-cell-alias) (7 7))",
        "variable cells",
    );
}

#[test]
fn forwarded_c_variables_follow_store_symval_forwarding() {
    // data.c:store_symval_forwarding by slot kind: Lisp_Fwd_Bool keeps
    // `!NILP (newval)' on every store path, Lisp_Fwd_Int is CHECK_INTEGER
    // plus an intmax_t range check (`overflow-error'), and set_internal
    // storing Qunbound turns the symbol plain: `boundp' nil, a later store
    // keeps any object.  Fboundp of a still-forwarded slot is t.
    let program = r#"
        (list (progn (setq auto-window-vscroll 5) auto-window-vscroll)
              (progn (setq print-escape-newlines 'yes)
                     (list print-escape-newlines (let ((print-escape-newlines 'x)) print-escape-newlines)))
              (condition-case e (setq undo-limit 1.5) (error e))
              (condition-case e (setq undo-limit (expt 2 70)) (error e))
              (progn (setq undo-limit 5) undo-limit)
              (progn (makunbound 'print-length) (list (boundp 'print-length) (progn (setq print-length 'z) print-length)))
              (progn (makunbound 'print-escape-newlines) (setq print-escape-newlines 5) print-escape-newlines)
              (boundp 'undo-limit)
              (progn (makunbound 'undo-limit) (list (boundp 'undo-limit) (progn (setq undo-limit 2.5) undo-limit)))
              (special-variable-p 'undo-limit)
              (progn (defvar zz-plain 1) (setq zz-plain 'x)
                     (list (boundp 'zz-plain) (progn (makunbound 'zz-plain) (boundp 'zz-plain)))))"#;
    assert_oracle_contract_matches_interpreter(
        program,
        "(t (t t) (wrong-type-argument integerp 1.5) (overflow-error 1180591620717411303424) 5 \
         (nil z) 5 t (nil 2.5) t (t nil))",
        "forwarded stores",
    );
}

