#[test]
fn uninterned_symbols_are_reached_by_object_not_by_name() {
    // alloc.c marks the symbol object: of two uninterned symbols with one
    // name, the unreferenced one is collected while the other, referenced,
    // keeps its weak-key entry.  The collector's reached-symbol set is by
    // symbol id.
    let program = r#"
        (let* ((table (make-hash-table :test 'eq :weakness 'key))
               (live (make-symbol "same")))
          (puthash (make-symbol "same") 1 table)
          (puthash live 2 table)
          (garbage-collect)
          (garbage-collect)
          (list (hash-table-count table) (gethash live table)))"#;
    assert_oracle_contract_matches_interpreter(program, "(1 2)", "uninterned symbol reach");
}

#[test]
fn markers_the_collector_reaches_survive_and_the_rest_are_unchained() {
    // alloc.c's sweep unchains a marker nothing references: it stops being
    // adjusted by edits.  Every marker C keeps a slot for is reached from
    // that slot -- the buffer's mark, a process's mark, the excursion and
    // restriction markers on the specpdl, the undo list's -- and one held
    // in a Lisp variable from the variable.  The oracle's values (the
    // buffer prints as killed: the list is printed after `kill-buffer').
    let program = r#"
        (let* ((b (generate-new-buffer "markers"))
               (kept (with-current-buffer b (insert "0123456789") (copy-marker 4)))
               (p (start-process "markers-cat" b "cat")))
          (with-current-buffer b
            (set-marker (process-mark p) 6)
            (set-mark 3)
            (let ((i 0)) (while (< i 500) (copy-marker 5) (setq i (1+ i))))
            (buffer-enable-undo)
            (delete-region 7 9)
            (list
             (save-excursion
               (goto-char 8)
               (garbage-collect)
               (goto-char 1) (insert "ab")
               (point))
             (save-restriction
               (narrow-to-region 3 7)
               (garbage-collect)
               (goto-char (point-min)) (insert "xy")
               (list (point-min) (point-max)))
             (progn (garbage-collect)
                    (goto-char 1) (insert "Q")
                    (list (marker-position kept) (marker-position (process-mark p))
                          (marker-position (mark-marker)) (marker-buffer kept)
                          (let ((entries (seq-filter (lambda (e) (and (consp e) (markerp (car e))))
                                                     buffer-undo-list)))
                            (mapcar (lambda (e) (marker-position (car e))) entries))))
             (progn (delete-process p) (kill-buffer b) (marker-buffer kept)))))"#;
    assert_oracle_contract_matches_interpreter(
        program,
        "(3 (3 9) (9 11 8 #<killed buffer> nil) nil)",
        "markers across a collection",
    );
}

#[test]
fn labeled_restriction_bounds_survive_a_collection() {
    // editfns.c keeps a labeled restriction's bounds as markers in the
    // buffer's `labeled_restrictions' alist, which the mark phase reaches.
    // Found by the audit of the marker sweep: the interpreter's list of
    // active labeled restrictions marked its labels but not its bound
    // markers, so a collection inside `with-restriction' detached them
    // and the insertions that followed left the restriction where it
    // was.  The oracle's values: the end bound advances past the
    // insertion at its end, `widen' inside the restriction keeps it,
    // `without-restriction' lifts it, `narrow-to-region' inside it
    // clamps to it.
    let program = r#"(with-temp-buffer
         (insert "0123456789")
         (with-restriction 3 7 :label 'x
           (garbage-collect)
           (goto-char (point-min))
           (insert "ab")
           (goto-char (point-max))
           (insert "cd")
           (widen)
           (list (point-min) (point-max) (buffer-string)
                 (without-restriction :label 'x (list (point-min) (point-max)))
                 (progn (narrow-to-region 2 9) (list (point-min) (point-max))))))"#;
    assert_oracle_contract_matches_interpreter(
        program,
        r#"(3 9 "ab2345" (1 15) (3 9))"#,
        "labeled restriction across a collection",
    );
}

#[test]
fn unreached_markers_leave_their_buffers_edit_walk() {
    // 500 markers made and dropped: after a collection they are detached,
    // so an insertion adjusts only the markers still reachable (the kept
    // one and the buffer's mark), where before every edit walked the
    // dropped ones too.
    let mut interp = crate::test_support::initialized_gnu_early_lisp_interpreter();
    let mut env = crate::lisp::types::Env::new();
    let form = Reader::new(
        r#"(with-current-buffer (get-buffer-create "walk")
             (insert "0123456789")
             (set-marker (mark-marker) 3)
             (let ((i 0)) (while (< i 500) (copy-marker 5) (setq i (1+ i))))
             (setq walk-kept (copy-marker 7)))"#,
    )
    .read_all()
    .expect("read the marker walk contract")
    .remove(0);
    interp.eval(&form, &mut env).expect("make the markers");
    let before = interp.attached_marker_count();
    assert!(before >= 502, "attached before the collection: {before}");
    let collect = Reader::new(
        r#"(progn (garbage-collect)
                  (with-current-buffer "walk" (goto-char 1) (insert "ab") (marker-position walk-kept)))"#,
    )
    .read_all()
    .expect("read the collection form")
    .remove(0);
    let position = interp.eval(&collect, &mut env).expect("collect and edit");
    assert_eq!(position, Value::Integer(9));
    let after = interp.attached_marker_count();
    assert!(
        after < before && after <= before - 500,
        "attached after the collection: {after} (before {before})"
    );
}

#[test]
fn time_values_follow_timefns_c() {
    // timefns.c keeps (TICKS . HZ) as given (no reduction), decodes a
    // (HI LO US PS) list on its own clock (1, 10^6 or 10^12 by length),
    // scales a float by the power of two that makes it exact, and
    // time_arith keeps a common clock, else combines over the lcm with
    // gcd normalization and the rescale that keeps the result at least
    // as precise as either operand; the result is an integer at HZ 1,
    // the list form under `current-time-list' for list operands with an
    // exact list form, else the pair.  The oracle's values.
    let program = r#"(list (time-convert '(2 . 10) t) (time-convert '(4 . 8) t) (time-convert '(0 . 10) t)
        (time-convert 5 t) (time-convert '(1 2 3) t) (time-convert '(1 2 3 4) t) (time-convert '(1 2) t)
        (time-add '(1 . 10) '(1 . 10)) (time-add '(1 . 4) '(1 . 6)) (time-add '(1 . 6) '(1 . 3))
        (time-subtract '(3 . 6) '(1 . 6)) (time-subtract '(1 . 6) '(1 . 3))
        (time-equal-p '(1 . 2) '(2 . 4)) (time-less-p '(1 . 3) '(1 . 2))
        (time-convert '(3 . 4) 'integer) (time-convert '(6 . 4) 100) (float-time '(1 . 3))
        (time-convert 1.5 t) (time-convert '(2 . 10) 'list) (time-add 1 '(1 . 2)) (time-add '(0 . 10) '(0 . 10))
        (time-add '(1 2) '(3 4)) (time-add '(1 2 3) '(0 0 1))
        (let ((current-time-list nil)) (time-add '(1 2 3) '(0 0 1)))
        (time-add '(1 2 3 4) '(1 . 2)) (time-subtract '(1 2) 1) (time-convert '(1 2 3) 'list)
        (time-equal-p '(1 2) 65538) (time-less-p 1.5 '(3 . 2)) (time-add 1.5 1.5)
        (time-convert 0.0 t) (time-convert -1.5 t)
        (consp (time-convert nil t)) (= (cdr (time-convert nil t)) 1000000000))"#;
    assert_oracle_contract_matches_interpreter(
        program,
        "((2 . 10) (4 . 8) (0 . 10) (5 . 1) (65538000003 . 1000000) (65538000003000004 . 1000000000000) \
         (65538 . 1) (2 . 10) (5 . 12) (2 . 4) (2 . 6) (-1 . 6) t t 0 (150 . 100) 0.3333333333333333 \
         (6755399441055744 . 4503599627370496) (0 0 200000 0) (3 . 2) (0 . 10) 262150 (1 2 4 0) \
         (65538000004 . 1000000) (16384625000750001 . 250000000000) 65537 (1 2 3 0) t nil \
         (13510798882111488 . 4503599627370496) (0 . 1) (-6755399441055744 . 4503599627370496) t t)",
        "time values",
    );
}

#[test]
fn float_time_rounds_as_frac_to_double() {
    // timefns.c frac_to_double: the quotient scaled to 53 or 54 bits by
    // shifting the numerator or the denominator, truncating division,
    // the increment that makes truncation round to nearest even (with
    // the remainder as the sticky bit), and one scalbn.  Quotients over
    // 2^53, ties, subnormal results, and clocks that are no power of two
    // print as the oracle prints them.
    let program = r#"(mapcar (lambda (c) (float-time c))
        (list '(1000000004025 . 1000000000000) '(1 . 10000000000) '(-1 . 10000000000) '(1 . 3) '(2 . 3) '(-2 . 3) '(1 . 7) '(22 . 7) (cons (1+ (expt 2 53)) 1) (cons (+ 3 (expt 2 53)) 1) (cons (+ 5 (expt 2 53)) 1) (cons (- (+ 3 (expt 2 53))) 1) (cons (+ 3 (expt 2 54)) 1) (cons (+ 6 (expt 2 54)) 1) (cons (+ 5 (expt 2 54)) 3) (cons (expt 2 60) 3) (cons (1+ (expt 2 60)) 3) (cons (expt 10 30) 7) (cons 1 (expt 2 1074)) (cons 3 (expt 2 1074)) (cons -3 (expt 2 1074)) (cons 1 (expt 2 1075)) (cons 3 (expt 2 1075)) (cons 1 (expt 2 1076)) (cons (1+ (expt 2 53)) (expt 2 1074)) (cons (1+ (expt 2 53)) (expt 2 1073)) (cons 1 (expt 2 1022)) (cons (1- (expt 2 53)) (expt 2 1074)) (cons 1723456789123456789 1000000000) (cons -1723456789123456789 1000000000) (cons 1723456789123456789123 1000000000000) (cons (expt 2 1023) 1) (cons (* 3 (expt 2 1022)) 1) (cons (expt 3 700) (expt 2 100)) (cons (expt 3 700) (expt 3 699)) (cons (expt 3 700) (1+ (expt 3 699))) (cons 1 (expt 3 700)) (cons 9007199254740993 2) (cons 9007199254740995 2) (cons 27021597764222977 3) (cons 4503599627370497 1000000007) '(0 . 5) '(-0 . 5) (cons (- (expt 2 63)) 1) (cons (1- (expt 2 63)) 1) (cons (expt 2 63) (expt 2 10)) (cons (1+ (expt 2 63)) (expt 2 10))) )"#;
    assert_oracle_contract_matches_interpreter(
        program,
        "(1.000000004025 1e-10 -1e-10 0.3333333333333333 0.6666666666666666 -0.6666666666666666 0.14285714285714285 3.142857142857143 9007199254740992.0 9007199254740996.0 9007199254740996.0 -9007199254740996.0 18014398509481988.0 1.801439850948199e+16 6004799503160663.0 3.843071682022823e+17 3.843071682022823e+17 1.4285714285714285e+29 5e-324 1.5e-323 -1.5e-323 0.0 1e-323 0.0 4.450147717014403e-308 8.900295434028806e-308 2.2250738585072014e-308 4.4501477170144023e-308 1723456789.1234567 -1723456789.1234567 1723456789.1234567 8.98846567431158e+307 1.348269851146737e+308 7.61866253907264e+303 3.0 3.0 0.0 4503599627370496.0 4503599627370498.0 9007199254740992.0 4503599.5958453 0.0 0.0 -9.223372036854776e+18 9.223372036854776e+18 9007199254740992.0 9007199254740992.0)",
        "float-time rounding",
    );
}

#[test]
fn let_binding_lists_must_be_lists() {
    // eval.c Flet and FletX read the binding list with list_length and
    // FOR_EACH_TAIL: a vector (or any non-list) is wrong-type-argument
    // listp.  A vector, read as a sequence, bound its elements to nil
    // before (the Mac's frozen run: eval-tests--let--vector).  The
    // oracle's conditions.
    assert_oracle_contract_matches_interpreter(
        r#"(list (condition-case e (let [a]) (error e))
               (condition-case e (let* [a]) (error e))
               (condition-case e (let 1) (error e))
               (condition-case e (let "a") (error e)))"#,
        r#"((wrong-type-argument listp [a]) (wrong-type-argument listp [a]) (wrong-type-argument listp 1) (wrong-type-argument listp "a"))"#,
        "let binding lists",
    );
}

#[test]
fn set_file_times_keeps_the_whole_timestamp() {
    // fileio.c Fset_file_times: lisp_time_argument's timespec through
    // utimensat, to the nanosecond.  The seconds alone were set before,
    // so a file stamped with `current-time' fell a fraction of a second
    // behind the time the caller kept (multisession's file backend then
    // took its cached value over another Emacs's newer one).  The
    // oracle's value, read back with `file-attributes'.
    assert_oracle_contract_matches_interpreter(
        r#"(let ((file (make-temp-file "emaxx-file-times")))
             (set-file-times file '(27301 29776 232076 444000))
             (prog1 (file-attribute-modification-time (file-attributes file))
               (delete-file file)))"#,
        "(27301 29776 232076 444000)",
        "set-file-times precision",
    );
}

#[test]
fn buffer_searches_convert_offsets_through_the_rope() {
    // A multibyte buffer whose haystack is its own text converts the
    // engine's byte offsets through the rope (test builds compare every
    // conversion with the haystack index): point, match data, the
    // positions after forward and backward searches, and a search after
    // an insertion, all the oracle's.
    let program = r#"(with-temp-buffer
         (insert "αβγ abc δεζ\nημ xyz θι\n")
         (goto-char 3)
         (list (looking-at "γ \\(a\\)") (match-data t)
               (re-search-forward "δ\\(ε\\)" nil t) (match-beginning 1) (match-end 0) (point)
               (re-search-backward "β" nil t) (point)
               (progn (goto-char 1) (re-search-forward "^η\\(μ\\)" nil t)) (match-data t)
               (progn (goto-char 14) (looking-at "ημ \\(x\\)")) (match-data t)
               (progn (goto-char 1) (search-forward "θ" nil t))
               (progn (goto-char (point-max)) (re-search-backward "[αη]" nil t)) (point)
               (progn (goto-char 5) (insert "ω") (goto-char 6) (looking-at "abc δ")) (match-end 0)
               (progn (goto-char 1) (re-search-forward "ζ$" nil t)) (match-beginning 0)))"#;
    assert_oracle_contract_matches_interpreter(
        program,
        "(t (3 6 5 6 #<killed buffer>) 11 10 11 11 2 2 15 (13 15 14 15 #<killed buffer>) nil \
         (13 15 14 15 #<killed buffer>) 21 13 13 t 11 13 12)",
        "non-ASCII buffer searches",
    );
}

#[test]
fn finalizers_follow_alloc_c() {
    // alloc.c: Fmake_finalizer checks FUNCTIONP; print.c prints
    // `#<finalizer>'; garbage_collect queues every unreached finalizer
    // with a non-nil function before the weak-table sweep and runs them
    // once the collection is complete, in creation order, under
    // `inhibit-quit'; a finalizer still referenced does not run; one
    // reachable only from another finalizer's function still runs.  The
    // oracle's conservative stack scan decides WHICH later collection
    // dooms a released object, so the program only observes a finalizer
    // through collections that follow the release by two `garbage-collect'
    // calls, and the kept one's function writes a log no later group reads.
    let program = r#"
        (let ((log nil))
          (list (condition-case e (make-finalizer 3) (error e))
                (type-of (make-finalizer #'ignore))
                (prin1-to-string (make-finalizer #'ignore))
                (progn (make-finalizer (lambda () (push 'a log)))
                       (make-finalizer (lambda () (push 'b log)))
                       (garbage-collect) (garbage-collect) log)
                (let ((kept-log nil))
                  (let ((keep (make-finalizer (lambda () (push 'kept kept-log)))))
                    (garbage-collect) (list kept-log (type-of keep))))
                (let ((f2 nil))
                  (setq f2 (make-finalizer (lambda () (push 'inner log))))
                  (make-finalizer (lambda () (push (list 'outer (type-of f2)) log)))
                  (setq f2 nil)
                  (garbage-collect) (garbage-collect) log)))"#;
    assert_oracle_contract_matches_interpreter(
        program,
        "((wrong-type-argument functionp 3) finalizer \"#<finalizer>\" (b a) (nil finalizer) \
         ((outer symbol) inner b a))",
        "finalizers",
    );
}

#[test]
fn a_failing_finalizer_is_logged_not_signalled() {
    // alloc.c:run_finalizer_function: internal_condition_case_1 with Qt and
    // run_finalizer_handler, which add_to_log's "finalizer failed: %S".
    // A conservative stack scan can retain a newly created finalizer
    // through the first collection. As in finalizers_follow_alloc_c,
    // observe later collections, and require the failing callback to run
    // exactly once. GNU evaluates the same program below.
    let program = r#"
        (let ((runs 0))
          (make-finalizer (lambda () (setq runs (1+ runs)) (error "boom")))
          (garbage-collect)
          (garbage-collect)
          (let ((after-error runs))
            (garbage-collect)
            (list after-error runs
                  (with-current-buffer "*Messages*" (buffer-string)))))"#;
    assert_upstream_primitive_contract(
        &format!("(prin1 {program})"),
        "(1 1 \"finalizer failed: (error \\\"boom\\\")\n\")",
    );
    let mut interp = crate::test_support::initialized_upstream_batch_interpreter();
    let form = Reader::new(program)
        .read_all()
        .expect("read finalizer program")
        .remove(0);
    let result = interp
        .eval(&form, &mut crate::lisp::types::Env::new())
        .expect("a failing finalizer does not signal to the collector's caller");
    let fields = result.to_vec().expect("finalizer observations");
    assert_eq!(fields.len(), 3);
    assert_eq!(
        fields[0],
        Value::Integer(1),
        "callback ran before observation"
    );
    assert_eq!(fields[1], Value::Integer(1), "callback never runs twice");
    let text = string_like(&fields[2]).expect("*Messages* text").text;
    assert!(
        text.contains("finalizer failed: (error \"boom\")"),
        "expected the add_to_log line, got {text:?}"
    );
}

#[test]
fn buffer_local_cells_follow_data_c() {
    // data.c: a buffer's local bindings are its `local_var_alist', searched
    // by the symbol object; a cell whose value is Qunbound is still a
    // binding (`local-variable-p' t, `buffer-local-variables' lists the
    // bare symbol, a read is void, the default is untouched);
    // `make-local-variable' copies the default cell (void stays void) and
    // refuses a constant with VARIABLE as given; `make-variable-buffer-local'
    // turns a void plain value into nil, refuses a constant, and returns
    // VARIABLE as given; `set' through the alist cell, `let' as
    // SPECPDL_LET_LOCAL over a cell, `kill-local-variable', `set-default',
    // and `buffer-local-value' (void-variable with VARIABLE as given).
    let program = r#"
        (let ((results nil))
          (defvar zz-bl-a 'default)
          (push (with-temp-buffer
                  (list (local-variable-p 'zz-bl-a) (local-variable-if-set-p 'zz-bl-a)
                        (progn (make-local-variable 'zz-bl-a) (list (local-variable-p 'zz-bl-a) zz-bl-a))
                        (progn (setq zz-bl-a 'local) (list zz-bl-a (default-value 'zz-bl-a)))
                        (with-temp-buffer (list zz-bl-a (local-variable-p 'zz-bl-a)))
                        (progn (setq-default zz-bl-a 'new-default) (list zz-bl-a (default-value 'zz-bl-a)))
                        (let ((zz-bl-a 'let-bound))
                          (list zz-bl-a (default-value 'zz-bl-a) (with-temp-buffer zz-bl-a)))
                        (progn (kill-local-variable 'zz-bl-a) (list zz-bl-a (local-variable-p 'zz-bl-a)))))
                results)
          (defvar zz-bl-b 1)
          (make-variable-buffer-local 'zz-bl-b)
          (push (with-temp-buffer
                  (list (local-variable-if-set-p 'zz-bl-b) (local-variable-p 'zz-bl-b)
                        (progn (setq zz-bl-b 2) (list zz-bl-b (default-value 'zz-bl-b) (local-variable-p 'zz-bl-b)))
                        (let ((zz-bl-b 3)) (list zz-bl-b (default-value 'zz-bl-b) (with-temp-buffer zz-bl-b)))
                        (progn (set-default 'zz-bl-b 4) (list zz-bl-b (with-temp-buffer zz-bl-b)))
                        (progn (makunbound 'zz-bl-b)
                               (list (boundp 'zz-bl-b) (local-variable-p 'zz-bl-b) (default-boundp 'zz-bl-b)
                                     (condition-case e zz-bl-b (void-variable (cadr e)))
                                     (condition-case e (buffer-local-value 'zz-bl-b (current-buffer))
                                       (void-variable (cadr e)))
                                     (with-temp-buffer zz-bl-b)))
                        (mapcar (lambda (e) (if (consp e) (car e) e))
                                (seq-filter (lambda (e) (memq (if (consp e) (car e) e) '(zz-bl-a zz-bl-b zz-bl-c)))
                                            (buffer-local-variables)))
                        (progn (setq zz-bl-b 5) (list zz-bl-b (boundp 'zz-bl-b) (default-value 'zz-bl-b)))))
                results)
          (push (with-temp-buffer
                  (setq-local zz-bl-c 1) (setq-local zz-bl-a 2)
                  (list (mapcar #'car (seq-filter (lambda (e) (memq (car-safe e) '(zz-bl-a zz-bl-c)))
                                                  (buffer-local-variables)))
                        (progn (kill-all-local-variables)
                               (list (local-variable-p 'zz-bl-c) (boundp 'zz-bl-c) (default-boundp 'zz-bl-c)))
                        (progn (put 'zz-bl-d 'permanent-local t) (setq-local zz-bl-d 9)
                               (kill-all-local-variables) (local-variable-p 'zz-bl-d))
                        (condition-case e (make-local-variable :kw) (error e))
                        (condition-case e (make-variable-buffer-local 'nil) (error e))
                        (condition-case e (make-local-variable 3) (error e))
                        (progn (defvaralias 'zz-bl-alias 'zz-bl-a) (setq-local zz-bl-alias 7)
                               (list zz-bl-a (local-variable-p 'zz-bl-a) (local-variable-p 'zz-bl-alias)
                                     (buffer-local-value 'zz-bl-alias (current-buffer))
                                     (make-variable-buffer-local 'zz-bl-alias)
                                     (make-local-variable 'zz-bl-alias)
                                     (kill-local-variable 'zz-bl-alias)))
                        (with-temp-buffer
                          (list (buffer-local-value 'zz-bl-a (current-buffer))
                                (condition-case e (buffer-local-value 'zz-bl-unbound (current-buffer)) (error e))))
                        (progn (make-variable-buffer-local 'zz-bl-e)
                               (list (boundp 'zz-bl-e) zz-bl-e (default-value 'zz-bl-e) (local-variable-p 'zz-bl-e)))
                        (progn (make-local-variable 'zz-bl-f)
                               (list (boundp 'zz-bl-f) (local-variable-p 'zz-bl-f) (default-boundp 'zz-bl-f)
                                     (progn (setq zz-bl-f 1)
                                            (list zz-bl-f (default-boundp 'zz-bl-f)
                                                  (with-temp-buffer (boundp 'zz-bl-f))))))
                        (progn (defvar zz-bl-g 0)
                               (let ((zz-bl-g 1))
                                 (list (make-local-variable 'zz-bl-g) zz-bl-g (local-variable-p 'zz-bl-g)
                                       (default-value 'zz-bl-g))))
                        (progn (make-variable-buffer-local 'zz-bl-h)
                               (let ((zz-bl-h 1)) (setq zz-bl-h 2)
                                    (list zz-bl-h (local-variable-p 'zz-bl-h) (default-value 'zz-bl-h))))))
                results)
          (nreverse results))"#;
    assert_oracle_contract_matches_interpreter(
        program,
        "((nil nil (t default) (local default) (default nil) (local new-default) \
         (let-bound new-default new-default) (new-default nil)) \
         (t nil (2 1 t) (3 1 1) (2 4) (nil t t zz-bl-b zz-bl-b 4) (zz-bl-b) (5 t 4)) \
         ((zz-bl-c zz-bl-a) (nil nil nil) t (setting-constant :kw) (setting-constant nil) \
         (wrong-type-argument symbolp 3) (7 t t 7 zz-bl-alias zz-bl-a zz-bl-a) \
         (new-default (void-variable zz-bl-unbound)) (t nil nil nil) (nil t nil (1 nil nil)) \
         (zz-bl-g 1 t 1) (2 nil nil)))",
        "buffer-local cells",
    );
}

#[test]
fn loaded_buffer_local_bindings_follow_data_c() {
    // data.c's SYMBOL_LOCALIZED reads and stores through the binding loaded
    // for a buffer (blv `where' and `valcell'): a store into a variable
    // local when set makes the buffer's binding unless a `let' of the
    // default is in effect (let_shadows_buffer_binding_p); a binding killed
    // (`kill-local-variable', `kill-all-local-variables', the buffer's
    // death), made again, copied to an indirect clone, `let'-bound or
    // watched after it was loaded is the one read and stored next, from the
    // evaluator and from byte-code; and each modification sets
    // `deactivate-mark' in a binding of the buffer's own.
    let program = r#"
        (let ((results nil)
              (a (generate-new-buffer "zz-lb-a"))
              (b (generate-new-buffer "zz-lb-b")))
          (defvar-local zz-lb-loc 'default)
          (defvar zz-lb-plain 'plain-default)
          ;; A store makes A's binding; B still sees the default.
          (with-current-buffer a (setq zz-lb-loc 'in-a))
          (push (list (with-current-buffer a zz-lb-loc) (with-current-buffer b zz-lb-loc)
                      (default-value 'zz-lb-loc))
                results)
          ;; A `let' of the default in B shadows the binding a store would make.
          (with-current-buffer b
            (let ((zz-lb-loc 'let-default))
              (setq zz-lb-loc 'set-in-let)
              (push (list zz-lb-loc (local-variable-p 'zz-lb-loc) (default-value 'zz-lb-loc)
                          (with-current-buffer a zz-lb-loc))
                    results))
            (push (list zz-lb-loc (local-variable-p 'zz-lb-loc) (default-value 'zz-lb-loc)) results)
            (setq zz-lb-loc 'in-b)
            (push (list zz-lb-loc (local-variable-p 'zz-lb-loc)) results))
          ;; Killed, then made again, while loaded.
          (with-current-buffer a
            (push zz-lb-loc results)
            (kill-local-variable 'zz-lb-loc)
            (push (list zz-lb-loc (local-variable-p 'zz-lb-loc)) results)
            (setq zz-lb-loc 'again)
            (push (list zz-lb-loc (local-variable-p 'zz-lb-loc) (with-current-buffer b zz-lb-loc)) results))
          ;; A plain variable made local in A: a store in B is the default's.
          (with-current-buffer a (make-local-variable 'zz-lb-plain) (setq zz-lb-plain 'a-plain))
          (with-current-buffer b (setq zz-lb-plain 'b-set))
          (push (list (with-current-buffer a zz-lb-plain) (with-current-buffer b zz-lb-plain)
                      (default-value 'zz-lb-plain) (with-current-buffer b (local-variable-p 'zz-lb-plain)))
                results)
          ;; A `let' of A's binding, read from B inside it.
          (with-current-buffer a
            (let ((zz-lb-loc 'a-let))
              (push (list zz-lb-loc (with-current-buffer b zz-lb-loc)
                          (progn (setq zz-lb-loc 'a-let-set) zz-lb-loc))
                    results))
            (push zz-lb-loc results))
          ;; A watcher added once the binding is loaded sees the next store.
          (let* ((seen nil)
                 (watch (lambda (symbol new op where)
                          (push (list symbol new op (buffer-name where)) seen))))
            (with-current-buffer a (setq zz-lb-loc 'before-watch))
            (add-variable-watcher 'zz-lb-loc watch)
            (with-current-buffer a (setq zz-lb-loc 'watched))
            (remove-variable-watcher 'zz-lb-loc watch)
            (with-current-buffer a (setq zz-lb-loc 'unwatched))
            (push (list (nreverse seen) (with-current-buffer a zz-lb-loc)) results))
          ;; Byte-code reads and stores the same bindings.
          (push (funcall (byte-compile
                          (lambda (a b)
                            (with-current-buffer a (setq zz-lb-loc 'bc-a))
                            (list (with-current-buffer a zz-lb-loc)
                                  (with-current-buffer b (setq zz-lb-loc 'bc-b) zz-lb-loc)
                                  (with-current-buffer a zz-lb-loc))))
                         a b)
                results)
          ;; An indirect clone copies the bindings; each keeps its own after.
          (let ((c (with-current-buffer a (make-indirect-buffer a "zz-lb-c" t))))
            (push (list (with-current-buffer c zz-lb-loc)
                        (progn (with-current-buffer c (setq zz-lb-loc 'in-c)) (with-current-buffer a zz-lb-loc))
                        (with-current-buffer c zz-lb-loc))
                  results)
            (kill-buffer c))
          ;; `kill-all-local-variables' and `makunbound' of a loaded binding.
          (with-current-buffer a
            (kill-all-local-variables)
            (push (list zz-lb-loc zz-lb-plain (local-variable-p 'zz-lb-loc)) results)
            (setq zz-lb-loc 'after-kill-all)
            (makunbound 'zz-lb-loc)
            (push (list (boundp 'zz-lb-loc) (local-variable-p 'zz-lb-loc)
                        (with-current-buffer b zz-lb-loc))
                  results))
          ;; Each modification stores `deactivate-mark' through a binding of its own.
          (with-current-buffer b
            (insert "x")
            (push (list deactivate-mark (local-variable-p 'deactivate-mark)
                        (with-current-buffer a (local-variable-p 'deactivate-mark)))
                  results))
          ;; A killed buffer's bindings go with it.
          (kill-buffer a)
          (push (with-current-buffer b (list zz-lb-loc (default-value 'zz-lb-loc))) results)
          (kill-buffer b)
          (nreverse results))"#;
    assert_oracle_contract_matches_interpreter(
        program,
        "((in-a default default) (set-in-let nil set-in-let in-a) (default nil default) (in-b t) \
         in-a (default nil) (again t in-b) (a-plain b-set b-set nil) (a-let in-b a-let-set) again \
         (((zz-lb-loc watched set \"zz-lb-a\")) unwatched) (bc-a bc-b bc-a) (bc-a bc-a in-c) \
         (default b-set nil) (nil t bc-b) (t t nil) (bc-b default))",
        "loaded buffer-local bindings",
    );
}

#[test]
fn defvaralias_records_the_alias_in_load_history() {
    // eval.c:Fdefvaralias: LOADHIST_ATTACH (new_alias) -- the bare symbol,
    // exactly as Fdefvar records a variable.
    let program = r#"
        (let ((file (make-temp-file "zz-lh" nil ".el")))
          (with-temp-file file
            (insert "(defvaralias 'zz-lh-a 'zz-lh-b)\n(defvar zz-lh-c 1)\n"))
          (load file nil t)
          (prog1 (cdr (assoc file load-history)) (delete-file file)))"#;
    assert_oracle_contract_matches_interpreter(
        program,
        "(zz-lh-a zz-lh-c)",
        "defvaralias load-history",
    );
}

#[test]
fn defvaralias_follows_eval_c() {
    // eval.c:Fdefvaralias, in order: CHECK_SYMBOL, "Cannot make a
    // constant an alias", the non-circularity walk from BASE (signalling
    // with BASE), "Cannot make a built-in variable an alias" for a
    // SYMBOL_FORWARDED new-alias and "Don't know how to make a
    // buffer-local variable an alias" for a SYMBOL_LOCALIZED one, the
    // 2008 hand-over of the alias's value to an unbound base or the
    // `losing-value' warning with its formatted message, "Don't know how
    // to make a let-bound variable an alias", watchers, then the
    // redirect to BASE itself (so re-pointing BASE re-points its aliases),
    // `variable-documentation' put even when nil, and BASE returned.
    let program = r#"
        (progn
          (require 'cl-lib)
          (list
           (condition-case err (defvaralias :zz-kw 'zz-x) (error err))
           (condition-case err (defvaralias 'nil 'zz-x) (error err))
           (condition-case err (defvaralias 'zz-self 'zz-self) (error err))
           (condition-case err
               (progn (defvar zz-bl 1) (with-temp-buffer (make-local-variable 'zz-bl))
                      (defvaralias 'zz-bl 'zz-x))
             (error err))
           (condition-case err (defvaralias 'fill-column 'zz-x) (error err))
           (condition-case err (defvaralias 'load-path 'zz-x) (error err))
           (condition-case err (defvaralias 'case-fold-search 'zz-x) (error err))
           (condition-case err (defvaralias 'deactivate-mark 'zz-x) (error err))
           (condition-case err (defvaralias 'gc-cons-threshold 'zz-x) (error err))
           (condition-case err (defvaralias 'zz-x 'load-path) (error err))
           (condition-case err (defvaralias 'byte-code-meter 'zz-x) (error err))
           (condition-case err (let ((zz-lb 1)) (defvar zz-lb) (defvaralias 'zz-lb 'zz-x)) (error err))
           (condition-case err
               (progn (defvar zz-lb2 0) (let ((zz-lb2 1)) (defvaralias 'zz-lb2 'zz-x)))
             (error err))
           (let ((log nil))
             (defvar zz-w1 1)
             (add-variable-watcher 'zz-w1 (lambda (&rest a) (push a log)))
             (list (condition-case err
                       (progn (defvaralias 'zz-cy1 'zz-w1) (defvaralias 'zz-w1 'zz-cy1))
                     (error err))
                   log))
           (condition-case err
               (progn (defvaralias 'zz-d1 'zz-d2 "doc")
                      (list (get 'zz-d1 'variable-documentation) (special-variable-p 'zz-d2)
                            (special-variable-p 'zz-d1) (boundp 'zz-d1) (symbol-plist 'zz-d1)))
             (error err))
           (condition-case err (progn (defvaralias 'zz-d3 'zz-d4) (symbol-plist 'zz-d3)) (error err))
           (condition-case err
               (progn (set 'zz-na 3) (defvaralias 'zz-na 'zz-nb) (list zz-nb (indirect-variable 'zz-na)))
             (error err))
           (condition-case err
               (progn (defvaralias 'zz-ch-a 'zz-ch-b) (defvaralias 'zz-ch-b 'zz-ch-c) (set 'zz-ch-c 1)
                      (defvaralias 'zz-ch-b 'zz-ch-d) (set 'zz-ch-d 2)
                      (list zz-ch-a (indirect-variable 'zz-ch-a)
                            (condition-case e2 (defvaralias 'zz-ch-d 'zz-ch-a) (error e2))))
             (error err))
           (condition-case err
               (progn (defvar zz-warn-a 1) (defvar zz-warn-b 2)
                      (let ((warnings nil))
                        (cl-letf (((symbol-function 'display-warning) (lambda (&rest a) (push a warnings))))
                          (defvaralias 'zz-warn-a 'zz-warn-b))
                        (list zz-warn-a warnings)))
             (error err))
           (condition-case err (defvaralias 'zz-nonsym 3) (error err))
           (condition-case err (defvaralias 3 'zz-nonsym) (error err))))"#;
    assert_oracle_contract_matches_interpreter(
        program,
        "((error \"Cannot make a constant an alias: :zz-kw\") \
         (error \"Cannot make a constant an alias: nil\") \
         (cyclic-variable-indirection zz-self) \
         (error \"Don't know how to make a buffer-local variable an alias: zz-bl\") \
         (error \"Cannot make a built-in variable an alias: fill-column\") \
         (error \"Cannot make a built-in variable an alias: load-path\") \
         (error \"Don't know how to make a buffer-local variable an alias: case-fold-search\") \
         (error \"Don't know how to make a buffer-local variable an alias: deactivate-mark\") \
         (error \"Cannot make a built-in variable an alias: gc-cons-threshold\") \
         load-path zz-x zz-x \
         (error \"Don't know how to make a let-bound variable an alias: zz-lb2\") \
         ((cyclic-variable-indirection zz-cy1) nil) \
         (\"doc\" t t nil (variable-documentation \"doc\")) (variable-documentation nil) \
         (3 zz-nb) (2 zz-ch-d (cyclic-variable-indirection zz-ch-a)) \
         (2 (((defvaralias losing-value zz-warn-a) \
         \"Overwriting value of `zz-warn-a' by aliasing to `zz-warn-b'\"))) \
         (wrong-type-argument symbolp 3) (wrong-type-argument symbolp 3))",
        "defvaralias",
    );
}

#[test]
fn compiled_variable_references_and_sets_follow_bytecode_c() {
    // bytecode.c: Bvarref is find_symbol_value on the constant (a void
    // variable signals with that very symbol), Bvarset is set_internal
    // (constants, aliases, watchers with the original value, the current
    // buffer's local cell), Bvarbind is specbind.  Emaxx dispatched each
    // through the named `symbol-value'/`set' primitives with a fresh name
    // string per reference; the same cells are now reached directly, and
    // this pins that nothing observable changed.
    let program = r#"
        (progn
          (require 'bytecomp)
          (let ((byte-compile-warnings nil))
            (list (condition-case e (funcall (byte-compile (lambda () zz-unbound-var))) (error e))
                  (condition-case e (funcall (byte-compile (lambda () (set 'nil 1)))) (error e))
                  (condition-case e (funcall (byte-compile (lambda () (setq zz-unbound-var2 1) zz-unbound-var2)))
                    (error e))
                  (progn (defvar zz-target 1) (defvaralias 'zz-alias 'zz-target)
                         (funcall (byte-compile (lambda () (setq zz-alias 2))))
                         (list zz-target (funcall (byte-compile (lambda () zz-alias)))))
                  (let ((log nil))
                    (defvar zz-w 0)
                    (add-variable-watcher 'zz-w (lambda (s n op w) (push (list s n op w) log)))
                    (funcall (byte-compile (lambda () (setq zz-w 5) (let ((zz-w 7)) zz-w))))
                    log)
                  (progn (defvar zz-loc 9)
                         (with-temp-buffer
                           (setq-local zz-loc 3)
                           (funcall (byte-compile (lambda () (setq zz-loc 4))))
                           (list zz-loc (default-value 'zz-loc)))))))"#;
    assert_oracle_contract_matches_interpreter(
        program,
        "((void-variable zz-unbound-var) (setting-constant nil) 1 (2 2) ((zz-w 5 set nil)) (4 9))",
        "compiled variable operations",
    );
}

#[test]
fn message_log_disables_undo_in_the_messages_buffer() {
    // xdisp.c message_dolog sets `buffer-undo-list' to t and
    // `cache-long-scans' to nil in the log buffer every time it logs, so
    // an undo list a user installs there is gone after the next message.
    // Emaxx recorded undo entries for every logged line.
    let program = r#"
        (progn
          (message "x")
          (list (with-current-buffer "*Messages*" (list buffer-undo-list cache-long-scans))
                (progn (with-current-buffer "*Messages*" (setq buffer-undo-list nil cache-long-scans t))
                       (message "y")
                       (with-current-buffer "*Messages*" (list buffer-undo-list cache-long-scans)))))"#;
    assert_oracle_contract_matches_interpreter(
        program,
        "((t nil) (t nil))",
        "message log undo list",
    );
}

#[test]
fn a_buffer_local_eval_depth_applies_only_in_its_buffer() {
    // The evaluator's cell for `max-lisp-eval-depth' holds the current
    // buffer's value: a local limit applies in its buffer, the global one
    // in another buffer, and again after `kill-all-local-variables' or
    // after killing the current buffer that held the local binding. A
    // buffer switch refreshes the cells only when one of the two buffers
    // has such a local binding, so the paths that drop the current
    // buffer's locals refresh them themselves.
    let program = r#"
        (progn
          (defalias 'forwarded-cell-deep
            (lambda (n) (if (> n 0) (1+ (forwarded-cell-deep (1- n))) 0)))
          (let ((probe (lambda ()
                         (condition-case nil (forwarded-cell-deep 150)
                           (excessive-lisp-nesting 'too-deep)))))
            (with-temp-buffer
              (setq-local max-lisp-eval-depth 200)
              (list (funcall probe)
                    (with-temp-buffer (funcall probe))
                    (funcall probe)
                    (progn (kill-all-local-variables) (funcall probe))
                    (progn (setq-local max-lisp-eval-depth 200)
                           (let ((buffer (current-buffer)))
                             (with-temp-buffer
                               (let ((inner (current-buffer)))
                                 (set-buffer buffer)
                                 (kill-buffer buffer)
                                 (list (eq (current-buffer) inner) (funcall probe))))))))))"#;
    assert_oracle_contract_matches_interpreter(
        program,
        "(too-deep 150 too-deep 150 (nil 150))",
        "buffer-local eval depth",
    );
}

#[test]
fn mapping_reads_each_element_when_its_call_comes_like_mapcar1() {
    // fns.c's mapcar, mapc and mapcan take Flength first (its errors,
    // then listp for a char-table), and mapcar1 reads each element only
    // when FUNCTION is called on it: a car, an AREF, a string character
    // at its byte cursor, a bool-vector bit. A function that changes the
    // sequence sees its changes, and a list it shortens ends the mapping.
    // A closure maps over its slots. Emaxx copied the sequence first and
    // signalled vectorp for a char-table.
    let program = r#"
        (list
         (let ((l (list 1 2 3))) (mapcar (lambda (x) (setcar (cddr l) 30) x) l))
         (let ((l (list 1 2 3 4))) (mapcar (lambda (x) (setcdr (cdr l) nil) x) l))
         (let ((v (vector 1 2 3))) (mapcar (lambda (x) (aset v 2 30) x) v))
         (let ((l (list 1 2 3 4)) seen)
           (list (eq (mapc (lambda (x) (push x seen) (setcdr (cdr l) nil)) l) l)
                 (nreverse seen)))
         (let ((l (list 1 2 3))) (mapcan (lambda (x) (setcar (cddr l) 30) (list x)) l))
         (let ((s (copy-sequence "abc"))) (mapcar (lambda (c) (aset s 2 122) c) s))
         (let ((s (copy-sequence "abc"))) (mapcar (lambda (c) (aset s 2 8364) c) s))
         (let ((m (mapcar #'identity (make-byte-code 0 "\300\207" [7] 1))))
           (list (length m) (nth 0 m) (nth 2 m) (nth 3 m)))
         (mapcar #'identity (string-to-unibyte "\300a"))
         (mapcar #'identity (string 97 233 8364))
         (mapcar #'identity (bool-vector t nil t))
         (mapconcat #'number-to-string [1 2 3] ",")
         (mapcar nil nil)
         (condition-case e (mapcar nil (list 1)) (error e))
         (condition-case e (mapc #'identity (make-char-table nil)) (error (list (car e) (cadr e))))
         (condition-case e (mapcan #'list '(1 2 . 3)) (error e))
         (condition-case e (mapcar #'identity (let ((l (list 1 2))) (nconc l l))) (error (car e)))
         (condition-case e (mapcar #'identity 5) (error e))
         (mapcar #'identity '(vector-literal 1 2)))"#;
    // The last: a result list headed by the symbol `vector-literal' is a
    // list (Emaxx's internal vector form once made it a vector).
    assert_oracle_contract_matches_interpreter(
        program,
        r#"((1 2 30) (1 2) (1 2 30) (t (1 2)) (1 2 30) (97 98 122) (97 98 8364) (4 0 [7] 1) (192 97) (97 233 8364) (t nil t) "1,2,3" nil (void-function nil) (wrong-type-argument listp) (wrong-type-argument listp 3) circular-list (wrong-type-argument sequencep 5) (vector-literal 1 2))"#,
        "mapping functions",
    );
}

#[test]
fn message_log_folds_repeated_lines_like_message_dolog() {
    // xdisp.c message_dolog: a line equal to the previous one replaces it
    // with " [N times]" (counting on from an existing count), a line that
    // matched the previous one through "..." replaces it, and the log keeps
    // the last `message-log-max' lines when that is a natural number.
    // `(message "")' does not log, but a format giving "" logs an empty
    // line. Only a newline ends a line. Point and the restriction move as
    // markers do, and point at the end stays there. Emaxx logged every repetition, so a repeated message
    // filled the log and every later message trimmed its first line.
    let program = r#"
        (let ((log (lambda (thunk)
                     (with-current-buffer "*Messages*"
                       (let ((inhibit-read-only t)) (widen) (erase-buffer)))
                     (funcall thunk)
                     (with-current-buffer "*Messages*"
                       (save-restriction (widen) (buffer-string)))))
              (positions nil))
          (list
           (funcall log (lambda () (message "x") (message "x") (message "y")
                          (message "x") (message "x") (message "x")))
           (funcall log (lambda () (message "Loading foo...") (message "Loading foo...done")
                          (message "Loading bar...") (message "Loading baz...done")
                          (message "abc...") (message "abd")))
           (funcall log (lambda () (message "") (message nil) (message "%s" "")
                          (message "%s" "") (message "%s" "")))
           (funcall log (lambda () (message "z\nx") (message "x") (message "x\n") (message "x\n")))
           (funcall log (lambda () (message "c [5 times]") (message "c")
                          (message "d [ 7 times]") (message "d")
                          (message "e [-2 times]") (message "e")
                          (message "f [0 times]") (message "f")
                          (message "g [3 times]x") (message "g")
                          (message "h [9223372036854775807 times]") (message "h")
                          (message "i [+4 times]") (message "i")
                          (message "j[4 times]") (message "j")))
           (funcall log (lambda () (let ((message-log-max 3))
                                     (message "a") (message "b") (message "c") (message "c")
                                     (message "d"))))
           (replace-regexp-in-string
            "\r" "<CR>"
            (funcall log (lambda () (let ((message-log-max 2))
                                      (message "a") (message "p\rq") (message "p\rq")
                                      (message "b\rc")))))
           (funcall log (lambda () (let ((message-log-max 0)) (message "a") (message "b"))))
           (funcall log (lambda () (let ((message-log-max nil)) (message "a") (message "b"))))
           (funcall log (lambda () (let ((message-log-max 1.5))
                                     (message "a") (message "b") (message "c"))))
           (funcall log (lambda ()
                          (message "one") (message "two") (message "three")
                          (with-current-buffer "*Messages*" (goto-char 2) (narrow-to-region 2 7))
                          (message "four")
                          (with-current-buffer "*Messages*"
                            (push (list (point) (point-min) (point-max)) positions))
                          (let ((message-log-max 2)) (message "five"))
                          (with-current-buffer "*Messages*"
                            (push (list (point) (point-min) (point-max)) positions)
                            (widen) (goto-char (point-max)))
                          (message "five")
                          (with-current-buffer "*Messages*"
                            (push (list (point) (point-max)) positions)
                            (goto-char (1- (point-max))))
                          (message "five")
                          (with-current-buffer "*Messages*"
                            (push (list (point) (point-max)) positions))))
           (nreverse positions)))"#;
    assert_oracle_contract_matches_interpreter(
        program,
        r#"("x [2 times]
y
x [3 times]
" "Loading foo...done
Loading bar...
Loading baz...done
abc...
abd
" " [3 times]
" "z
x [2 times]
x

x

" "c [6 times]
d [8 times]
e [-2 times]
e
f [0 times]
f
g [3 times]x
g
h [9223372036854775807 times]
h
i [5 times]
j[4 times]
j
" "b
c [2 times]
d
" "p<CR>q [2 times]
b<CR>c
" "" "" "a
b
c
" "four
five [3 times]
" ((2 2 7) (1 1 1) (21 21) (6 21)))"#,
        "message log duplicate folding",
    );
}

#[test]
fn copy_keymap_copies_a_list_keymap_like_keymap_c() {
    // keymap.c copy_keymap_1/copy_keymap_item: a fresh spine, copied
    // char-tables, vectors and nested keymaps, fresh `(EVENT . DEFN)'
    // cells, fresh cells for a menu-item's marker, name and binding with
    // its tail shared, fresh cells for an old-style item's strings, the
    // parent tail shared, a symbol resolved through its function cell,
    // and `keymapp' for anything else.  Emaxx returned a list keymap
    // itself (keymap-copy-keymap/is-not-eq).
    let program = r#"
        (list (let* ((sub (let ((m (make-sparse-keymap))) (define-key m "b" 'ignore) m))
                     (m (make-sparse-keymap "Menu")))
                (define-key m "a" 'ignore)
                (define-key m "c" sub)
                (define-key m [menu-bar foo] '(menu-item "Foo" ignore :help "h"))
                (set-keymap-parent m (let ((p (make-sparse-keymap))) (define-key p "z" 'undo) p))
                (let* ((c (copy-keymap m))
                       (mi-c (assq 'foo (cdr (lookup-key c [menu-bar]))))
                       (mi-m (assq 'foo (cdr (lookup-key m [menu-bar])))))
                  (list (eq c m) (equal c m)
                        (eq (keymap-parent c) (keymap-parent m))
                        (eq (lookup-key c "c") (lookup-key m "c"))
                        (equal (lookup-key c "c") sub)
                        (eq mi-c mi-m) (equal mi-c mi-m)
                        (eq (nthcdr 4 mi-c) (nthcdr 4 mi-m))
                        (eq (nthcdr 3 mi-c) (nthcdr 3 mi-m))
                        (condition-case e (copy-keymap 5) (error e))
                        (condition-case e (copy-keymap 'emaxx-no-such-map) (error e)))))
              (let ((f (make-keymap)))
                (define-key f "x" 'ignore)
                (define-key f [?y] (let ((s (make-sparse-keymap))) (define-key s "w" 'undo) s))
                (let ((c (copy-keymap f)))
                  (list (eq c f) (equal c f) (eq (cadr c) (cadr f))
                        (eq (lookup-key c "x") 'ignore)
                        (eq (lookup-key c "y") (lookup-key f "y"))
                        (equal (lookup-key c "y") (lookup-key f "y")))))
              (let ((k (make-sparse-keymap)))
                (fset 'emaxx-copy-keymap-fn k)
                (define-key k "q" 'ignore)
                (let ((c (copy-keymap 'emaxx-copy-keymap-fn)))
                  (list (eq c k) (equal c k))))
              (let ((o (make-sparse-keymap)))
                (define-key o "s" '("Old" "help" . ignore))
                (let* ((c (copy-keymap o))
                       (ec (assq ?s (cdr c)))
                       (em (assq ?s (cdr o))))
                  (list (eq ec em) (equal ec em) (eq (cddr ec) (cddr em)) (eq (cdddr ec) (cdddr em))))))"#;
    assert_oracle_contract_matches_interpreter(
        program,
        "((nil t t nil t nil t t nil (wrong-type-argument keymapp 5) (wrong-type-argument keymapp emaxx-no-such-map)) (nil t nil t nil t) (nil t) (nil t nil t))",
        "copy-keymap",
    );
}

#[test]
fn load_warns_about_unescaped_character_literals_on_the_eval_buffer_path() {
    // lread.c: Fload binds `lread--unescaped-character-literals' to nil,
    // the reader conses every unescaped `?)'-style literal onto it, and
    // load_warn_unescaped_character_literals messages "Loading `FILE':
    // ..." as the load unwinds -- also for a `load' with NOMESSAGE.  The
    // merged `load' evaluates a source file through
    // load-with-code-conversion and `eval-buffer', whose reader had not
    // recorded the literals (lread-tests--unescaped-char-literals).  (The
    // message's quotes and backslashes are substituted so the expected
    // text needs no escaping.)  Exercise each explicit quoting style: the
    // nil default is locale-dependent (curve on the Linux UTF-8 oracle).
    let program = r#"
        (let* ((text-quoting-style 'QUOTE_STYLE)
               (f (make-temp-file "emaxx-lit" nil ".el" "?) ?( ?; ?\" ?[ ?]"))
               (r (load f nil :nomessage :nosuffix))
               (m (with-current-buffer "*Messages*"
                    (save-excursion
                      (goto-char (point-max))
                      (forward-line -1)
                      (buffer-substring (point) (line-end-position))))))
          (delete-file f)
          (list r (string-replace "\\" "B" (string-replace "\"" "Q" (string-replace f "FILE" m)))))"#;
    let grave = "(t \"Loading `FILE': unescaped character literals `?Q', `?(', `?)', `?;', `?[', `?]' detected, `?BQ', `?B(', `?B)', `?B;', `?B[', `?B]' expected!\")";
    for (style, open, close) in [
        ("grave", "`", "'"),
        ("curve", "‘", "’"),
        ("straight", "'", "'"),
    ] {
        let expected = grave.replace('`', open).replace('\'', close);
        assert_oracle_contract_matches_interpreter(
            &program.replace("QUOTE_STYLE", style),
            &expected,
            &format!("unescaped character literal warning with {style} quotes"),
        );
    }
}

#[test]
fn sqlite_values_are_a_list_or_a_vector() {
    // sqlite.c bind_values walks VALUES as a vector (AREF) or a list
    // (XCAR/XCDR); Fsqlite_execute and Fsqlite_select signal `sqlite-error'
    // for anything else.  The merged vector representation made
    // `vector_items' vector-only, and a list of parameters (multisession.el
    // passes one) signalled `(wrong-type-argument vectorp ...)'.
    let program = r#"
        (let ((db (sqlite-open)))
          (sqlite-execute db "create table t (a, b)")
          (sqlite-execute db "insert into t values (?, ?)" (list "x" "y"))
          (sqlite-execute db "insert into t values (?, ?)" ["p" "q"])
          (list (sqlite-select db "select * from t where a = ?" (list "x"))
                (sqlite-select db "select * from t where a = ?" ["p"])
                (sqlite-select db "select * from t order by a")
                (condition-case e (sqlite-select db "select 1" 5) (error e))
                (condition-case e (sqlite-execute db "select 1" "s") (error e))))"#;
    assert_oracle_contract_matches_interpreter(
        program,
        r#"((("x" "y")) (("p" "q")) (("p" "q") ("x" "y")) (sqlite-error "VALUES must be a list or a vector") (sqlite-error "VALUES must be a list or a vector"))"#,
        "sqlite VALUES",
    );
}

#[test]
fn sqlite_primitives_follow_sqlite_c_on_the_c_api() {
    // sqlite.c on SQLite's C API: a FILE expanded against
    // `default-directory' and nil for one that cannot be opened; no busy
    // handler, so a locked database is `sqlite-locked-error' at once (the
    // five-second timeout of rusqlite's connections waited); only the first
    // statement executed, and sqlite3_changes for one that returns no row;
    // bind_values' own messages and bignum_to_intmax's 0; a BLOB unibyte; a
    // TEXT column decoded as utf-8 (raw bytes kept, eol detected); a set
    // stepped lazily, `sqlite-more-p' t until a step finds no row; every
    // object error `sqlite-error'; and print.c's #<sqlite db=...>.
    let program = r##"
        (let* ((dir (make-temp-file "emaxx-sqlite-" t))
               (default-directory (file-name-as-directory dir)))
          (unwind-protect
              (let* ((db (sqlite-open "t.db"))
                     (db2 (sqlite-open "t.db"))
                     (err (lambda (thunk) (condition-case e (funcall thunk) (error e)))))
                (prog1
                    (list
                     (file-exists-p (expand-file-name "t.db" dir))
                     (sqlite-open "/nonexistent-emaxx-dir/a.db")
                     (sqlite-execute db "create table t (x)")
                     (sqlite-execute db "insert into t values (1)")
                     (sqlite-execute db "select * from t where 0")
                     (sqlite-execute db "insert into t values (5); insert into t values (6)")
                     (funcall err (lambda ()
                                    (sqlite-execute db "create table u (x unique)")
                                    (sqlite-execute db "insert into u values (1)")
                                    (sqlite-execute db "insert into u values (1)")))
                     (funcall err (lambda () (sqlite-execute db "insert into t values (?)" (list 'foo))))
                     (funcall err (lambda ()
                                    (sqlite-execute db "insert into t values (?)"
                                                    (list (propertize "é" 'coding-system 'binary)))))
                     (sqlite-select db "select ?, ?, ?, ?" (list (expt 2 70) t 'false nil))
                     (let ((v (caar (sqlite-select db "select x'C3A9'")))) (list (append v nil) (multibyte-string-p v)))
                     (append (caar (sqlite-select db "select cast(x'FF41' as text)")) nil)
                     (append (caar (sqlite-select db "select 'a'||char(13)||char(10)||'b'")) nil)
                     (let ((set (sqlite-select db "select x from t order by x" nil 'set)) r)
                       (while (sqlite-more-p set) (push (sqlite-next set) r))
                       (list (nreverse r)
                             (funcall err (lambda () (sqlite-close set)))
                             (sqlite-finalize set)
                             (funcall err (lambda () (sqlite-next set)))))
                     (progn
                       (sqlite-transaction db)
                       (sqlite-execute db "insert into t values (9)")
                       (prog1 (funcall err (lambda () (sqlite-execute db2 "insert into t values (10)")))
                         (sqlite-commit db)))
                     (funcall err (lambda () (sqlite-execute db "")))
                     (funcall err (lambda () (sqlite-execute 1 "select 1")))
                     (progn
                       (sqlite-close db)
                       (list (funcall err (lambda () (sqlite-execute db "select 1")))
                             (string-match-p "\\`#<sqlite db=(nil) name=/" (prin1-to-string db)))))
                  (sqlite-close db2)))
            (delete-directory dir t)))"##;
    assert_oracle_contract_matches_interpreter(
        program,
        r#"(t nil 0 1 1 1 (sqlite-error "UNIQUE constraint failed: u.x") (sqlite-error "invalid argument") (sqlite-error "BLOB values must be unibyte") ((0 1 0 nil)) ((195 169) nil) (4194303 65) (97 10 98) (((1) (5) nil) (sqlite-error "Invalid database object") t (sqlite-error "Statement closed")) (sqlite-locked-error "database is locked") (sqlite-error "not an error") (wrong-type-argument sqlitep 1) ((sqlite-error "Database closed") 0))"#,
        "sqlite.c",
    );
}

#[test]
fn next_read_file_uses_dialog_p_follows_the_oracle_toolkit() {
    // fileio.c requires window_system_available(SELECTED_FRAME()). GNU's
    // initial batch frame is a terminal even in its graphical builds.
    let program = r#"
        (list (next-read-file-uses-dialog-p)
              (let ((use-dialog-box t) (use-file-dialog t) (last-nonmenu-event nil))
                (next-read-file-uses-dialog-p))
              (let ((use-dialog-box nil)) (next-read-file-uses-dialog-p)))"#;
    assert_oracle_contract_matches_interpreter(program, "(nil nil nil)", "read-file-name dialog");

    // Preserve separate build contracts: ns-win.el owns the NS function;
    // pgtkfns.c and GTK/Motif xfns.c own the Linux graphical variants.
    // Plain X11 and terminal-only builds have no file-dialog definition.
    // Select by actual features, never by the OS running this Rust test.
    let availability = r#"
        (let* ((backend (cond ((featurep 'ns) 'ns)
                              ((featurep 'pgtk) 'pgtk)
                              ((featurep 'w32) 'w32)
                              ((featurep 'haiku) 'haiku)
                              ((and (featurep 'x) (featurep 'gtk)) 'x-gtk)
                              ((and (featurep 'x) (featurep 'motif)) 'x-motif)
                              ((featurep 'x) 'x)
                              (t 'terminal)))
               (available (fboundp 'x-file-dialog))
               (function (and available (indirect-function 'x-file-dialog))))
          (list backend available
                (and available
                     (cond ((autoloadp function) 'autoload)
                           ((and (subrp function) (not (subr-native-elisp-p function))) 'c)
                           (t 'lisp)))))"#;
    let oracle = upstream_primitive_contract_output(&format!("(prin1 {availability})"));
    assert!(
        matches!(
            oracle.as_str(),
            "(ns t lisp)"
                | "(pgtk t c)"
                | "(x-gtk t c)"
                | "(x-motif t c)"
                | "(w32 t c)"
                | "(haiku t c)"
                | "(x nil nil)"
                | "(terminal nil nil)"
        ),
        "GNU's file-dialog availability/owner does not match its backend: {oracle}"
    );
    let mut interpreter = crate::test_support::initialized_upstream_batch_interpreter();
    let actual = crate::test_support::eval_lisp(
        &mut interpreter,
        &mut crate::lisp::types::Env::new(),
        availability,
    )
    .expect("read the terminal runtime's graphical capability boundary");
    // This is a capability boundary, not a claim of NS/GTK availability
    // parity. A future graphical runtime needs its matching backend case.
    assert_eq!(actual.to_string(), "(terminal nil nil)");
    eprintln!("file-dialog backend coverage: GNU {oracle}; Emaxx {actual}");
}

#[test]
fn portable_dump_introspection_and_backend_boundary_are_honest() {
    let sort_program = r#"
        (list
         (dump-emacs-portable--sort-predicate '(first 1) '(second 2))
         (dump-emacs-portable--sort-predicate '(first 2) '(second 1))
         (dump-emacs-portable--sort-predicate '(first 1) '(second 1)))"#;
    let expected = "(t nil nil)";
    assert_upstream_primitive_contract(&format!("(prin1 {sort_program})"), expected);

    let mut interp = Interpreter::new();
    let mut env = crate::lisp::types::Env::new();
    let form = Reader::new(sort_program)
        .read()
        .expect("portable-dump sort program should parse")
        .expect("portable-dump sort program should contain a form");
    let actual = interp
        .eval(&form, &mut env)
        .expect("portable-dump sort predicate should evaluate");
    let expected = Reader::new(expected)
        .read()
        .expect("portable-dump sort result should parse")
        .expect("portable-dump sort result should exist");
    assert!(
        values_equal(&interp, &actual, &expected).expect("equal"),
        "portable-dump relocation ordering differs from GNU:\nactual: {actual:?}\nexpected: {expected:?}"
    );

    assert_upstream_primitive_contract(
        r#"(let ((stats (pdumper-stats)))
              (prin1
               (or (null stats)
                   (and (eq (alist-get 'dumped-with-pdumper stats) t)
                        (numberp (alist-get 'load-time stats))
                        (stringp (alist-get 'dump-file-name stats))))))"#,
        "t",
    );
    // A reconstructed process reports no dump; one the harness started
    // from its shared loadup image reports that file, as GNU's emacs
    // reports emacs.pdmp.
    let stats = call(&mut interp, "pdumper-stats", &[], &mut env)
        .expect("a directly initialized Emaxx has valid dump statistics");
    match interp
        .pdumper_load_record()
        .map(|record| record.filename.clone())
    {
        None => assert_eq!(
            stats,
            Value::Nil,
            "Emaxx must not claim it restored from a portable dump"
        ),
        Some(filename) => {
            let printed = call(&mut interp, "prin1-to-string", &[stats], &mut env).expect("print");
            assert!(
                string_like(&printed)
                    .expect("printed")
                    .text
                    .ends_with(&format!("(dump-file-name . {filename:?}))")),
                "{printed:?}"
            );
        }
    }

    let contract_program = r#"
        (list
         (subr-arity (symbol-function 'dump-emacs-portable))
         (subr-arity
          (symbol-function 'dump-emacs-portable--sort-predicate-copied))
         (condition-case error-data
             (dump-emacs-portable 42)
           (error error-data)))"#;
    let contract_expected = "((1 . 2) (2 . 2) (wrong-type-argument stringp 42))";
    assert_upstream_primitive_contract(&format!("(prin1 {contract_program})"), contract_expected);

    let boundary_program = r#"
        (list
         (subr-arity (symbol-function 'dump-emacs-portable))
         (subr-arity
          (symbol-function 'dump-emacs-portable--sort-predicate-copied))
         (condition-case error-data
             (dump-emacs-portable 42)
           (error error-data))
         (condition-case error-data
             (dump-emacs-portable "/nonexistent-dir/must-not-be-created.pdmp" t)
           (error (car error-data)))
         (condition-case error-data
             (dump-emacs-portable--sort-predicate-copied nil nil)
           (error error-data)))"#;
    let unavailable = "(error \"Portable dumper backend is unavailable\")";
    let boundary_expected = format!(
        "((1 . 2) (2 . 2) (wrong-type-argument stringp 42) \
         file-missing {unavailable})"
    );
    // The writer boundary sits past pdumper.c's batch-mode check, so the
    // program runs in an initialized batch image (a bare interpreter is
    // refused as GNU refuses an interactive one).  It is read once that
    // image exists, so that its symbols are the image's own: a handler's
    // `error' is compared with the conditions by identity, as Fmemq does.
    let mut interp = crate::test_support::initialized_upstream_batch_interpreter();
    let form = Reader::new(boundary_program)
        .read()
        .expect("portable-dumper boundary program should parse")
        .expect("portable-dumper boundary program should contain a form");
    let actual = interp
        .eval(&form, &mut env)
        .expect("portable-dumper boundary should be catchable");
    let expected = Reader::new(&boundary_expected)
        .read()
        .expect("portable-dumper boundary expectation should parse")
        .expect("portable-dumper boundary expectation should contain a form");
    assert!(
        values_equal(&interp, &actual, &expected).expect("equal"),
        "portable-dumper boundary was not explicit:\nactual: {actual}\nexpected: {expected}"
    );
}

#[test]
fn dump_emacs_portable_prelude_follows_pdumper_c() {
    // pdumper.c:Fdump_emacs_portable in source order: the main-thread and
    // other-thread refusals, `load--fixup-all-elns' called as a Lisp
    // function, one collection (post-gc-hook runs) before the filename is
    // checked, the `command-line-processed' binding made and unbound
    // around the failure, and the arity errors.
    let program = r#"
        (progn
          (setq zz-order nil)
          (fset 'load--fixup-all-elns (lambda () (push 'fixup zz-order)))
          (add-hook 'post-gc-hook (lambda () (push 'gc zz-order)))
          (add-variable-watcher 'command-line-processed
                                (lambda (_symbol value operation _where)
                                  (push (list 'watch operation value) zz-order)))
          (list
           (condition-case error-data (dump-emacs-portable 42) (error error-data))
           (reverse zz-order)
           command-line-processed
           (condition-case error-data
               (dump-emacs-portable "/nonexistent-dir/zz-dump.pdmp")
             (error error-data))
           (let ((thread (make-thread (lambda () (thread-yield) (sleep-for 1)))))
             (setq zz-order nil)
             (prog1 (list (condition-case error-data (dump-emacs-portable 42)
                            (error error-data))
                          (reverse zz-order))
               (thread-join thread)))
           (let ((thread (make-thread
                          (lambda ()
                            (condition-case error-data (dump-emacs-portable 42)
                              (error error-data))))))
             (thread-join thread))
           (condition-case error-data (dump-emacs-portable) (error error-data))
           (condition-case error-data (dump-emacs-portable "a" "b" "c")
             (error error-data))))"#;
    let expected = "((wrong-type-argument stringp 42) \
         (fixup gc (watch let nil) (watch unlet t)) t \
         (file-missing \"Opening dump output\" \"No such file or directory\" \
         \"/nonexistent-dir/zz-dump.pdmp\") \
         ((error \"No other Lisp threads can be running when this function is called\") nil) \
         (error \"This function can be called only in the main thread\") \
         (wrong-number-of-arguments dump-emacs-portable 0) \
         (wrong-number-of-arguments dump-emacs-portable 3))";
    assert_oracle_contract_matches_interpreter(program, expected, "dump-emacs-portable prelude");
}

#[test]
fn dump_emacs_portable_restores_context_and_reports_native_image_limit() {
    // Runtime boundary control, not a claim of full GNU image parity.
    // The loadup state dumps and round-trips: when the startup loaded
    // native functions, under loadup.el's `load--bin-dest-dir' and
    // `load--eln-dest-dir' (the Makefile's --bin-dest and --eln-dest), so
    // that `load--fixup-all-elns' fixes each unit's file up for the dump
    // (D14/D15); as it is otherwise.  Never disable native loading to make
    // this test pass.
    use super::pdumper::image::{DUMP_MAGIC, RootSlot};
    use super::pdumper::load::{load_image, validate_header};
    let mut interp = crate::test_support::initialized_upstream_batch_interpreter();
    let mut env = crate::lisp::types::Env::new();
    let has_native_functions = interp.known_symbol_names().iter().any(|name| {
        matches!(
            interp.raw_function_binding(name, &env).map(|v| v.kind()),
            Some(Kind::NativeFunction(_))
        )
    });
    let path = std::env::temp_dir().join(format!("emaxx-d11-boundary-{}.pdmp", std::process::id()));
    let _ = std::fs::remove_file(&path);
    let dump_form = if has_native_functions {
        format!(
            "(let ((load--bin-dest-dir invocation-directory) \
                   (load--eln-dest-dir source-directory)) \
               (dump-emacs-portable {:?}))",
            path.display()
        )
    } else {
        format!("(dump-emacs-portable {:?})", path.display())
    };
    let program = format!(
        r#"(progn
             (defun zz-post-gc () nil)
             (setq purify-flag 'zz-pure
                   post-gc-hook '(zz-post-gc)
                   process-environment '("ZZ=1"))
             (let ((processed command-line-processed))
               (list (condition-case error-data {dump_form}
                       (error (list (car error-data) (cadr error-data))))
                     purify-flag post-gc-hook process-environment
                     (eq processed command-line-processed))))"#
    );
    let form = Reader::new(&program)
        .read()
        .expect("context program parses")
        .expect("context program has a form");
    let result = interp
        .eval(&form, &mut env)
        .expect("the dump returns or signals");
    let bytes = std::fs::read(&path).expect("the completed image");
    let _ = std::fs::remove_file(&path);
    assert_eq!(&bytes[..DUMP_MAGIC.len()], &DUMP_MAGIC);
    let header = validate_header(&bytes).unwrap_or_else(|error| panic!("validate: {error:?}"));
    assert_eq!(header.cold_start % (64 * 1024), 0);
    assert!(header.discardable_start < header.cold_start);
    assert!(header.cold_start < bytes.len() as u32);

    // What the writer's process answers, taken before it is dropped: a
    // loaded image reopens the native units, and dlopen hands the
    // writer's own handle back while it still holds them (GNU never loads
    // a dump into the process that wrote it).  The obarray's size is the
    // dump-time one; the programs below intern symbols of their own.
    let source_names: std::collections::HashSet<String> =
        interp.known_symbol_names().into_iter().collect();
    let dumped_symbol_count = source_names.len();
    // Every root group of the loadup state prints the same from the
    // restored interpreter (the timer list's due times are relative); taken
    // before the programs below, which update lexical cells. Capture these
    // before printing even the context result: print.c:print_prepare binds
    // print-escape-nonascii for prin1-to-string's buffer, advancing the
    // writer's binding counter after the image has already been written.
    let mut source_groups = Vec::new();
    for (slot, value) in interp.dump_root_groups() {
        let text = call(
            &mut interp,
            "prin1-to-string",
            std::slice::from_ref(&value),
            &mut env,
        )
        .expect("print the source group");
        source_groups.push((slot, string_like(&text).expect("printed").text));
    }
    let printed = call(&mut interp, "prin1-to-string", &[result], &mut env)
        .expect("print the context result");
    assert_eq!(
        string_like(&printed).expect("printed string").text,
        "(nil zz-pure (zz-post-gc) (\"ZZ=1\") t)"
    );
    let programs = [
        "(list (featurep 'subr-x) (featurep 'cl-lib) (fboundp 'when-let) (macrop 'when))",
        "(list (length load-path) (symbol-value 'emacs-version) (default-value 'fill-column))",
        "(let ((x 41)) (cl-incf x) x)",
        "(with-temp-buffer (insert \"abc\") (upcase-region 1 3) (buffer-string))",
        "(list (get 'car 'side-effect-free) (symbol-plist 'zz-none) (boundp 'zz-none))",
        "(format \"%S %s %d\" '(1 . 2) \"s\" 7)",
        "(mapconcat #'symbol-name (list 'a 'b) \",\")",
        "(sort (list 3 1 2) #'<)",
        "(string-match \"b+\" \"abbbc\")",
        "(list (buffer-name) (current-buffer) (mapcar #'buffer-name (buffer-list)))",
        "(let ((n 0)) (mapatoms (lambda (_s) (setq n (1+ n)))) n)",
        // The native functions the startup loaded, if any, are native
        // after the round trip (their units reopened, each resolved by
        // its C name) and the preloaded ones run. Check every native name
        // and arity, not the accidental first bucket occupant: GNU obarrays
        // with identical native fields can enumerate in different orders.
        "(let ((n 0) (contracts nil)) \
           (mapatoms (lambda (s) \
             (when (native-comp-function-p (symbol-function s)) \
               (setq n (1+ n)) \
               (push (list s (subr-arity (symbol-function s))) contracts)))) \
           (list n (string-trim \" a \") \
                 (sort contracts (lambda (a b) \
                                   (string-lessp (car a) (car b))))))",
        "(pdumper-stats)",
    ];
    let mut expected = Vec::new();
    for program in programs {
        let form = Reader::new(program)
            .read()
            .expect("program parses")
            .expect("a form");
        let value = interp
            .eval(&form, &mut env)
            .unwrap_or_else(|error| panic!("{program}: {error:?}"));
        let printed = call(&mut interp, "prin1-to-string", &[value], &mut env).expect("print");
        expected.push(string_like(&printed).expect("printed").text);
    }
    let writer_loaded_a_dump = interp.dump_loaded_p();
    drop(interp);

    let mut target = crate::lisp::eval::Interpreter::new();
    let image = load_image(&bytes, &mut target).unwrap_or_else(|error| panic!("load: {error:?}"));
    assert_eq!(image.obarray.len(), dumped_symbol_count);
    assert!(
        image
            .roots
            .iter()
            .any(|(slot, _)| *slot == RootSlot::Obarray)
    );
    // Each symbol of the obarray is a record or a cell of the symbol blocks.
    assert!(
        image.symbols.len() + image.header.symbol_blocks.nr_entries as usize >= image.obarray.len()
    );
    assert_eq!(image.native_units.is_empty(), !has_native_functions);
    assert_eq!(image.native_functions.is_empty(), !has_native_functions);
    drop(target);

    // pdumper_load: the same image into a fresh process-state interpreter
    // through the process-level loader, which installs the symbols and
    // the static roots and reopens the native units; Lisp then answers
    // the same on both sides, and pdumper-stats reports the load.
    use super::pdumper::{PdumperLoadError, pdumper_load};
    let loaded_path =
        std::env::temp_dir().join(format!("emaxx-d12-load-{}.pdmp", std::process::id()));
    std::fs::write(&loaded_path, &bytes).expect("write the image for the loader");
    let mut restored = crate::lisp::eval::Interpreter::new();
    let record = pdumper_load(&loaded_path, &mut restored)
        .unwrap_or_else(|error| panic!("pdumper_load: {error:?}"));
    assert_eq!(record.dump_size, bytes.len() as u64);
    assert!(restored.dump_loaded_p());
    // alloc.c: the loaded objects are not consing, and `consing_until_gc'
    // is zero in a process that starts from a dump, so the first
    // collection comes after `gc-cons-threshold' bytes of the process's
    // own consing; the loader's allocations used to count, and every
    // booted process collected on its first evaluation.
    assert!(
        !restored.native_compiler.garbage_collection_might_be_due(),
        "the image's objects counted as consing"
    );
    assert_eq!(
        pdumper_load(&loaded_path, &mut restored),
        Err(PdumperLoadError::Error("a dump is already loaded".into()))
    );
    let mut env_restored = crate::lisp::types::Env::new();
    let target_groups = restored.dump_root_groups();
    assert_eq!(source_groups.len(), target_groups.len());
    let mut compared = 0;
    for ((slot, source_text), (target_slot, target_value)) in
        source_groups.iter().zip(&target_groups)
    {
        assert_eq!(slot, target_slot);
        if *slot == RootSlot::TimerList {
            continue;
        }
        let target_text = call(
            &mut restored,
            "prin1-to-string",
            std::slice::from_ref(target_value),
            &mut env_restored,
        )
        .expect("print the restored group");
        let target_text = string_like(&target_text).expect("printed").text;
        // GNU's late native-unit relocation allocates lambda_gc_guard_h
        // with Fmake_hash_table. Hash tables now have their own allocation,
        // so reopening units must preserve every remembered scalar,
        // including next-record-id, instead of advancing the record allocator.
        assert_eq!(source_text, &target_text, "root group {slot:?}");
        compared += 1;
    }
    assert!(compared > 30);
    assert!(
        !target_groups
            .iter()
            .any(|(slot, value)| { *slot == RootSlot::CodingSystems && value.is_nil() })
    );
    for (program, expected) in programs.iter().zip(&expected) {
        let form = Reader::new(program)
            .read()
            .expect("program parses")
            .expect("a form");
        let actual = restored
            .eval(&form, &mut env_restored)
            .unwrap_or_else(|error| panic!("restored {program}: {error:?}"));
        let actual = call(
            &mut restored,
            "prin1-to-string",
            &[actual],
            &mut env_restored,
        )
        .expect("print");
        let actual = string_like(&actual).expect("printed").text;
        if program.starts_with("(let ((n 0)) (mapatoms") {
            // Every symbol the writer's obarray knows is in the restored
            // one; the restored obarray can hold more: a symbol whose
            // only mention at dump time was an autoload not yet read into
            // its function cell is interned in GNU's obarray and listed
            // here only once something looks it up.
            let target: std::collections::HashSet<String> =
                restored.known_symbol_names().into_iter().collect();
            let missing = source_names.difference(&target).collect::<Vec<_>>();
            assert!(
                missing.is_empty(),
                "missing from the restored obarray: {missing:?}"
            );
            continue;
        }
        if *program == "(pdumper-stats)" {
            // The writer's process reports the harness image it started
            // from, if any; the restored one reports this load.
            if writer_loaded_a_dump {
                assert!(
                    expected.starts_with("((dumped-with-pdumper . t) "),
                    "{expected}"
                );
            } else {
                assert_eq!(expected, "nil");
            }
            assert!(
                actual.starts_with("((dumped-with-pdumper . t) (load-time . "),
                "{actual}"
            );
            assert!(
                actual.ends_with(&format!("(dump-file-name . {:?}))", loaded_path.display())),
                "{actual}"
            );
            continue;
        }
        if program.starts_with("(let ((n 0) (called nil))") {
            assert_eq!(&actual, expected, "{program}");
            assert_eq!(actual.starts_with("(0 "), !has_native_functions, "{actual}");
            continue;
        }
        assert_eq!(&actual, expected, "{program}");
    }
    let _ = std::fs::remove_file(&loaded_path);
    drop(restored);
    // The error contract: a missing file and a truncated one (the foreign
    // fingerprint and the incomplete marker are the loader's own controls).
    let mut fresh = crate::lisp::eval::Interpreter::new();
    assert_eq!(
        pdumper_load(
            std::path::Path::new("/nonexistent-dir/none.pdmp"),
            &mut fresh
        ),
        Err(PdumperLoadError::FileNotFound)
    );
    let short = std::env::temp_dir().join(format!("emaxx-d12-short-{}.pdmp", std::process::id()));
    std::fs::write(&short, &bytes[..10]).expect("write a short file");
    assert_eq!(
        pdumper_load(&short, &mut fresh),
        Err(PdumperLoadError::BadFileType)
    );
    let _ = std::fs::remove_file(&short);
}

#[test]
fn batch_startup_image_round_trip_or_explicit_native_image_limit() {
    // Runtime boundary control.  temacs (before the Lisp top level)
    // dumps -- under loadup.el's `load--bin-dest-dir' and
    // `load--eln-dest-dir' when the startup loaded native functions, so
    // that `load--fixup-all-elns' fixes their units up (D14/D15); a
    // batch startup with emacs.c's --dump-file starts from the image,
    // applies the new process's init_* values over it, reopens the
    // units, runs GNU's normal-top-level as an initialized process, and
    // then answers what the temacs-built batch session answers.
    let upstream = crate::compat::project_root().join("../emacs");
    let load_path =
        crate::compat::emaxx_upstream_load_path(&upstream).expect("upstream GNU Emacs load path");
    let mut temacs = crate::batch::initialize_batch_interpreter(&crate::batch::BatchRunOptions {
        load_path: load_path.clone(),
        defer_delayed_custom_init: true,
        ..Default::default()
    })
    .expect("the loadup state");
    let has_native_functions = temacs.known_symbol_names().iter().any(|name| {
        matches!(
            temacs
                .raw_function_binding(name, &crate::lisp::types::Env::new())
                .map(|v| v.kind()),
            Some(Kind::NativeFunction(_))
        )
    });
    let path = std::env::temp_dir().join(format!("emaxx-d16-startup-{}.pdmp", std::process::id()));
    let _ = std::fs::remove_file(&path);
    // The hook emacs.c runs after the load ("mostly useful after
    // redumping") is set in the dumped state.
    let dump_form = if has_native_functions {
        format!(
            "(let ((load--bin-dest-dir invocation-directory) \
                   (load--eln-dest-dir source-directory)) \
               (dump-emacs-portable {:?}))",
            path.display()
        )
    } else {
        format!("(dump-emacs-portable {:?})", path.display())
    };
    let dump = Reader::new(&format!(
        "(progn (setenv \"ZZ_DUMPED\" \"1\") \
                (defvar zz-after-pdump-load nil) \
                (add-hook 'after-pdump-load-hook (lambda () (setq zz-after-pdump-load t))) \
                {dump_form})"
    ))
    .read()
    .expect("dump form parses")
    .expect("a dump form");
    let dumped = temacs.eval(&dump, &mut crate::lisp::types::Env::new());
    dumped.unwrap_or_else(|error| panic!("temacs dumps: {error:?}"));
    // The writer's units are closed before the image reopens them, and
    // so are the reference session's: the reference answers are taken
    // first, from an ordinary batch startup.
    drop(temacs);
    let programs = [
        "(list (featurep 'subr-x) (featurep 'cl-lib) (fboundp 'when-let) (macrop 'when))",
        "(list (fboundp 'forward-sexp) (fboundp 'beginning-of-defun-raw) (fboundp 'kill-region) \
               (fboundp 'move-to-left-margin) (intern-soft \"forward-sexp\"))",
        "(list (key-binding [?\\M-x]) (key-binding [?\\C-x ?\\C-f]) (key-binding \"\\M-x\") \
               (keymapp (keymap-parent (current-local-map))) (where-is-internal 'execute-extended-command))",
        "(list (symbol-value 'emacs-version) (default-value 'fill-column) purify-flag)",
        "(let ((x 41)) (cl-incf x) x)",
        "(with-temp-buffer (insert \"abc\") (upcase-region 1 3) (buffer-string))",
        "(list command-line-processed noninteractive (consp after-init-time))",
        "(list custom-delayed-init-variables (getenv \"HOME\") (getenv \"ZZ-NONE\"))",
        "(with-current-buffer \"*Messages*\" (buffer-string))",
        "(list (buffer-name) (mapcar #'buffer-name (buffer-list)))",
        "(list (car command-line-args) (length load-path) (car exec-path))",
        "(format \"%S %s %d\" '(1 . 2) \"s\" 7)",
        // The native functions the startup loaded, if any, are native in
        // the restored process too, and the preloaded ones run.
        "(let ((n 0) (first nil)) \
           (mapatoms (lambda (s) \
             (when (native-comp-function-p (symbol-function s)) \
               (setq n (1+ n)) \
               (unless first (setq first (list s (subr-arity (symbol-function s)))))))) \
           (list n (string-trim \" a \") first))",
    ];
    let print = |interp: &mut crate::lisp::eval::Interpreter, program: &str| {
        let mut env = crate::lisp::types::Env::new();
        let form = Reader::new(program)
            .read()
            .expect("program parses")
            .expect("a form");
        let value = interp
            .eval(&form, &mut env)
            .unwrap_or_else(|error| panic!("{program}: {error:?}"));
        let printed = call(interp, "prin1-to-string", &[value], &mut env).expect("print");
        string_like(&printed).expect("printed").text
    };
    let mut reference = crate::test_support::initialized_upstream_batch_interpreter();
    let expected = programs
        .iter()
        .map(|program| print(&mut reference, program))
        .collect::<Vec<_>>();
    let reference_stats = reference
        .eval(
            &Reader::new("(pdumper-stats)")
                .read()
                .expect("parses")
                .expect("a form"),
            &mut crate::lisp::types::Env::new(),
        )
        .expect("pdumper-stats");
    assert_eq!(reference_stats.is_nil(), !reference.dump_loaded_p());
    drop(reference);

    let mut restored = crate::batch::initialize_batch_interpreter(&crate::batch::BatchRunOptions {
        load_path: load_path.clone(),
        dump_file: Some(path.clone()),
        ..Default::default()
    })
    .unwrap_or_else(|error| panic!("start from the image: {error}"));
    let _ = std::fs::remove_file(&path);
    assert!(restored.dump_loaded_p());
    for (program, expected) in programs.iter().zip(&expected) {
        assert_eq!(&print(&mut restored, program), expected, "{program}");
    }
    // The load is recorded (emacs.c's dump_file names the image), and
    // the environment was rebuilt from the new process after the load
    // (the image carries `process-environment' as nil; `HOME' above
    // answered the same as the reference), the dump-time `setenv' gone
    // with the dumped list.
    let mut env = crate::lisp::types::Env::new();
    let stats = restored
        .eval(
            &Reader::new(
                "(list (car (pdumper-stats)) (cdr (assq 'dump-file-name (pdumper-stats))) \
                 (getenv \"ZZ_DUMPED\") (> (length process-environment) 0) \
                 zz-after-pdump-load)",
            )
            .read()
            .expect("parses")
            .expect("a form"),
            &mut env,
        )
        .expect("pdumper-stats");
    let stats = call(&mut restored, "prin1-to-string", &[stats], &mut env).expect("print");
    assert_eq!(
        string_like(&stats).expect("printed").text,
        format!("((dumped-with-pdumper . t) {:?} nil t t)", path.display())
    );
}

#[test]
fn native_units_and_functions_round_trip_through_the_image() {
    // pdumper.c:dump_native_comp_unit / dump_subr and the late and very
    // late relocations (D14/D15): a session that compiled and loaded a
    // named function and an anonymous lambda dumps them once
    // `load--fixup-all-elns' (loadup.el, under the Makefile's --bin-dest
    // and --eln-dest) has turned each unit's file into its pair of
    // executable-relative paths -- a unit still naming a string is refused
    // with GNU's error -- and a fresh process-state interpreter that loads
    // the image reopens the unit, resolves both functions by their C
    // names, fixes up the lambda's impure relocation, registers the unit
    // under its resolved file, and runs the native code.  A unit whose
    // file has gone fails the load as dynlib_open_for_eln fails it.
    if !crate::lisp::native_comp::NativeCompilerState::available() {
        eprintln!("libgccjit is not available: native round trip not tested");
        return;
    }
    use super::pdumper::{PdumperLoadError, pdumper_load};
    let mut interp = crate::test_support::initialized_upstream_batch_interpreter();
    let mut env = crate::lisp::types::Env::new();
    let eval = |interp: &mut crate::lisp::eval::Interpreter, env: &mut Env, program: &str| {
        let form = Reader::new(program)
            .read()
            .expect("program parses")
            .expect("a form");
        let value = interp
            .eval(&form, env)
            .unwrap_or_else(|error| panic!("{program}: {error:?}"));
        let printed = call(interp, "prin1-to-string", &[value], env).expect("print");
        string_like(&printed).expect("printed").text
    };
    // The unit is compiled from a file into the eln cache: a form compiled
    // by `native-compile' lives in `temporary-file-directory', whose
    // short name `load--fixup-all-elns' cannot take a ten-character
    // suffix of (GNU signals args-out-of-range there too).
    let source_directory =
        std::env::temp_dir().join(format!("emaxx-d14-source-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&source_directory);
    std::fs::create_dir_all(&source_directory).expect("create the source directory");
    let compiled = eval(
        &mut interp,
        &mut env,
        &format!(
            r#"(progn
             (require 'comp)
             (let ((source (expand-file-name "zz-native.el" {:?})))
               (with-temp-file source
                 (insert ";;; -*- lexical-binding: t -*-\n"
                         "(defun zz-native-add (a b) \"Add A and B.\" (+ a b))\n"
                         "(defun zz-native-make () (lambda (x) (* x 3)))\n"
                         "(defvar zz-native-lambda (zz-native-make))\n"))
               (let ((comp-running-batch-compilation t) (comp-no-spawn nil))
                 (load (native-compile source) nil t)))
             (list (native-comp-function-p (symbol-function 'zz-native-add))
                   (native-comp-function-p zz-native-lambda)
                   (zz-native-add 1 2) (funcall zz-native-lambda 5)
                   (stringp (native-comp-unit-file
                             (subr-native-comp-unit (symbol-function 'zz-native-add))))
                   (eq (subr-native-comp-unit zz-native-lambda)
                       (subr-native-comp-unit (symbol-function 'zz-native-add)))
                   (documentation 'zz-native-add)))"#,
            source_directory.display()
        ),
    );
    assert_eq!(compiled, "(t t 3 15 t t \"Add A and B.\n\n(fn A B)\")");
    let path = std::env::temp_dir().join(format!("emaxx-d14-native-{}.pdmp", std::process::id()));
    let _ = std::fs::remove_file(&path);
    // Without the fixup the unit's file is a string: refused.  The two
    // variables are bound to nil for this: a process that started from
    // the harness image carries the values that image was dumped under,
    // as GNU's emacs.pdmp carries the build's --bin-dest and --eln-dest.
    let refused = eval(
        &mut interp,
        &mut env,
        &format!(
            "(let ((load--bin-dest-dir nil) (load--eln-dest-dir nil))
               (condition-case error-data (dump-emacs-portable {:?}) (error error-data)))",
            path.display()
        ),
    );
    assert_eq!(refused, "(error \"trying to dump non fixed-up eln file\")");
    assert_eq!(std::fs::metadata(&path).expect("refused output").len(), 0);
    // loadup.el under `--bin-dest DIR --eln-dest DIR': the fixup runs
    // inside dump-emacs-portable and the dump completes.  The eln
    // destination is a directory holding no units: dump_do_dump_relocation
    // decides installed-or-local once, by the first unit, and a session
    // holding the preloaded units of the source tree beside this unit of
    // its cache (the Darwin startup) has no single installed root, so
    // every unit resolves through its build path here.
    let eln_destination = source_directory.join("eln-dest");
    std::fs::create_dir_all(&eln_destination).expect("create the eln destination");
    let dumped = eval(
        &mut interp,
        &mut env,
        &format!(
            "(let ((load--bin-dest-dir invocation-directory)
                   (load--eln-dest-dir {:?}))
               (list (dump-emacs-portable {:?})
                     (consp (native-comp-unit-file
                             (subr-native-comp-unit (symbol-function 'zz-native-add))))
                     (consp (native-comp-unit-file (subr-native-comp-unit zz-native-lambda)))))",
            format!("{}/", eln_destination.display()),
            path.display()
        ),
    );
    assert_eq!(dumped, "(nil t t)");
    let unit_file = eval(
        &mut interp,
        &mut env,
        "(expand-file-name (cdr (native-comp-unit-file (subr-native-comp-unit zz-native-lambda))) invocation-directory)",
    );
    let unit_file = std::path::PathBuf::from(unit_file.trim_matches('"'));
    assert!(unit_file.is_file(), "{}", unit_file.display());
    let _ = std::fs::remove_dir_all(&source_directory);
    // The writer's process closes its units before the image is loaded
    // here: dlopen hands the same handle back while a unit is open, and
    // GNU never loads a dump into the process that wrote it.
    drop(interp);

    let mut restored = crate::lisp::eval::Interpreter::new();
    pdumper_load(&path, &mut restored).unwrap_or_else(|error| panic!("pdumper_load: {error:?}"));
    let mut restored_env = crate::lisp::types::Env::new();
    let answers = eval(
        &mut restored,
        &mut restored_env,
        r#"(let* ((named (symbol-function 'zz-native-add))
                  (unit (subr-native-comp-unit zz-native-lambda))
                  (file (native-comp-unit-file unit)))
             (list (zz-native-add 1 2) (funcall zz-native-lambda 5)
                   (native-comp-function-p named) (subr-native-elisp-p zz-native-lambda)
                   (subr-arity named) (func-arity zz-native-lambda)
                   (stringp file) (file-exists-p file)
                   (eq unit (subr-native-comp-unit named))
                   (eq unit (gethash file comp-loaded-comp-units-h))
                   (documentation 'zz-native-add)
                   (condition-case error-data (zz-native-add 1) (error (car error-data)))))"#,
    );
    assert_eq!(
        answers,
        "(3 15 t t (2 . 2) (1 . 1) t t t t \"Add A and B.\n\n(fn A B)\" wrong-number-of-arguments)"
    );
    let resolved = eval(
        &mut restored,
        &mut restored_env,
        "(native-comp-unit-file (subr-native-comp-unit zz-native-lambda))",
    );
    assert_eq!(
        std::path::PathBuf::from(resolved.trim_matches('"'))
            .canonicalize()
            .expect("the resolved unit file exists"),
        unit_file.canonicalize().expect("the unit file exists")
    );
    drop(restored);

    // dynlib_open_for_eln fails: "Error using execdir" on stderr and the
    // dynamic loader's message as the error.
    let moved = unit_file.with_extension("eln.moved");
    std::fs::rename(&unit_file, &moved).expect("move the unit away");
    let mut fresh = crate::lisp::eval::Interpreter::new();
    let failed = pdumper_load(&path, &mut fresh);
    std::fs::rename(&moved, &unit_file).expect("move the unit back");
    let _ = std::fs::remove_file(&path);
    let file_name = unit_file
        .file_name()
        .expect("unit file name")
        .to_string_lossy()
        .into_owned();
    assert!(
        matches!(&failed, Err(PdumperLoadError::Error(message)) if message.contains(&file_name)),
        "{failed:?}"
    );
}

#[test]
fn fixture_image_directory_dumps_once_and_starts_every_later_boot_from_it() {
    // Rust-only, the harness's shared loadup image: with
    // EMAXX_FIXTURE_IMAGE_DIR set, the first batch startup builds the
    // loadup state and dumps it (loadup.el's own final act), the second
    // starts from that file (emacs.c's load_pdump of emacs.pdmp), and
    // both answer the same; the file is named by the build's fingerprint.
    let upstream = crate::compat::project_root().join("../emacs");
    let load_path =
        crate::compat::emaxx_upstream_load_path(&upstream).expect("upstream GNU Emacs load path");
    let directory =
        std::env::temp_dir().join(format!("emaxx-fixture-images-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&directory);
    let options = || crate::batch::BatchRunOptions {
        load_path: load_path.clone(),
        ..Default::default()
    };
    let programs = [
        "(list (featurep 'subr-x) (fboundp 'when-let) (macrop 'when) purify-flag)",
        "(list (fboundp 'forward-sexp) (fboundp 'beginning-of-defun-raw) (fboundp 'move-to-left-margin))",
        "(list (key-binding [?\\M-x]) (key-binding [?\\C-x ?\\C-f]) (keymapp (keymap-parent (current-local-map))))",
        "(list command-line-processed noninteractive custom-delayed-init-variables)",
        "(with-current-buffer \"*Messages*\" (buffer-string))",
        "(list (buffer-name) (mapcar #'buffer-name (buffer-list)) (length load-path))",
        "(with-temp-buffer (insert \"abc\") (upcase-region 1 3) (buffer-string))",
        "(list (getenv \"HOME\") (car command-line-args) (car exec-path))",
    ];
    let observe = |interp: &mut crate::lisp::eval::Interpreter| {
        programs.map(|program| {
            let mut env = crate::lisp::types::Env::new();
            let form = Reader::new(program)
                .read()
                .expect("program parses")
                .expect("a form");
            let value = interp
                .eval(&form, &mut env)
                .unwrap_or_else(|error| panic!("{program}: {error:?}"));
            let printed = call(interp, "prin1-to-string", &[value], &mut env).expect("print");
            string_like(&printed).expect("printed").text
        })
    };
    let _env_write = crate::compat::lock_boot_environment_for_write();
    struct RestoreFixtureDirectory(Option<std::ffi::OsString>);
    impl Drop for RestoreFixtureDirectory {
        fn drop(&mut self) {
            // SAFETY: The boot-environment write guard outlives this restore.
            unsafe {
                match &self.0 {
                    Some(previous) => std::env::set_var("EMAXX_FIXTURE_IMAGE_DIR", previous),
                    None => std::env::remove_var("EMAXX_FIXTURE_IMAGE_DIR"),
                }
            }
        }
    }
    let _restore = RestoreFixtureDirectory(std::env::var_os("EMAXX_FIXTURE_IMAGE_DIR"));
    // SAFETY: The boot-environment write guard covers the mutation and both boots.
    unsafe {
        std::env::set_var("EMAXX_FIXTURE_IMAGE_DIR", &directory);
    }
    let mut first = crate::batch::initialize_batch_interpreter(&options())
        .unwrap_or_else(|error| panic!("the dumping boot: {error}"));
    assert!(!first.dump_loaded_p());
    let first_answers = observe(&mut first);
    let images = std::fs::read_dir(&directory)
        .expect("fixture image directory")
        .map(|entry| entry.expect("fixture directory entry").file_name())
        .map(|name| name.to_string_lossy().into_owned())
        .filter(|name| name.ends_with(".pdmp"))
        .collect::<Vec<_>>();
    let fingerprint = crate::lisp::primitives::pdumper::image::executable_fingerprint()[..4]
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect::<String>();
    assert_eq!(images.len(), 1, "{images:?}");
    assert!(
        images[0].starts_with(&format!("loadup-{fingerprint}-")),
        "{images:?}"
    );
    // GNU loads the image in a fresh process. Release the writer's native
    // units before dlopen restores their relocation slots from the image.
    drop(first);
    let mut second = crate::batch::initialize_batch_interpreter(&options())
        .unwrap_or_else(|error| panic!("the boot from the image: {error}"));
    assert!(second.dump_loaded_p());
    for ((program, first), second) in programs
        .into_iter()
        .zip(first_answers)
        .zip(observe(&mut second))
    {
        assert_eq!(second, first, "{program}");
    }
    let _ = std::fs::remove_dir_all(&directory);
}

#[test]
fn replace_match_on_a_string_returns_concat3_multibyteness() {
    // search.c:Freplace_match with STRING returns concat3 (before, newtext,
    // after): multibyte when STRING or NEWTEXT is.  burmese.el builds its
    // composition regexp by replacing ASCII keys in an ASCII pattern with
    // multibyte pieces; the result was left unibyte with characters above
    // 255, a string GNU cannot hold (the image writer found it).
    let program = r#"
        (list
         (multibyte-string-p (replace-regexp-in-string "V" "္" "aVb" t t))
         (progn (string-match "V" "aVb")
                (multibyte-string-p (replace-match "္" t t "aVb")))
         (progn (string-match "V" "aVb")
                (multibyte-string-p (replace-match "x" t t "aVb")))
         (progn (string-match "V" "a္Vb")
                (multibyte-string-p (replace-match "x" t t "a္Vb")))
         (let ((case-fold-search nil))
           (string-bytes (replace-regexp-in-string "K" "[ငၚ]်္"
                                                   "\\(K\\)?C" t t)))
         (multibyte-string-p (aref (car (aref composition-function-table #x1000)) 0))
         (string-bytes (aref (car (aref composition-function-table #x1000)) 0)))"#;
    assert_oracle_contract_matches_interpreter(
        program,
        "(t t nil t 20 t 228)",
        "replace-match multibyteness",
    );
}

#[test]
fn compiled_regexp_introspection_preserves_the_real_backend_boundary() {
    let contract_program = r#"
        (list
         (subr-arity (symbol-function 're--describe-compiled))
         (condition-case error-data
             (re--describe-compiled "[" t)
           (error (car error-data)))
         (let ((raw (re--describe-compiled "a" t)))
           (list (stringp raw)
                 (multibyte-string-p raw)
                 (string-to-list raw))))"#;
    let contract_expected = "((1 . 2) invalid-regexp (t nil (2 1 97 1)))";
    assert_upstream_primitive_contract(&format!("(prin1 {contract_program})"), contract_expected);

    let boundary_program = r#"
        (list
         (subr-arity (symbol-function 're--describe-compiled))
         (condition-case error-data
             (re--describe-compiled "[" t)
           (error (car error-data)))
         (condition-case error-data
             (re--describe-compiled "a")
           (error error-data))
         (condition-case error-data
             (re--describe-compiled "a" t)
           (error error-data)))"#;
    // search.c:Fre__describe_compiled: GNU without --enable-checking
    // refuses the description but returns the raw bytecode (exactn 1 ?a,
    // succeed).
    let boundary_expected = "((1 . 2) invalid-regexp \
         (error \"Not available: rebuild with --enable-checking\") \"\\2\\1a\\1\")";
    let mut interp = Interpreter::new();
    let mut env = crate::lisp::types::Env::new();
    let form = Reader::new(boundary_program)
        .read()
        .expect("compiled-regexp boundary program should parse")
        .expect("compiled-regexp boundary program should contain a form");
    let actual = interp
        .eval(&form, &mut env)
        .expect("compiled-regexp boundary should be catchable");
    let expected = Reader::new(boundary_expected)
        .read()
        .expect("compiled-regexp boundary expectation should parse")
        .expect("compiled-regexp boundary expectation should contain a form");
    assert!(
        values_equal(&interp, &actual, &expected).expect("equal"),
        "compiled-regexp boundary was not explicit:\nactual: {actual:?}\nexpected: {expected:?}"
    );
}

#[test]
fn memory_use_counts_exposes_the_allocation_telemetry_boundary_honestly() {
    // alloc.c:Fmemory_use_counts: no arguments, seven natural numbers.
    assert_oracle_contract_matches_interpreter(
        r#"(let ((counts (memory-use-counts)))
            (list
             (subr-arity (symbol-function 'memory-use-counts))
             (length counts)
             (mapcar #'natnump counts)))"#,
        "((0 . 0) 7 (t t t t t t t))",
        "memory-use-counts contract",
    );
}

#[test]
fn memory_use_counts_counts_actual_allocations_by_category() {
    // Each delta is taken against the same measurement around an
    // allocation-free (or empty) form, so the measurement's own consing
    // cancels. The values are alloc.c's increments: one per cons, float,
    // symbol and string, the words asked for by allocate_vectorlike, and the
    // string's bytes (two per `é' in a multibyte string). Bool vectors are
    // not compared: Emaxx keeps their bits as one host-side value per bit
    // outside the Lisp heap (an open representation difference), so only
    // their record object is counted, where GNU counts the packed words.
    assert_oracle_contract_matches_interpreter(
        r#"(let ((delta (lambda (index thunk)
                         (let ((before (nth index (memory-use-counts))))
                           (funcall thunk)
                           (- (nth index (memory-use-counts)) before)))))
            (list
             (- (funcall delta 0 (lambda () (make-list 100 nil)))
                (funcall delta 0 (lambda () (make-list 0 nil))))
             (- (funcall delta 1 (lambda () (float 3)))
                (funcall delta 1 (lambda () (float 3.0))))
             (- (funcall delta 2 (lambda () (make-vector 10 nil)))
                (funcall delta 2 (lambda () (make-vector 0 nil))))
             (- (funcall delta 3 (lambda () (make-symbol "x")))
                (funcall delta 3 (lambda () "x")))
             (- (funcall delta 4 (lambda () (make-string 5 ?a)))
                (funcall delta 4 (lambda () (make-string 0 ?a))))
             (- (funcall delta 4 (lambda () (make-string 3 ?é)))
                (funcall delta 4 (lambda () (make-string 0 ?é))))
             (- (funcall delta 6 (lambda () (make-string 5 ?a)))
                (funcall delta 6 (lambda () (make-string 0 ?a))))))"#,
        "(100 1 10 1 5 6 1)",
        "allocation counter deltas",
    );
}

#[test]
fn intervals_consed_counts_make_interval_calls() {
    // alloc.c:make_interval raises `intervals-consed' once an interval:
    // create_root_interval, each split_interval_left and _right, and
    // copy_intervals and reproduce_tree for every interval they copy
    // (Fcopy_sequence, substring, buffer-string, the printer's pruned
    // copy), with the deleted text record_change and casify_region make
    // even in a buffer without undo.
    assert_oracle_contract_matches_interpreter(
        r##"(let ((s3 (concat (propertize "ab" 'face 'bold) "cd" (propertize "ef" 'x 1))))
            (mapcar (lambda (thunk)
                      (let ((before intervals-consed))
                        (funcall thunk)
                        (- intervals-consed before)))
                    (list (lambda () (propertize "abc" 'face 'bold))
                          (lambda () (concat "abc" "def"))
                          (lambda () (concat (propertize "ab" 'face 'bold) "cd" (propertize "ef" 'x 1)))
                          (lambda () (copy-sequence s3))
                          (lambda () (substring s3 1 5))
                          (lambda () (substring s3 0 1))
                          (lambda () (let ((s (copy-sequence "abcdef"))) (put-text-property 2 4 'a 1 s)))
                          (lambda () (format "%s-%s" (propertize "a" 'x 1) "b"))
                          (lambda () (with-temp-buffer (insert s3) (buffer-string)))
                          (lambda () (with-temp-buffer (insert "abcdefgh") (put-text-property 2 6 'a 1) (goto-char 4) (insert "XY")))
                          (lambda () (with-temp-buffer (insert s3) (delete-region 2 5)))
                          (lambda () (with-temp-buffer (insert s3) (upcase-region 1 7)))
                          (lambda () (with-temp-buffer (insert s3) (subst-char-in-region 1 7 ?b ?Q)))
                          (lambda () (car (read-from-string "#(\"abcd\" 0 1 (a 1) 2 4 (b 2))")))
                          (lambda () (prin1-to-string s3)))))"##,
        "(1 0 5 3 3 1 3 3 6 5 3 6 4 3 3)",
        "intervals-consed deltas",
    );
}

#[test]
fn float_returns_a_float_argument_itself() {
    // floatfns.c:Ffloat returns a float argument unchanged (no new object);
    // an integer argument makes a new float.
    assert_oracle_contract_matches_interpreter(
        "(let ((f 1.5)) (list (eq f (float f)) (eq 2.0 (float 2)) (float 2)))",
        "(t nil 2.0)",
        "float identity",
    );
}

#[test]
fn allocation_counter_variables_forward_to_the_counters() {
    // lread.c:defvar_int: reads and stores reach the C counter, so a store
    // restarts the count, `let' restores the outer word on exit (dropping
    // what was counted inside), stores are integer-checked, collection never
    // lowers a counter, and `makunbound' makes the symbol plain while the
    // counter itself keeps counting for `memory-use-counts'.
    assert_oracle_contract_matches_interpreter(
        r#"(list
            (progn (setq vector-cells-consed 7) (make-vector 3 nil) vector-cells-consed)
            (= vector-cells-consed (nth 2 (memory-use-counts)))
            (progn (setq vector-cells-consed 100)
                   (let ((vector-cells-consed 0)) (make-vector 5 nil))
                   vector-cells-consed)
            (condition-case err (setq vector-cells-consed 'x) (error err))
            (condition-case err (setq vector-cells-consed 1.5) (error err))
            (let* ((before (memory-use-counts))
                   (after (progn (garbage-collect) (memory-use-counts)))
                   (ok t))
              (while before
                (unless (<= (car before) (car after)) (setq ok nil))
                (setq before (cdr before) after (cdr after)))
              ok)
            (progn (makunbound 'symbols-consed)
                   (list (boundp 'symbols-consed)
                         (progn (setq symbols-consed 'plain) symbols-consed)
                         (let ((before (nth 3 (memory-use-counts))))
                           (make-symbol "y")
                           (> (nth 3 (memory-use-counts)) before)))))"#,
        "(10 t 100 (wrong-type-argument integerp x) (wrong-type-argument integerp 1.5) t (nil plain t))",
        "allocation counter forwarding",
    );
}

#[cfg(unix)]
#[test]
fn call_process_reports_signal_termination_in_both_entry_points() {
    let program = r#"(list
        (call-process "/bin/sh" nil nil nil "-c" "exit 7")
        (stringp (call-process "/bin/sh" nil nil nil "-c" "kill -TERM $$"))
        (stringp (call-process-region (point-min) (point-max)
                    "/bin/sh" nil nil nil "-c" "kill -TERM $$")))"#;
    assert_upstream_primitive_contract(&format!("(prin1 {program})"), "(7 t t)");
    let mut interp = Interpreter::new();
    let actual = interp
        .eval(
            &Reader::new(program)
                .read()
                .expect("subprocess program should parse")
                .expect("subprocess program should contain a form"),
            &mut Env::new(),
        )
        .expect("synchronous subprocess results");
    assert_eq!(actual, Value::list([Value::Integer(7), Value::T, Value::T]));
}

#[cfg(unix)]
#[test]
fn module_load_validates_and_initializes_real_libraries() {
    use std::sync::atomic::{AtomicU64, Ordering};

    static PROBE_ID: AtomicU64 = AtomicU64::new(0);
    let directory = std::env::temp_dir().join(format!(
        "emaxx-module-probe-{}-{}",
        std::process::id(),
        PROBE_ID.fetch_add(1, Ordering::Relaxed)
    ));
    std::fs::create_dir_all(&directory).expect("module probe directory should be created");
    let source = directory.join("probe.c");
    std::fs::write(
        &source,
        "int plugin_is_GPL_compatible;\n\
         int emacs_module_init(void *runtime) { (void) runtime; return 0; }\n",
    )
    .expect("module probe source should be written");
    #[cfg(target_os = "macos")]
    let library = directory.join("probe.dylib");
    #[cfg(not(target_os = "macos"))]
    let library = directory.join("probe.so");
    let mut compiler = std::process::Command::new(
        std::env::var_os("CC").unwrap_or_else(|| std::ffi::OsString::from("cc")),
    );
    // The child gets the process's startup environment, as a GNU child
    // built from `process-environment' would: an in-process libgccjit
    // compile earlier in this test process exports its own
    // GCC_EXEC_PREFIX into the host environment, which the system cc
    // cannot use.
    compiler.env_clear().envs(
        crate::lisp::eval::initial_process_environment()
            .iter()
            .cloned(),
    );
    #[cfg(target_os = "macos")]
    compiler.arg("-dynamiclib");
    #[cfg(not(target_os = "macos"))]
    compiler.args(["-shared", "-fPIC"]);
    let status = compiler
        .arg(&source)
        .arg("-o")
        .arg(&library)
        .status()
        .expect("module probe compiler should run");
    assert!(status.success(), "module probe should compile");

    let contract_program = r#"
        (list
         (subr-arity (symbol-function 'module-load))
         (condition-case error-data
             (module-load 1)
           (error (car error-data)))
         (condition-case error-data
             (module-load "/definitely/missing/emaxx-module.so")
           (error (car error-data)))
         (get 'module-open-failed 'error-conditions)
         (get 'module-not-gpl-compatible 'error-conditions)
         (get 'missing-module-init-function 'error-conditions)
         (get 'module-init-failed 'error-conditions))"#;
    let contract_expected = "((1 . 1) wrong-type-argument module-open-failed \
        (module-open-failed module-load-failed error) \
        (module-not-gpl-compatible module-load-failed error) \
        (missing-module-init-function module-load-failed error) \
        (module-init-failed module-load-failed error))";
    assert_upstream_primitive_contract(&format!("(prin1 {contract_program})"), contract_expected);

    let mut interp = Interpreter::new();
    let mut env = crate::lisp::types::Env::new();
    let contract_form = Reader::new(contract_program)
        .read()
        .expect("dynamic-module contract should parse")
        .expect("dynamic-module contract should contain a form");
    let contract_actual = interp
        .eval(&contract_form, &mut env)
        .expect("dynamic-module validation conditions should be catchable");
    let contract_expected = Reader::new(contract_expected)
        .read()
        .expect("dynamic-module expectation should parse")
        .expect("dynamic-module expectation should contain a form");
    assert!(
        values_equal(&interp, &contract_actual, &contract_expected).expect("equal"),
        "dynamic-module validation conditions diverged:\nactual: {contract_actual:?}"
    );

    let form = Value::list([
        Value::symbol("condition-case"),
        Value::symbol("error-data"),
        Value::list([
            Value::symbol("module-load"),
            Value::String(library.display().to_string().into()),
        ]),
        Value::list([Value::symbol("error"), Value::symbol("error-data")]),
    ]);
    let actual = interp
        .eval(&form, &mut env)
        .expect("dynamic-module ABI boundary should be catchable");
    let expected = Value::T;
    assert!(
        values_equal(&interp, &actual, &expected).expect("equal"),
        "a successful module initializer returns t:\nactual: {actual:?}"
    );
    std::fs::remove_dir_all(directory).expect("module probe directory should be removed");
}

#[test]
fn every_claimed_gnu_c_primitive_mirror_has_an_exact_native_surface_contract() {
    use super::generated_gnu_c_primitives::{
        GNU_C_PRIMITIVE_AVAILABLE_COUNT, GNU_C_PRIMITIVE_SOURCE_COUNT, GNU_C_PRIMITIVES,
    };

    assert_eq!(GNU_C_PRIMITIVES.len(), GNU_C_PRIMITIVE_SOURCE_COUNT);
    assert_eq!(
        GNU_C_PRIMITIVES
            .iter()
            .filter(|contract| contract.arity.is_some())
            .count(),
        GNU_C_PRIMITIVE_AVAILABLE_COUNT
    );
    assert!(
        GNU_C_PRIMITIVES
            .windows(2)
            .all(|pair| pair[0].name < pair[1].name),
        "generated GNU C primitive inventory must stay sorted and unique"
    );

    let available = GNU_C_PRIMITIVES
        .iter()
        .filter(|contract| contract.arity.is_some())
        .collect::<Vec<_>>();
    let is_native_mirror = |name: &str| has_dispatch_handler(name) || is_special_form_name(name);
    let missing = available
        .iter()
        .copied()
        .filter(|contract| !is_native_mirror(contract.name))
        .collect::<Vec<_>>();
    let mut mirrored = Vec::new();
    let mut issues = Vec::new();
    for contract in available
        .iter()
        .copied()
        .filter(|contract| is_native_mirror(contract.name))
    {
        mirrored.push(contract.name);
        if generated_builtin_arities::generated_builtin_arity(contract.name) != contract.arity {
            issues.push(format!(
                "{} [{}]: arity {:?}, expected {:?}",
                contract.name,
                contract.origins,
                generated_builtin_arities::generated_builtin_arity(contract.name),
                contract.arity
            ));
        }
        if is_special_form_name(contract.name) != contract.special_form {
            issues.push(format!(
                "{} [{}]: special_form {}, expected {}",
                contract.name,
                contract.origins,
                is_special_form_name(contract.name),
                contract.special_form
            ));
        }
        if generated_builtin_arities::generated_builtin_command_p(contract.name) != contract.command
        {
            issues.push(format!(
                "{} [{}]: command {}, expected {}",
                contract.name,
                contract.origins,
                generated_builtin_arities::generated_builtin_command_p(contract.name),
                contract.command
            ));
        }
        if !contract.special_form && !has_dispatch_handler(contract.name) {
            issues.push(format!(
                "{} [{}]: claimed native without a Rust dispatch route",
                contract.name, contract.origins
            ));
        }
    }

    let fingerprint = |names: &[&str]| {
        // Stable FNV-1a over the sorted, NUL-separated names.  The exact
        // fingerprint prevents a removed dispatch arm from silently moving
        // from the mirrored inventory into the missing inventory.
        names.iter().fold(0xcbf29ce484222325_u64, |mut hash, name| {
            for byte in name.bytes().chain(std::iter::once(0)) {
                hash ^= u64::from(byte);
                hash = hash.wrapping_mul(0x100000001b3);
            }
            hash
        })
    };
    let missing_names = missing
        .iter()
        .map(|contract| contract.name)
        .collect::<Vec<_>>();
    assert_eq!(
        (mirrored.len(), fingerprint(&mirrored)),
        // Regeneration excludes three native-Elisp owners mistaken for C:
        // frame-windows-min-size, x-begin-drag, and x-file-dialog.
        (1_417, 10_595_795_051_582_904_188),
        "GNU C mirror inventory changed; audit the exact addition/removal before updating this snapshot"
    );
    assert_eq!(
        (missing_names.len(), fingerprint(&missing_names)),
        (0, 14_695_981_039_346_656_037),
        "GNU C missing-primitive inventory changed; audit the exact addition/removal before updating this snapshot"
    );
    if std::env::var_os("EMAXX_PRINT_NATIVE_PRIMITIVE_AUDIT").is_some() {
        let mut by_origin = std::collections::BTreeMap::<&str, Vec<&str>>::new();
        for contract in missing {
            by_origin
                .entry(contract.origins)
                .or_default()
                .push(contract.name);
        }
        for (origins, names) in by_origin {
            eprintln!("{} ({})\n  {}", origins, names.len(), names.join(" "));
        }
    }
    assert!(
        issues.is_empty(),
        "{} GNU C primitive surface mismatches across {} Emaxx mirrors:\n{}",
        issues.len(),
        mirrored.len(),
        issues.join("\n")
    );
}

#[test]
fn every_literal_native_dispatch_arm_is_owned_by_gnu_c() {
    let quoted_name =
        regex::Regex::new(r#"\"([^\"]+)\""#).expect("compile native-dispatch pattern extractor");
    let mut patterns = Vec::new();
    super::dispatch::visit_handled_patterns(&mut |module, pattern| {
        patterns.push((module, pattern))
    });

    let mut names = std::collections::BTreeMap::new();
    let mut nonliteral_patterns = Vec::new();
    for (module, pattern) in patterns {
        let extracted = quoted_name
            .captures_iter(pattern)
            .map(|capture| capture[1].to_string())
            .collect::<Vec<_>>();
        if extracted.is_empty() {
            nonliteral_patterns.push(format!("{module}: {pattern}"));
        } else {
            for name in extracted {
                names.insert(name, module);
            }
        }
    }
    assert!(
        nonliteral_patterns.is_empty(),
        "native dispatch contains patterns that the ownership audit cannot enumerate: {}",
        nonliteral_patterns.join(", ")
    );

    // Dispatch source is a cross-platform union.  An arm must belong to at
    // least one contracted GNU host, while `is_builtin' separately selects
    // only the current host's generated ownership manifest.  alloc.c's
    // variable watchers are GNU subrs made without DEFUN.
    let non_gnu = names
        .iter()
        .filter(|(name, _)| {
            !crate::lisp::native_comp::abi::C_VARIABLE_WATCHERS
                .iter()
                .any(|subr| subr.name == name.as_str())
                && super::generated_gnu_c_primitives::generated_gnu_c_primitive_available(name)
                    != Some(true)
                && super::generated_gnu_c_primitives_linux::generated_gnu_c_primitive_available(
                    name,
                ) != Some(true)
        })
        .map(|(name, module)| format!("{module}: {name}"))
        .collect::<Vec<_>>();
    assert!(
        non_gnu.is_empty(),
        "{} native dispatch arms are not owned by GNU C:\n{}",
        non_gnu.len(),
        non_gnu.join("\n")
    );
}

#[test]
fn file_notification_primitives_follow_the_host_contract() {
    #[cfg(target_os = "macos")]
    {
        assert!(is_builtin("kqueue-add-watch"));
        assert!(!is_builtin("inotify-add-watch"));
    }
    #[cfg(target_os = "linux")]
    {
        assert!(is_builtin("inotify-add-watch"));
        assert!(!is_builtin("kqueue-add-watch"));
    }
}

#[test]
fn native_dispatch_fails_closed_at_the_gnu_c_boundary() {
    let mut interp = Interpreter::new();
    let mut env = crate::lisp::types::Env::new();

    for name in [
        "semantic-go-to-tag",
        "srecode-template-get-table",
        "bounds-of-thing-at-point",
        "advice-add",
        "advice-remove",
        "advice-member-p",
        "add-function",
        "remove-function",
        "define-advice",
        concat!("emaxx", "--apply-around-advice"),
        concat!("emaxx", "--apply-after-advice"),
        concat!("emaxx", "--cl-generic-remove-loadhist-method"),
        concat!("emaxx", "--oclosure-slot"),
    ] {
        assert!(
            !is_builtin(name),
            "{name} is not a GNU C primitive and must not be Lisp-callable Rust"
        );
        assert!(
            !matches!(
                interp.raw_function_binding(name, &env).map(|v| v.kind()),
                Some(Kind::BuiltinFunc(_))
            ),
            "{name} acquired a native function cell outside GNU's C manifest"
        );
        assert!(
            matches!(
                call(&mut interp, name, &[], &mut env).map_err(LispError::into_kind),
                Err(LispErrorKind::Signal(message)) if message == format!("Unknown function: {name}")
            ),
            "direct dispatch bypassed the GNU C ownership boundary for {name}"
        );
    }
}

#[test]
fn generated_rust_manifests_never_contain_trailing_whitespace() {
    for (name, source) in [(
        "builtin arities",
        include_str!("generated_builtin_arities.rs"),
    )] {
        for (line_index, line) in source.lines().enumerate() {
            assert!(
                !line.ends_with(' ') && !line.ends_with('\t'),
                "{name} generator emitted trailing whitespace on line {}",
                line_index + 1
            );
        }
    }
}

#[test]
fn builtin_metadata_covers_the_whole_c_manifest_without_lisp_string_leakage() {
    use super::generated_gnu_c_primitives::GNU_C_PRIMITIVES;

    for contract in GNU_C_PRIMITIVES {
        let Some(arity) = contract.arity else {
            continue;
        };
        assert_eq!(
            generated_builtin_arities::generated_builtin_arity(contract.name),
            Some(arity),
            "{} [{}] is missing from generated C primitive arities",
            contract.name,
            contract.origins
        );
        assert_eq!(
            generated_builtin_arities::generated_builtin_command_p(contract.name),
            contract.command,
            "{} [{}] has the wrong generated command identity",
            contract.name,
            contract.origins
        );
    }

    // These are dumped Lisp commands in GNU, not C primitives.  Merely
    // mentioning their condition symbols inside a Rust dispatcher must never
    // move them across the Lisp/native boundary.
    for name in ["beginning-of-buffer", "end-of-buffer"] {
        assert_eq!(
            generated_builtin_arities::generated_builtin_arity(name),
            None,
            "{name} leaked into C metadata from a Rust string literal"
        );
        assert!(
            !generated_builtin_arities::generated_builtin_command_p(name),
            "{name} leaked into C command metadata from a Rust string literal"
        );
    }
}

#[test]
fn project_does_not_ship_lisp_compatibility_facades() {
    let source_dir = crate::compat::project_root().join("src/lisp");
    let mut facades = walkdir::WalkDir::new(&source_dir)
        .into_iter()
        .filter_map(Result::ok)
        .filter(|entry| entry.file_type().is_file())
        .map(|entry| entry.into_path())
        .filter(|path| path.extension().is_some_and(|extension| extension == "el"))
        .collect::<Vec<_>>();
    facades.sort();
    assert!(
        facades.is_empty(),
        "project-owned Lisp compatibility facades can mask missing GNU owners: {facades:?}"
    );
}

/// Patterns from GNU's own Lisp (the resource helpers, a hyphen class,
/// empty shy groups) compile and match as regex-emacs.c does.  In
/// `[\-[:alnum:]]' a backslash is an ordinary character: `\-[' is a
/// reversed (empty) range, `:alnum:' are plain members and the class
/// closes before a literal `]', which `--tofu-policy=' lacks.
#[test]
fn regex_helper_and_rx_patterns_match_like_gnu() {
    let mut interp = Interpreter::new();
    let mut env = crate::lisp::types::Env::new();
    for (pattern, text, expected) in [
        (r"\(?:^\|[^\]\)\(?:\\\\\)*\\", r"ab\\\c", Value::Integer(1)),
        (r"\(?:^\|[^\]\)\(?:\\\\\)*\\.\=", r"x\y", Value::Nil),
        (
            r"-\(?:[\-[:alnum:]]\)+\(?:=\)?",
            "--tofu-policy=",
            Value::Nil,
        ),
        (r"\(?:\)?x\(?:\)*", "x", Value::Integer(0)),
    ] {
        assert_eq!(
            call(
                &mut interp,
                "string-match",
                &[Value::String(pattern.into()), Value::String(text.into())],
                &mut env,
            )
            .expect("match a GNU Lisp pattern"),
            expected,
            "{pattern} against {text}"
        );
    }
}

#[test]
fn subregexp_context_rejects_classes_bounds_and_trailing_escape() {
    let mut interp = crate::test_support::initialized_upstream_batch_interpreter();
    let mut env = crate::lisp::types::Env::new();

    assert_eq!(
        call_via_lisp(
            &mut interp,
            "subregexp-context-p",
            &[Value::String("a[b]".into()), Value::Integer(2)],
            &mut env,
        )
        .expect("inside a character class is not a subregexp context"),
        Value::Nil
    );
    assert_eq!(
        call_via_lisp(
            &mut interp,
            "subregexp-context-p",
            &[Value::String(r"a\(".into()), Value::Integer(3)],
            &mut env,
        )
        .expect("unfinished group is still a subregexp context"),
        Value::T
    );
    assert_eq!(
        call_via_lisp(
            &mut interp,
            "subregexp-context-p",
            &[Value::String(r"a\".into()), Value::Integer(2)],
            &mut env,
        )
        .expect("trailing escape is not a subregexp context"),
        Value::Nil
    );
}

#[test]
fn string_to_syntax_encodes_classes_flags_and_matching_characters() {
    // Keep this public-value contract tied to the pinned GNU implementation,
    // not merely to hand-copied Rust expectations.  This probe is small
    // enough for the fast suite and covers the related char-table boundary.
    assert_upstream_primitive_contract(
        r#"(let ((table (make-syntax-table)) mapped)
              (modify-syntax-entry ?% ". c" table)
              (map-char-table
               (lambda (range syntax)
                 (when (or (equal range ?%)
                           (and (consp range)
                                (<= (car range) ?%)
                                (>= (cdr range) ?%)))
                   (setq mapped syntax)))
               table)
              (prin1
               (list (string-to-syntax ".")
                     (string-to-syntax "-")
                     (string-to-syntax ". 1234")
                     (string-to-syntax "(] 1234")
                     (string-to-syntax "@")
                     (string-to-syntax ". c")
                     (aref table ?%)
                     (char-table-range table ?%)
                     mapped
                     (condition-case error
                         (string-to-syntax "z")
                       (error (list (car error)
                                    (error-message-string error)))))))"#,
        "((1) (0) (983041) (983044 . 93) nil (8388609) (8388609) (8388609) (8388609) (error \"Invalid syntax description letter: z\"))",
    );

    let mut interp = Interpreter::new();
    let mut env = crate::lisp::types::Env::new();

    assert_eq!(
        call(
            &mut interp,
            "string-to-syntax",
            &[Value::String("-".into())],
            &mut env,
        )
        .expect("hyphen whitespace syntax alias"),
        Value::list([Value::Integer(0)])
    );
    assert_eq!(
        call(
            &mut interp,
            "string-to-syntax",
            &[Value::String(".".into())],
            &mut env,
        )
        .expect("punctuation syntax"),
        Value::list([Value::Integer(1)])
    );
    assert_eq!(
        call(
            &mut interp,
            "string-to-syntax",
            &[Value::String(". 1234".into())],
            &mut env,
        )
        .expect("comment flag syntax"),
        Value::list([Value::Integer(983041)])
    );
    assert_eq!(
        call(
            &mut interp,
            "string-to-syntax",
            &[Value::String(". nb".into())],
            &mut env,
        )
        .expect("nested style-b syntax"),
        Value::list([Value::Integer(6291457)])
    );
    assert_eq!(
        call(
            &mut interp,
            "string-to-syntax",
            &[Value::String("(] 1234".into())],
            &mut env,
        )
        .expect("matching paren syntax"),
        Value::cons(Value::Integer(983044), Value::Integer(']' as i64))
    );
    assert_eq!(
        call(
            &mut interp,
            "string-to-syntax",
            &[Value::String("@".into())],
            &mut env,
        )
        .expect("inherit syntax"),
        Value::Nil
    );
    assert_eq!(
        call(
            &mut interp,
            "string-to-syntax",
            &[Value::String(". c".into())],
            &mut env,
        )
        .expect("comment style-c syntax"),
        Value::list([Value::Integer(8_388_609)])
    );
    assert_eq!(
        call(
            &mut interp,
            "string-to-syntax",
            &[Value::String("z".into())],
            &mut env,
        )
        .expect_err("invalid syntax descriptors must signal")
        .to_string(),
        "Invalid syntax description letter: z"
    );
}

#[test]
fn internal_char_font_accepts_gnu_characters_and_checks_position_first() {
    let mut interp = Interpreter::new();
    let mut env = crate::lisp::types::Env::new();
    for character in [0xd800, 0x110000, 0x3fffff] {
        assert_eq!(
            call(
                &mut interp,
                "internal-char-font",
                &[Value::Nil, Value::Integer(character)],
                &mut env
            )
            .expect("GNU character accepted by the initial terminal"),
            Value::Nil,
        );
    }
    for character in [Value::Integer(-1), Value::Integer(0x400000), Value::Nil] {
        assert!(matches!(
            call(&mut interp, "internal-char-font", &[Value::Nil, character], &mut env).map_err(LispError::into_kind),
            Err(LispErrorKind::WrongTypeArgument(predicate, value))
                if predicate == "characterp" && value == character
        ));
    }
    interp.buffer.borrow_mut().insert("A");
    assert_eq!(
        call(
            &mut interp,
            "internal-char-font",
            &[Value::Integer(1), Value::Integer(0x400000)],
            &mut env
        )
        .expect("positive fixnum outside the character range returns nil"),
        Value::Nil,
    );
    assert!(matches!(
        call(&mut interp, "internal-char-font", &[Value::Integer(1), Value::Integer(-1)], &mut env).map_err(LispError::into_kind),
        Err(LispErrorKind::WrongTypeArgument(predicate, value))
            if predicate == "wholenump" && value == Value::Integer(-1)
    ));
    let error = call(
        &mut interp,
        "internal-char-font",
        &[Value::Integer(2), Value::Integer(-1)],
        &mut env,
    )
    .expect_err("check position before the optional character");
    assert!(matches!(error.kind(), LispErrorKind::SignalValue(value)
        if value.car().is_ok_and(|head| head == Value::symbol("args-out-of-range"))));
}

#[test]
fn internal_char_font_matches_the_headless_gnu_font_boundary() {
    assert_upstream_primitive_contract(
        r#"(prin1 (list (internal-char-font nil ?A)
                         (with-temp-buffer
                           (insert "A")
                           (internal-char-font 1))))"#,
        "(nil nil)",
    );

    let mut interp = Interpreter::new();
    let mut env = crate::lisp::types::Env::new();
    assert_eq!(
        call(
            &mut interp,
            "internal-char-font",
            &[Value::Nil, Value::Integer('A' as i64)],
            &mut env,
        )
        .expect("query the headless default font"),
        Value::Nil
    );
    interp.buffer.borrow_mut().insert("A");
    assert_eq!(
        call(
            &mut interp,
            "internal-char-font",
            &[Value::Integer(1)],
            &mut env,
        )
        .expect("query an undisplayed buffer position"),
        Value::Nil
    );
}

#[test]
fn fontp_matches_the_gnu_font_record_contract() {
    assert_upstream_primitive_contract(
        r#"(let ((font (font-spec :name "x")))
              (prin1
               (list (fontp nil)
                     (fontp font)
                     (fontp font 'font-spec)
                     (fontp font 'font-object)
                     (condition-case error
                         (fontp font 'bogus)
                       (error (car error))))))"#,
        "(nil t t nil wrong-type-argument)",
    );

    let mut interp = Interpreter::new();
    let mut env = crate::lisp::types::Env::new();
    let font = call(
        &mut interp,
        "font-spec",
        &[Value::Symbol(":name".into()), Value::String("x".into())],
        &mut env,
    )
    .expect("font-spec should create a font record");
    assert_eq!(
        call(&mut interp, "fontp", &[Value::Nil], &mut env).expect("nil is not a font"),
        Value::Nil
    );
    assert_eq!(
        call(&mut interp, "fontp", std::slice::from_ref(&font), &mut env)
            .expect("font-spec is a font"),
        Value::T
    );
    assert_eq!(
        call(
            &mut interp,
            "fontp",
            &[font, Value::Symbol("font-spec".into())],
            &mut env,
        )
        .expect("font-spec subtype should match"),
        Value::T
    );
    assert_eq!(
        call(
            &mut interp,
            "fontp",
            &[font, Value::Symbol("font-object".into())],
            &mut env,
        )
        .expect("font-object subtype should not match"),
        Value::Nil
    );
    let error = call(
        &mut interp,
        "fontp",
        &[font, Value::Symbol("bogus".into())],
        &mut env,
    )
    .expect_err("invalid font subtype must signal");
    assert_eq!(error.condition_type(), "wrong-type-argument");
}

