#[test]
fn substitute_in_file_name_expands_shell_style_env_vars() {
    let old = std::env::var("EMAXX_SUBST_TEST").ok();
    unsafe {
        std::env::set_var("EMAXX_SUBST_TEST", "value");
    }
    assert_eq!(
        substitute_in_file_name("$EMAXX_SUBST_TEST/${EMAXX_SUBST_TEST}/$$"),
        "value/value/$"
    );
    assert_eq!(substitute_in_file_name("/path///file"), "/file");
    assert_eq!(substitute_in_file_name("path//file"), "/file");
    if let Some(value) = old {
        unsafe {
            std::env::set_var("EMAXX_SUBST_TEST", value);
        }
    } else {
        unsafe {
            std::env::remove_var("EMAXX_SUBST_TEST");
        }
    }
}

#[cfg(target_os = "linux")]
#[test]
fn x_window_properties_validate_the_frame_before_property_arguments() {
    // xfns.c enters decode_window_system_frame before inspecting property
    // names, values or formats. These are real primitives in an X-enabled
    // GNU build even when its current frame is a terminal. Their function
    // cells must also exist so fset installs normal native trampolines.
    let program = r#"(prin1
      (list
        (mapcar (lambda (name)
                  (let ((function (symbol-function name)))
                    (list (subrp function) (subr-arity function))))
                '(x-change-window-property x-window-property
                  x-window-property-attributes x-delete-window-property))
        (mapcar (lambda (form) (condition-case err (eval form t) (error err)))
                '((x-change-window-property 1 2)
                  (x-window-property 1)
                  (x-window-property-attributes 1)
                  (x-delete-window-property 1)
                  (x-change-window-property "p" "v" 17)
                  (x-window-property "p" 17)
                  (x-window-property-attributes "p" 17)
                  (x-delete-window-property "p" 17)
                  (x-change-window-property 1 2 (selected-frame) nil 'bad-format)
                  (x-window-property 1 (selected-frame) 'bad-type)
                  (x-window-property-attributes 1 (selected-frame) 'bad-window)
                  (x-delete-window-property 1 (selected-frame) 'bad-window)))))"#;
    let frame_error = r#"(error "Window system frame should be used")"#;
    let type_error = "(wrong-type-argument frame-live-p 17)";
    let errors = [frame_error; 4]
        .into_iter()
        .chain([type_error; 4])
        .chain([frame_error; 4])
        .collect::<Vec<_>>()
        .join(" ");
    let expected = format!("(((t (2 . 7)) (t (1 . 6)) (t (1 . 3)) (t (1 . 3))) ({errors}))");
    assert_upstream_primitive_contract(program, &expected);
    let mut interp = crate::test_support::initialized_upstream_batch_interpreter();
    let form = Reader::new(program)
        .read()
        .expect("window-property contract is valid Lisp")
        .expect("window-property contract contains a form");
    let value = interp
        .eval(&form, &mut crate::lisp::types::Env::new())
        .expect("window-property contract catches the expected frame errors");
    let expected = Reader::new(&expected)
        .read()
        .expect("expected window-property results are valid Lisp")
        .expect("expected window-property results contain a form");
    assert_eq!(value, expected);
}

#[test]
fn dumped_directory_family_ignores_the_test_harness_variable() {
    // Finding 102: data-directory, doc-directory, installation-directory
    // and emacsclient-program-name were derived from EMACS_TEST_DIRECTORY
    // -- exactly the rule source-directory's own comment bans.  In GNU
    // they are epaths.h constants fixed when the binary is built; here
    // that means the configured checkout's paths, whatever the
    // harness environment says.
    let repo = crate::compat::canonicalize_path(&upstream_emacs_repo())
        .expect("configured GNU checkout")
        .display()
        .to_string();
    let program = concat!(
        "(prin1 (list source-directory data-directory doc-directory installation-directory ",
        "emacsclient-program-name))"
    );
    let expected =
        format!("(\"{repo}/\" \"{repo}/etc/\" \"{repo}/etc/\" \"{repo}/\" \"emacsclient\")");
    assert_upstream_primitive_contract(program, &expected);

    // A hostile EMACS_TEST_DIRECTORY pointing at a fake repo layout --
    // complete with the binaries the old derivation looked for -- must
    // change none of them.
    let unique = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_nanos();
    let fake_root = std::env::temp_dir().join(format!("emaxx-compat-paths-{unique}"));
    let test_dir = fake_root.join("test");
    std::fs::create_dir_all(&test_dir).expect("create test directory");
    std::fs::create_dir_all(fake_root.join("src")).expect("create src directory");
    std::fs::create_dir_all(fake_root.join("lib-src")).expect("create lib-src directory");
    std::fs::create_dir_all(fake_root.join("etc")).expect("create etc directory");
    std::fs::write(fake_root.join("src/emacs"), "").expect("write fake emacs binary");
    std::fs::write(fake_root.join("lib-src/emacsclient"), "")
        .expect("write fake emacsclient binary");

    let _env_write = crate::compat::lock_boot_environment_for_write();
    let old = std::env::var("EMACS_TEST_DIRECTORY").ok();
    let old_configured_source = std::env::var_os("EMAXX_GNU_SOURCE_DIRECTORY");
    unsafe {
        std::env::set_var("EMACS_TEST_DIRECTORY", test_dir.display().to_string());
        std::env::set_var("EMAXX_GNU_SOURCE_DIRECTORY", &fake_root);
    }
    assert_eq!(
        current_invocation_path(),
        std::env::current_exe().expect("current test executable"),
        "EMACS_TEST_DIRECTORY must never redirect Emaxx subprocesses to the GNU oracle"
    );
    assert_eq!(compat_data_directory(), Some(format!("{repo}/etc/")));
    assert_eq!(compat_installation_directory(), Some(format!("{repo}/")));
    assert_eq!(
        crate::compat::configured_gnu_source_root(),
        PathBuf::from(&repo),
        "a runtime environment variable cannot change the configured installation"
    );
    match old_configured_source {
        Some(value) => unsafe { std::env::set_var("EMAXX_GNU_SOURCE_DIRECTORY", value) },
        None => unsafe { std::env::remove_var("EMAXX_GNU_SOURCE_DIRECTORY") },
    }
    if let Some(value) = old {
        unsafe {
            std::env::set_var("EMACS_TEST_DIRECTORY", value);
        }
    } else {
        unsafe {
            std::env::remove_var("EMACS_TEST_DIRECTORY");
        }
    }
    let _ = std::fs::remove_dir_all(&fake_root);
    drop(_env_write);

    // The interpreter's dumped bindings answer the same oracle row.
    let mut interp = crate::test_support::initialized_upstream_batch_interpreter();
    let values = interp
        .eval(
            &Reader::new(
                "(list source-directory data-directory doc-directory installation-directory \
                 emacsclient-program-name)",
            )
            .read_all()
            .expect("read directory-family list")
            .remove(0),
            &mut crate::lisp::types::Env::new(),
        )
        .expect("evaluate directory-family list");
    assert_eq!(values.to_string(), expected);
}

/// filelock.c names a lock with files.el's `make-lock-file-name', which a
/// bare interpreter has not loaded: its value with no
/// `lock-file-name-transforms'.
fn define_make_lock_file_name(interp: &mut Interpreter, env: &mut crate::lisp::types::Env) {
    let definition = Reader::new(
        "(fset 'make-lock-file-name
               (function
                (lambda (filename)
                  (concat (file-name-directory filename) \".#\"
                          (file-name-nondirectory filename)))))",
    )
    .read()
    .expect("read make-lock-file-name")
    .expect("a definition");
    interp
        .eval(&definition, env)
        .expect("define make-lock-file-name");
}

#[test]
fn insert_file_contents_reports_missing_input_as_file_missing() {
    let mut interp = Interpreter::new();
    let mut env = crate::lisp::types::Env::new();
    // A visit unlocks the file before it signals.
    define_make_lock_file_name(&mut interp, &mut env);
    let path = std::env::temp_dir().join(format!(
        "emaxx-missing-input-{}",
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap_or_default()
            .as_nanos()
    ));
    let error = call(
        &mut interp,
        "insert-file-contents",
        &[Value::String(path.display().to_string().into())],
        &mut env,
    )
    .expect_err("a nonexistent input file must signal");

    assert_eq!(error.condition_type(), "file-missing");

    let path = path.display().to_string();
    let error = call(
        &mut interp,
        "insert-file-contents",
        &[Value::String(path.clone().into()), Value::T],
        &mut env,
    )
    .expect_err("visiting a nonexistent input file must still signal");

    assert_eq!(error.condition_type(), "file-missing");
    assert_eq!(interp.buffer.borrow().file.as_deref(), Some(path.as_str()));
    assert!(!interp.buffer.borrow().is_modified());
}

#[test]
fn insert_file_contents_replace_collapses_point_in_the_differing_middle() {
    let mut interp = Interpreter::new();
    let mut env = crate::lisp::types::Env::new();
    define_make_lock_file_name(&mut interp, &mut env);
    let path = std::env::temp_dir().join(format!(
        "emaxx-replace-point-{}",
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap_or_default()
            .as_nanos()
    ));
    std::fs::write(&path, "alpha beta\n").expect("write replace fixture");
    interp.buffer.borrow_mut().insert("changed alpha beta\n");
    interp.buffer.borrow_mut().goto_char(9);

    call(
        &mut interp,
        "insert-file-contents",
        &[
            Value::String(path.display().to_string().into()),
            Value::T,
            Value::Nil,
            Value::Nil,
            Value::Symbol("if-regular".into()),
        ],
        &mut env,
    )
    .expect("replace buffer contents");

    assert_eq!(interp.buffer.borrow().buffer_string(), "alpha beta\n");
    assert_eq!(
        interp.buffer.borrow().point(),
        interp.buffer.borrow().point_min()
    );
    let _ = std::fs::remove_file(path);
}

#[test]
fn system_move_file_to_trash_preserves_gnu_missing_file_contract() {
    let mut interp = Interpreter::new();
    let mut env = crate::lisp::types::Env::new();
    let path = std::env::temp_dir().join(format!(
        "emaxx-missing-trash-input-{}",
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap_or_default()
            .as_nanos()
    ));
    let path = path.display().to_string();
    let error = call(
        &mut interp,
        "system-move-file-to-trash",
        &[Value::String(path.clone().into())],
        &mut env,
    )
    .expect_err("moving a nonexistent file to trash must signal");
    // Only the w32 and NS builds DEFUN this primitive; on a host whose C
    // contract lacks it (the X oracle), GNU and Emaxx both answer
    // `void-function'.
    if !is_builtin("system-move-file-to-trash") {
        let condition = crate::test_support::eval_lisp(
            &mut interp,
            &mut env,
            "(condition-case e (system-move-file-to-trash \"/nonexistent/zz\") (error e))",
        )
        .expect("void-function must be catchable")
        .to_string();
        assert_eq!(condition, "(void-function system-move-file-to-trash)");
        drop(error);
        return;
    }
    let LispErrorKind::SignalValue(condition) = error.kind() else {
        panic!("expected a structured file-missing condition");
    };
    assert_eq!(
        *condition,
        Value::list([
            Value::Symbol("file-missing".into()),
            Value::String("Removing old name".into()),
            Value::String("No such file or directory".into()),
            Value::String(path.into()),
        ])
    );
}

#[test]
fn get_walks_the_plist_as_plist_get_does() {
    // fns.c:Fget with no overriding plist environment is plist_get on the
    // symbol's plist: pairs read in place, a key compared by EQ, an odd
    // tail or a non-list plist nil, a circular plist nil (FOR_EACH_TAIL_SAFE
    // breaks out).  The oracle's values.
    let mut interp = crate::test_support::initialized_gnu_early_lisp_interpreter();
    let mut env = crate::lisp::types::Env::new();
    for (form, expected) in [
        (
            "(progn (setplist 'plist-x '(a 1 b)) (list (get 'plist-x 'a) (get 'plist-x 'b) (get 'plist-x 1)))",
            "(1 nil nil)",
        ),
        (
            "(let ((l (list 'a 1 'b 2))) (setcdr (nthcdr 3 l) l) (setplist 'plist-y l) (list (get 'plist-y 'a) (get 'plist-y 'b) (get 'plist-y 'zz)))",
            "(1 2 nil)",
        ),
        (
            "(progn (setplist 'plist-z '(nil 5 t 6)) (list (get 'plist-z nil) (get 'plist-z t)))",
            "(5 6)",
        ),
        ("(progn (setplist 'plist-w '(p)) (get 'plist-w 'p))", "nil"),
        (
            "(progn (setplist 'plist-v 'not-a-list) (get 'plist-v 'p))",
            "nil",
        ),
        (
            "(progn (setplist 'plist-u '(a 1 . 7)) (list (get 'plist-u 'a) (get 'plist-u 'b)))",
            "(1 nil)",
        ),
    ] {
        let value = crate::test_support::eval_lisp(&mut interp, &mut env, form)
            .unwrap_or_else(|error| panic!("{form}: {error:?}"));
        assert_eq!(value.to_string(), expected, "{form}");
    }
}

#[test]
fn mapatoms_walks_the_standard_obarray_in_place() {
    // lread.c:Fmapatoms calls FUNCTION on every symbol of the obarray, nil
    // and t as the objects they are; a symbol interned by the callback
    // joins the obarray without disturbing the walk.
    let mut interp = crate::test_support::initialized_gnu_early_lisp_interpreter();
    let mut env = crate::lisp::types::Env::new();
    let value = crate::test_support::eval_lisp(
        &mut interp,
        &mut env,
        "(let ((n 0) (seen nil))
           (mapatoms #'(lambda (s)
                       (setq n (1+ n))
                       (when (memq s '(nil t)) (push s seen))
                       (when (= n 1) (intern \"mapatoms-walk-newcomer\"))))
           (list (length seen) (> n 100) (intern-soft \"mapatoms-walk-newcomer\")))",
    )
    .expect("mapatoms over the standard obarray");
    assert_eq!(value.to_string(), "(2 t mapatoms-walk-newcomer)");
}

#[cfg(unix)]
#[test]
fn failed_deletions_report_as_fileio_c_does() {
    // Fdelete_file_internal: `unlink' failing with anything but ENOENT is
    // report_file_error ("Removing old name", filename); ENOENT is no
    // error.  Fdelete_directory_internal: report_file_error ("Removing
    // directory", directory) on any `rmdir' failure.  The condition is the
    // errno's (permission-denied for EACCES, file-missing for ENOENT,
    // file-error otherwise) with strerror's text -- url-cache's pruner
    // handles `file-error' and let a plain `error' through.  A path through
    // a regular file is ENOTDIR for any user; the values are the oracle's.
    let mut interp = Interpreter::new();
    let mut env = crate::lisp::types::Env::new();
    let file = std::env::temp_dir().join(format!(
        "emaxx-deletion-report-{}",
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap_or_default()
            .as_nanos()
    ));
    std::fs::write(&file, b"regular").expect("write the regular file");
    let file = file.display().to_string();
    let inner = format!("{file}/x");
    let cases = [
        (
            format!("(condition-case e (delete-file-internal \"{inner}\") (error e))"),
            format!("(file-error \"Removing old name\" \"Not a directory\" \"{inner}\")"),
        ),
        (
            format!("(condition-case e (delete-directory-internal \"{inner}\") (error e))"),
            format!("(file-error \"Removing directory\" \"Not a directory\" \"{inner}\")"),
        ),
        (
            "(condition-case e (delete-file-internal \"/no/such/file\") (error e))".to_string(),
            "nil".to_string(),
        ),
        (
            "(condition-case e (delete-directory-internal \"/no/such/dir\") (error e))".to_string(),
            "(file-missing \"Removing directory\" \"No such file or directory\" \"/no/such/dir\")"
                .to_string(),
        ),
    ];
    for (form, expected) in cases {
        let value = crate::test_support::eval_lisp(&mut interp, &mut env, &form)
            .unwrap_or_else(|error| panic!("{form}: {error:?}"));
        assert_eq!(value.to_string(), expected, "{form}");
    }
    let _ = std::fs::remove_file(&file);
}

