#[test]
fn insert_signals_buffer_read_only_unless_inhibited() {
    let mut interp = Interpreter::new();
    interp
        .buffer
        .replace_state(crate::buffer::Buffer::from_text("*test*", ""));
    let mut env = crate::lisp::types::Env::new();
    interp.set_variable("buffer-read-only", Value::T, &mut env);

    assert!(matches!(
        call(&mut interp, "insert", &[Value::String("x".into())], &mut env).map_err(LispError::into_kind),
        Err(LispErrorKind::SignalValue(value))
            if matches!(value.to_vec().ok().as_deref().map(crate::lisp::types::kinds).as_deref(), Some([
                Kind::Symbol(name),
                Kind::Buffer(_),
            ]) if name == "buffer-read-only")
    ));

    interp.set_variable("inhibit-read-only", Value::T, &mut env);
    call(
        &mut interp,
        "insert",
        &[Value::String("x".into())],
        &mut env,
    )
    .expect("inhibit-read-only should allow insertion");
    assert_eq!(
        interp
            .buffer
            .borrow()
            .buffer_substring(
                interp.buffer.borrow().point_min(),
                interp.buffer.borrow().point_max()
            )
            .expect("buffer contents"),
        "x"
    );
}

