#[test]
fn minor_mode_keymap_consumers_share_gnu_order_replacement_and_default_rules() {
    let program = r#"
        (progn
          (defvar emaxx-test-mode-a nil)
          (defvar emaxx-test-mode-b nil)
          (defvar emaxx-test-mode-c nil)
          (defvar emaxx-test-emulation nil)
          (let* ((map-a (make-sparse-keymap))
                 (map-b (make-sparse-keymap))
                 (map-c (make-sparse-keymap))
                 (prefix-a (make-sparse-keymap))
                 (prefix-c (make-sparse-keymap))
                 (emaxx-test-mode-a t)
                 (emaxx-test-mode-b t)
                 (emaxx-test-mode-c t)
                 (minor-mode-map-alist
                  (list (cons 'emaxx-test-mode-a map-a)
                        (cons 'emaxx-test-mode-b map-b)))
                 (minor-mode-overriding-map-alist
                  (list (cons 'emaxx-test-mode-b map-c)))
                 (emaxx-test-emulation
                  (list (cons 'emaxx-test-mode-c map-a)))
                 (emulation-mode-map-alists '(emaxx-test-emulation)))
            (define-key map-a "x" prefix-a)
            (define-key map-b "x" 'hidden)
            (define-key map-c "x" prefix-c)
            (list
             (mapcar (lambda (map)
                       (cond ((eq map map-a) 'a)
                             ((eq map map-b) 'b)
                             ((eq map map-c) 'c)))
                     (current-minor-mode-maps))
             (mapcar (lambda (entry)
                       (cons (car entry)
                             (cond ((eq (cdr entry) prefix-a) 'pa)
                                   ((eq (cdr entry) prefix-c) 'pc))))
                     (minor-mode-key-binding "x"))
             (let ((defaults (make-sparse-keymap))
                   (emaxx-test-mode-c t)
                   (minor-mode-map-alist nil)
                   (minor-mode-overriding-map-alist nil)
                   (emulation-mode-map-alists nil))
               (define-key defaults [t] 'fallback)
               (let ((minor-mode-map-alist
                      (list (cons 'emaxx-test-mode-c defaults))))
                 (list (lookup-key defaults "z")
                       (lookup-key defaults "z" t)
                       (minor-mode-key-binding "z")
                       (minor-mode-key-binding "z" t))))
             (list (subrp (symbol-function 'current-minor-mode-maps))
                   (help-function-arglist 'current-minor-mode-maps)
                   (subrp (symbol-function 'minor-mode-key-binding))
                   (help-function-arglist 'minor-mode-key-binding)))))"#;
    let expected = "((a c a) ((emaxx-test-mode-c . pa) (emaxx-test-mode-b . pc) (emaxx-test-mode-a . pa)) (nil fallback nil ((emaxx-test-mode-c . fallback))) (t nil t (arg1 &optional arg2)))";
    assert_upstream_primitive_contract(&format!("(prin1 {program})"), expected);

    let mut interp = crate::test_support::initialized_upstream_batch_interpreter();
    let mut env = crate::lisp::types::Env::new();
    let form = Reader::new(program)
        .read()
        .expect("minor-mode keymap contract should parse")
        .expect("minor-mode keymap contract should contain a form");
    assert_eq!(
        interp
            .eval(&form, &mut env)
            .expect("all minor-mode keymap consumers should share one stack"),
        Reader::new(expected)
            .read()
            .expect("expected minor-mode keymap result should parse")
            .expect("expected minor-mode keymap result should exist")
    );
}

#[test]
fn keymap_parent_primitives_keep_constructor_object_identity() {
    // keymap.c:Fmake_sparse_keymap / Fset_keymap_parent / Fkeymap_parent:
    // the public constructor result is the object these primitives mutate.
    let mut interp = Interpreter::new();
    let mut env = Env::new();
    for constructor in ["make-sparse-keymap", "make-keymap"] {
        let child = call(&mut interp, constructor, &[], &mut env).expect("child map");
        let parent = call(&mut interp, constructor, &[], &mut env).expect("parent map");
        assert!(matches!(child.kind(), Kind::Cons(_)));
        let returned = call(&mut interp, "set-keymap-parent", &[child, parent], &mut env)
            .expect("set parent of the original map");
        assert!(values_eq_in_env(&interp, &returned, &parent, &env));
        let found = call(
            &mut interp,
            "keymap-parent",
            std::slice::from_ref(&child),
            &mut env,
        )
        .expect("read parent of the original map");
        assert!(values_eq_in_env(&interp, &found, &parent, &env));
        // The returned object is not a detached snapshot. A later binding
        // in it must be visible through the child's inheritance chain.
        let key = Value::vector(vec![Value::Integer(13)]);
        call(
            &mut interp,
            "define-key",
            &[parent, key, Value::symbol("ignore")],
            &mut env,
        )
        .expect("define inherited command");
        assert_eq!(
            call(&mut interp, "lookup-key", &[child, key], &mut env).expect("inherited lookup"),
            Value::symbol("ignore")
        );
    }
}

#[test]
fn keymap_parent_replacement_keeps_lookup_and_mutation_shared() {
    let mut interp = Interpreter::new();
    let mut env = Env::new();
    let child = call(&mut interp, "make-sparse-keymap", &[], &mut env).expect("child");
    let first = call(&mut interp, "make-sparse-keymap", &[], &mut env).expect("first parent");
    let second = call(&mut interp, "make-sparse-keymap", &[], &mut env).expect("second parent");
    let key = Value::vector(vec![Value::Integer(13)]);
    for (parent, command) in [(first, "ignore"), (second, "newline")] {
        call(
            &mut interp,
            "define-key",
            &[parent, key, Value::symbol(command)],
            &mut env,
        )
        .expect("define parent command");
    }
    for (parent, command) in [(first, "ignore"), (second, "newline")] {
        let result = call(&mut interp, "set-keymap-parent", &[child, parent], &mut env)
            .expect("replace parent");
        assert!(values_eq_in_env(&interp, &result, &parent, &env));
        assert_eq!(
            call(&mut interp, "lookup-key", &[child, key], &mut env)
                .expect("lookup after replacing parent"),
            Value::symbol(command)
        );
    }
    assert_eq!(
        call(
            &mut interp,
            "set-keymap-parent",
            &[child, Value::Nil],
            &mut env,
        )
        .expect("detach parent"),
        Value::Nil
    );
    assert_eq!(
        call(
            &mut interp,
            "keymap-parent",
            std::slice::from_ref(&child),
            &mut env
        )
        .expect("no parent"),
        Value::Nil
    );
    assert_eq!(
        call(&mut interp, "lookup-key", &[child, key], &mut env).expect("no inherited binding"),
        Value::Nil
    );
}

#[test]
