#[test]
fn minibuffer_c_g_runs_abort_minibuffers_and_recursive_edit_1_exits() {
    // C-g read in the minibuffer is a key (read_key_sequence clears
    // quit-flag): its map runs `abort-minibuffers' between the command
    // hooks, minibuffer.el's `minibuffer-quit-recursive-edit' throws a
    // function to `exit', and recursive_edit_1 calls it, signalling
    // `minibuffer-quit'.  Each recursive command loop enters through
    // command_loop_1's post-command hooks; `this-command' is left as the
    // last command set it; `recursion-depth' counts the minibuffers.
    let program = r#"(progn
             (defvar mbq-log nil)
             (defalias 'mbq-pre (lambda () (push (list 'pre this-command (recursion-depth) (minibuffer-depth)) mbq-log)))
             (defalias 'mbq-post (lambda () (push (list 'post this-command) mbq-log)))
             (defalias 'mbq-read
               (lambda (prompt events &optional recursive)
                 (setq mbq-log nil this-command nil)
                 (list (condition-case err
                           (let ((executing-kbd-macro t)
                                 (enable-recursive-minibuffers recursive)
                                 (unread-command-events events))
                             (read-from-minibuffer prompt))
                         (quit (list 'quit err)))
                       (reverse mbq-log)
                       (list this-command real-this-command last-command))))
             (add-hook 'pre-command-hook 'mbq-pre)
             (add-hook 'post-command-hook 'mbq-post)
             (unwind-protect
                 (list (mbq-read "C-g: " (list ?a 7))
                       (mbq-read "Nested: " (list ?a ?\M-x 7 ?y ?e ?s 13) t)
                       (mbq-read "RET: " (list ?a 13))
                       (recursion-depth)
                       (condition-case err (abort-recursive-edit) (error err))
                       (condition-case err (exit-recursive-edit) (error err)))
               (remove-hook 'pre-command-hook 'mbq-pre)
               (remove-hook 'post-command-hook 'mbq-post)))"#;
    let expected = r#"(((quit (minibuffer-quit)) ((post nil) (pre self-insert-command 1 1) (post self-insert-command) (pre abort-minibuffers 1 1)) (abort-minibuffers abort-minibuffers self-insert-command)) ("ayes" ((post nil) (pre self-insert-command 1 1) (post self-insert-command) (pre execute-extended-command 1 1) (post execute-extended-command) (pre abort-minibuffers 2 2) (post abort-minibuffers) (pre self-insert-command 1 1) (post self-insert-command) (pre self-insert-command 1 1) (post self-insert-command) (pre self-insert-command 1 1) (post self-insert-command) (pre exit-minibuffer 1 1)) (exit-minibuffer exit-minibuffer self-insert-command)) ("a" ((post nil) (pre self-insert-command 1 1) (post self-insert-command) (pre exit-minibuffer 1 1)) (exit-minibuffer exit-minibuffer self-insert-command)) 0 (user-error "No recursive edit is in progress") (user-error "No recursive edit is in progress"))"#;
    // The nested read's minibuffer-quit reaches cmd_error, whose
    // `(ding t)' writes GNU's batch bell to stdout before the result.
    assert_upstream_primitive_contract(&format!("(prin1 {program})"), &format!("\u{7}{expected}"));
    assert_interpreter_prints(program, expected, "minibuffer C-g");
}

#[test]
fn key_sequences_read_as_make_event_array_and_callint_k_specs() {
    // keyboard.c:make_event_array: a unibyte string when every event is a
    // character in 0...127 apart from the meta bit (M-x is "\370"), else
    // a vector (233 is [233]); callint.c's `k' reads a whole key sequence
    // with Fread_key_sequence and `K' a vector.
    assert_oracle_contract_matches_interpreter(
        r#"(let ((keys (lambda (events &optional vector)
                         (let* ((unread-command-events events)
                                (k (if vector (read-key-sequence-vector "") (read-key-sequence ""))))
                           (list (type-of k) (and (stringp k) (multibyte-string-p k)) (append k nil))))))
             (list (funcall keys (list ?\C-x ?\C-f))
                   (funcall keys (list ?\M-x))
                   (funcall keys (list 233))
                   (funcall keys (list ?a) t)
                   (let ((unread-command-events (list ?\C-x ?\C-f ?A)))
                     (mapcar (lambda (k) (list (type-of k) (append k nil)))
                             (call-interactively
                              (lambda (a b) (interactive "kKey: \nKKey %s: ") (list a b)))))))"#,
        r#"((string nil (24 6)) (string nil (248)) (vector nil (233)) (vector nil (97)) ((string (24 6)) (vector (65))))"#,
        "key sequence arrays",
    );
}

#[test]
fn read_minibuf_refuses_a_recursive_read_unless_enabled() {
    // minibuf.c:read_minibuf: with `enable-recursive-minibuffers' nil, a
    // read while a minibuffer is active is a user error from the
    // minibuffer window and, from another window, a throw of the message
    // to `exit' that ends the active read with it as an error.
    assert_oracle_contract_matches_interpreter(
        r#"(let* ((map (make-sparse-keymap))
                  (inner nil)
                  (outer (lambda (events &optional recursive)
                           (setq inner nil)
                           (list (condition-case err
                                     (let ((executing-kbd-macro t)
                                           (enable-recursive-minibuffers recursive)
                                           (unread-command-events events))
                                       (read-from-minibuffer "Outer: " nil map))
                                   (error (list 'outer-error err)))
                                 inner))))
             (set-keymap-parent map minibuffer-local-map)
             (define-key map "z"
               (lambda () (interactive)
                 (setq inner (condition-case err (read-string "Inner: ") (error (list 'inner-error err))))))
             (define-key map "w"
               (lambda () (interactive)
                 (select-window (frame-first-window))
                 (setq inner (read-string "Inner: "))))
             (list (funcall outer (list ?a ?z 13))
                   (funcall outer (list ?a ?z ?b 13 13) t)
                   (funcall outer (list ?a ?w 13))))"#,
        r#"(("a" (inner-error (user-error "Command attempted to use minibuffer while in minibuffer"))) ("a" "b") ((outer-error (error "Command attempted to use minibuffer while in minibuffer")) nil))"#,
        "recursive minibuffer",
    );
}

#[test]
fn read_minibuf_places_point_at_a_cons_initial_inputs_position() {
    // minibuf.c:read_minibuf: INITIAL (STRING . POSITION) puts point at
    // one-indexed POSITION, below 1 at the start and past the end an
    // `end-of-buffer'; completing-read-default turns its zero-indexed
    // POSITION into that one.
    assert_oracle_contract_matches_interpreter(
        r#"(let ((read (lambda (fn initial)
                         (condition-case err
                             (let ((executing-kbd-macro t)
                                   (unread-command-events (list ?X ?\r)))
                               (funcall fn initial))
                           (error err)))))
             (list (funcall read (lambda (i) (read-from-minibuffer "x: " i)) '("abc" . 2))
                   (funcall read (lambda (i) (read-from-minibuffer "x: " i)) '("abc" . 0))
                   (funcall read (lambda (i) (read-from-minibuffer "x: " i)) '("abc" . 4))
                   (funcall read (lambda (i) (read-from-minibuffer "x: " i)) '("abc"))
                   (funcall read (lambda (i) (read-string "x: " i)) '("abc" . 1))
                   (funcall read (lambda (i) (completing-read "x: " '("abXc") nil nil i)) '("abc" . 2))
                   (funcall read (lambda (i) (completing-read "x: " nil nil nil i)) '("abc" . 0))
                   (funcall read (lambda (i) (read-from-minibuffer "x: " i)) '("abc" . 5))
                   (funcall read (lambda (i) (read-from-minibuffer "x: " i)) '("abc" . x))
                   (funcall read (lambda (i) (read-from-minibuffer "x: " i)) '(abc . 1))
                   (funcall read (lambda (i) (read-from-minibuffer "x: " i)) '(nil))
                   (funcall read (lambda (i) (read-from-minibuffer "x: " i)) 5)
                   (funcall read (lambda (i) (completing-read "x: " nil nil nil i)) '("abc" . x))))"#,
        r#"("aXbc" "Xabc" "abcX" "abcX" "Xabc" "abXc" "Xabc" (end-of-buffer) (wrong-type-argument fixnump x) (wrong-type-argument stringp abc) (wrong-type-argument stringp nil) (wrong-type-argument stringp 5) (wrong-type-argument number-or-marker-p x))"#,
        "cons initial input",
    );
}

#[test]
fn native_minibuffer_stack_queries_match_gnu_minibuf_c() {
    let inactive = r#"(let ((buffer (window-buffer (minibuffer-window))))
                        (list
                         (buffer-name buffer)
                         (minibufferp buffer)
                         (minibufferp buffer t)
                         (with-current-buffer buffer
                           (list
                            (minibuffer-depth)
                            (minibuffer-prompt)
                            (minibuffer-prompt-end)
                            (innermost-minibuffer-p)
                            (minibuffer-innermost-command-loop-p)))
                         (innermost-minibuffer-p " *Minibuf-0*")
                         (condition-case error
                             (abort-minibuffers)
                           (error (cdr error)))))"#;
    let inactive_expected = r#"(" *Minibuf-0*" t nil (0 nil 1 t nil) nil ("Not in a minibuffer"))"#;
    assert_upstream_primitive_contract(&format!("(prin1 {inactive})"), inactive_expected);

    let active = r#"(catch 'state
                      (let ((minibuffer-setup-hook
                             (list
                              (lambda ()
                                (throw
                                 'state
                                 (list
                                  (minibuffer-depth)
                                  (minibuffer-prompt)
                                  (innermost-minibuffer-p)
                                  (minibuffer-innermost-command-loop-p)
                                  (minibuffer-prompt-end)
                                  (point)
                                  (minibuffer-contents)
                                  (windowp (active-minibuffer-window))
                                  (minibufferp nil t)
                                  (eq (current-local-map)
                                      minibuffer-local-completion-map)
                                  (equal minibuffer-completion-table '("a"))
                                  (let ((active (active-minibuffer-window)))
                                    (list
                                     (mapcar
                                      (lambda (window)
                                        (if (eq window active) 'mini 'ordinary))
                                      (window-list nil nil))
                                     (mapcar
                                      (lambda (window)
                                        (if (eq window active) 'mini 'ordinary))
                                      (window-list-1 (selected-window) nil nil))
                                     (memq active
                                           (window-list nil 'exclude))
                                     (length (get-buffer-window-list))))))))))
                        (let ((executing-kbd-macro t))
                          (completing-read "Prompt: " '("a")))))"#;
    let active_expected =
        r#"(1 "Prompt: " t t 9 9 "" t t t t ((mini ordinary) (mini ordinary) nil 1))"#;
    assert_upstream_primitive_contract(&format!("(prin1 {active})"), active_expected);

    let mut interp = crate::test_support::initialized_upstream_batch_interpreter();
    let mut env = crate::lisp::types::Env::new();
    for (program, expected) in [(inactive, inactive_expected), (active, active_expected)] {
        let form = Reader::new(program)
            .read()
            .expect("minibuffer stack contract should parse")
            .expect("minibuffer stack contract should contain a form");
        let expected = Reader::new(expected)
            .read()
            .expect("minibuffer stack result should parse")
            .expect("minibuffer stack result should exist");
        assert_eq!(
            interp
                .eval(&form, &mut env)
                .expect("minibuffer stack contract should evaluate"),
            expected
        );
    }
}

#[test]
fn native_minibuffer_runs_initial_post_command_hook_before_input() {
    let setup = r#"(setq emaxx-initial-post-command-count 0
                         minibuffer-setup-hook
                         (list
                          (lambda ()
                            (add-hook
                             'post-command-hook
                             (lambda ()
                               (setq emaxx-initial-post-command-count
                                     (1+ emaxx-initial-post-command-count)))
                             nil t))))"#;
    let program = format!(
        r#"(progn
                       {setup}
                       (let ((executing-kbd-macro t)
                             (unread-command-events '(13)))
                         (completing-read "Prompt: " '("a")))
                       emaxx-initial-post-command-count)"#
    );
    assert_upstream_primitive_contract(&format!("(prin1 {program})"), "1");

    let (mut interp, mut env) = upstream_interactive_interpreter();
    let form = Reader::new(setup)
        .read()
        .expect("initial post-command setup should parse")
        .expect("initial post-command setup should contain a form");
    interp
        .eval(&form, &mut env)
        .expect("initial post-command setup should evaluate");
    let script = std::rc::Rc::new(std::cell::RefCell::new(vec![Value::Integer(13)]));
    let feed = std::rc::Rc::clone(&script);
    set_tty_event_reader(Some(Box::new(move |_| feed.borrow_mut().pop())));
    let result = call(
        &mut interp,
        "completing-read",
        &[
            Value::String("Prompt: ".into()),
            Value::list([Value::String("a".into())]),
        ],
        &mut env,
    );
    set_tty_event_reader(None);
    assert_eq!(
        result.expect("RET should submit the minibuffer"),
        Value::String("".into())
    );
    assert_eq!(
        interp.lookup_var("emaxx-initial-post-command-count", &env),
        Some(Value::Integer(1))
    );
}

