#[test]
fn native_record_and_pseudovector_type_names_match_gnu_data_c() {
    let public_program = r#"(let* ((plain (record 'sample-record-type 1))
                                    (mutex (make-mutex "m"))
                                    (condition
                                     (make-condition-variable mutex "c")))
                               (list (type-of plain)
                                     (cl-type-of plain)
                                     (type-of condition)
                                     (cl-type-of condition)))"#;
    let public_expected =
        "(sample-record-type sample-record-type condition-variable condition-variable)";
    assert_upstream_primitive_contract(&format!("(prin1 {public_program})"), public_expected);

    let mut interp = Interpreter::new();
    let mut env = crate::lisp::types::Env::new();
    let form = Reader::new(public_program)
        .read()
        .expect("type-name contract should parse")
        .expect("type-name contract should contain a form");
    let expected = Reader::new(public_expected)
        .read()
        .expect("type-name result should parse")
        .expect("type-name result should exist");
    assert_eq!(
        interp
            .eval(&form, &mut env)
            .expect("type-name contract should evaluate"),
        expected
    );

    // These GNU PVEC_TS_* objects need a loaded grammar to construct through
    // Lisp, so cover the C decision-table names at Emaxx's typed host boundary.
    // GNU data.c returns exactly these `treesit-*` symbols for both `type-of`
    // and `cl-type-of`.
    for (variable, kind, type_name) in [
        (
            "parser-under-test",
            crate::lisp::eval::RecordKind::TreeSitterParser,
            "treesit-parser",
        ),
        (
            "node-under-test",
            crate::lisp::eval::RecordKind::TreeSitterNode,
            "treesit-node",
        ),
        (
            "query-under-test",
            crate::lisp::eval::RecordKind::TreeSitterCompiledQuery,
            "treesit-compiled-query",
        ),
    ] {
        let value = interp.create_pseudovector(kind, type_name, Vec::new());
        interp.set_global_binding(variable, value);
    }
    let form = Reader::new(
        "(list
           (type-of parser-under-test) (cl-type-of parser-under-test)
           (type-of node-under-test) (cl-type-of node-under-test)
           (type-of query-under-test) (cl-type-of query-under-test))",
    )
    .read()
    .expect("Tree-sitter type-name contract should parse")
    .expect("Tree-sitter type-name contract should contain a form");
    assert_eq!(
        interp
            .eval(&form, &mut env)
            .expect("Tree-sitter type-name contract should evaluate"),
        Value::list([
            Value::symbol("treesit-parser"),
            Value::symbol("treesit-parser"),
            Value::symbol("treesit-node"),
            Value::symbol("treesit-node"),
            Value::symbol("treesit-compiled-query"),
            Value::symbol("treesit-compiled-query"),
        ])
    );
}

#[test]
fn native_fixed_pseudovectors_use_gnu_full_vector_footprints() {
    // alloc.c:sweep_vectors accounts the complete VECSIZE of these
    // pseudovectors, not only the Lisp fields traced by the marker.  These
    // values come from the configured GNU headers:
    // process=42, window=66, window-configuration=13, thread=63,
    // mutex=9, and condition-variable=8 words.
    let mut interp = Interpreter::new();
    let before = interp.live_object_census();
    let values = [
        (crate::lisp::eval::RecordKind::Process, "process"),
        (crate::lisp::eval::RecordKind::Window, "window"),
        (
            crate::lisp::eval::RecordKind::WindowConfiguration,
            "window-configuration",
        ),
        (crate::lisp::eval::RecordKind::Thread, "thread"),
        (crate::lisp::eval::RecordKind::Mutex, "mutex"),
        (
            crate::lisp::eval::RecordKind::ConditionVariable,
            "condition-variable",
        ),
    ]
    .into_iter()
    .map(|(kind, name)| interp.create_pseudovector(kind, name, Vec::new()))
    .collect::<Vec<_>>();
    let after = interp.live_object_census();

    assert_eq!(after.vectors - before.vectors, values.len());
    assert_eq!(
        after.vector_slots - before.vector_slots,
        42 + 66 + 13 + 63 + 9 + 8
    );
    assert_eq!(values.len(), 6);
}

#[test]
fn native_frame_terminal_and_buffer_owners_contribute_to_vector_census() {
    // alloc.c:sweep_vectors (line 3522) uses vector_nbytes / word_size,
    // including the header and allocator rounding. Buffer objects now own
    // their Rust payload in that allocation, so substituting the old GNU
    // VECSIZE estimate would hide its real footprint. Keep exact object and
    // slot deltas, including a killed object that still has a Lisp reference.
    let mut interp = Interpreter::new();
    let before = interp.live_object_census();
    let (id, _) = interp.create_buffer("census-buffer");
    let buffer = interp
        .buffer_identity_value(id)
        .expect("created buffer object");
    let after = interp.live_object_census();

    assert_eq!(after.buffers - before.buffers, 1);
    // buffer.c:Fget_buffer_create allocates the buffer and its mark. The
    // mark is now the real 48-byte Lisp_Marker, counted by sweep_vectors.
    assert_eq!(after.vectors - before.vectors, 2);
    assert_eq!(
        after.vector_slots - before.vector_slots,
        (std::mem::size_of::<crate::lisp::alloc::vectors::VectorHeader>()
            + std::mem::size_of::<crate::lisp::types::BufferValue>())
        .div_ceil(std::mem::size_of::<Value>())
            + 6 // configured GNU Lisp_Marker: header plus five payload words
    );
    interp.kill_buffer_id(id);
    let killed = interp.live_object_census();
    assert_eq!(killed.buffers, after.buffers);
    assert_eq!(killed.vectors, after.vectors);
    assert_eq!(killed.vector_slots, after.vector_slots);
    assert!(matches!(buffer.kind(), Kind::Buffer(_)));
}

