#[test]
fn char_charset_family_follows_charset_c() {
    // charset.c: char_charset walks the priority order and answers
    // `unicode' once Vcharset_non_preferred_head (the part of the order
    // `set-charset-priority' did not move) is reached for a Unicode
    // character, `eight-bit' for a raw byte; a coding-system RESTRICTION
    // reads coding_system_charset_list (Vemacs_mule_charset_list for
    // emacs-mule); `split-char' is the code's bytes per dimension;
    // `charset-after' and `find-charset-string'/`-region' report raw bytes
    // as `eight-bit'.  ENCODE_CHAR/DECODE_CHAR honour a charset's
    // `:min-code'/`:max-code' and the code-space index of an offset
    // charset, a map file's `FROM-TO C' lines advance by index, the
    // `unicode' and `emacs' code spaces end at MAX_UNICODE_CHAR and
    // MAX_5_BYTE_CHAR, and CHECK_CHARSET_GET_CHARSET signals for an
    // unknown charset.
    let program = r##"
(list (mapcar #'char-charset (list ?a #xe9 #x3042 #x20ac #x110000 #x3fffe9 #x3fff7f #x200000 #x1f600))
	    (char-charset #x3042 '(japanese-jisx0208 ascii))
	    (char-charset #xe9 '(japanese-jisx0208 ascii))
	    (char-charset ?a '(japanese-jisx0208))
	    (char-charset #x3042 'iso-2022-jp) (char-charset #xe9 'iso-2022-jp)
	    (char-charset #x3042 'utf-8) (char-charset #xe9 'iso-latin-2)
	    (mapcar #'split-char (list ?a #xe9 #x3042 #x110000 #x3fffe9 #x3fff7f #xac00))
	    (with-temp-buffer (insert (string #x3fffe9 #x3042 ?\s ?a))
			      (mapcar #'charset-after '(1 2 3 4 10)))
	    (find-charset-string (string ?a #x3fffe9 #x20ac #x3042))
	    (find-charset-string (unibyte-string ?a 233))
	    (find-charset-string "")
	    (find-charset-string (string ?a #xe9 #x3042) '(japanese-jisx0208 ascii iso-8859-1))
	    (with-temp-buffer (insert (string ?a #x3fffe9 #x3042)) (find-charset-region (point-min) (point-max)))
	    (with-temp-buffer (set-buffer-multibyte nil) (insert (unibyte-string ?a 233)) (find-charset-region (point-min) (point-max)))
	    (progn (set-charset-priority 'japanese-jisx0208)
		   (list (seq-take (charset-priority-list) 3)
			 (mapcar #'char-charset (list ?a #xe9 #x3042 #x20ac #x110000 #x3fffe9))
			 (mapcar #'split-char (list #xe9 #x3042 #x20ac))
			 (find-charset-string (string ?a #x3fffe9 #x20ac #x3042))))
	    (progn (set-charset-priority 'ascii)
		   (list (seq-take (charset-priority-list) 3) (char-charset #xe9) (char-charset #x3042)))
	    (progn (set-charset-priority 'ascii 'iso-8859-1)
		   (list (char-charset #xe9) (char-charset #x3042)))
	    (progn (set-charset-priority 'iso-8859-2)
		   (list (seq-take (charset-priority-list) 3) (char-charset #xe9) (char-charset #x3042) (char-charset #x20ac)))
	    (progn (set-charset-priority 'unicode)
		   (list (char-charset #xe9) (char-charset #x3042) (char-charset #x110000) (split-char #x3042)))
	    (list (decode-char 'unicode #x3fff7f) (decode-char 'emacs #x3fff7f) (decode-char 'emacs #x3fff80)
		  (decode-char 'eight-bit #xe9) (decode-char 'eight-bit #x7f)
		  (encode-char #x3fffe9 'unicode) (encode-char #x3fffe9 'emacs) (encode-char #x3fff7f 'emacs)
		  (encode-char #x3fff7f 'unicode) (encode-char #x3fffe9 'eight-bit) (encode-char #x3fffe9 'iso-8859-1)
		  (encode-char #x3fffe9 'japanese-jisx0208) (encode-char #x3fffe9 'latin-iso8859-1))
	    (list (encode-char #x3fff7f 'gb18030) (encode-char #x10ffff 'gb18030) (encode-char #x110000 'gb18030)
		  (encode-char #x80 'gb18030-4-byte-bmp)
		  (decode-char 'gb18030-4-byte-bmp #x81308130) (decode-char 'gb18030-4-byte-bmp #x81308435)
		  (decode-char 'gb18030-4-byte-bmp #x81308436)
		  (decode-char 'gb18030-4-byte-smp #x90308130) (decode-char 'gb18030-4-byte-smp #xE3329A35)
		  (decode-char 'gb18030-4-byte-smp #xE3329A36)
		  (decode-char 'gb18030-4-byte-ext-1 #x8431A530) (encode-char #x200000 'gb18030-4-byte-ext-1)
		  (decode-char 'gb18030 #x8431A530) (encode-char #x200000 'gb18030)
		  (decode-char 'gb18030-2-byte #x8140) (encode-char #x4E02 'gb18030-2-byte)
		  (decode-char 'japanese-jisx0208 #x3021) (encode-char #x4E9C 'japanese-jisx0208)
		  (decode-char 'big5 #xA440) (encode-char #x4E00 'big5)
		  (decode-char 'chinese-gb2312 #x3021) (decode-char 'korean-ksc5601 #x3021)
		  (decode-char 'cp932-2-byte #x8140) (decode-char 'japanese-jisx0213-1 #x2121)
		  (condition-case e (decode-char 'jisx0213-1 #x2121) (error e))
		  (condition-case e (encode-char ?a 'jisx0213-1) (error e))))"##;
    assert_oracle_contract_matches_interpreter(
        program,
        r##"((ascii unicode unicode unicode chinese-gb2312 eight-bit emacs gb18030 unicode) japanese-jisx0208 nil nil japanese-jisx0208 nil unicode iso-8859-2 ((ascii 97) (unicode 0 0 233) (unicode 0 48 66) (chinese-gb2312 33 33) (eight-bit 233) (emacs 63 255 127) (unicode 0 172 0)) (eight-bit unicode ascii ascii nil) (ascii unicode eight-bit) (ascii eight-bit) nil (ascii unicode) (ascii unicode eight-bit) (ascii eight-bit) ((japanese-jisx0208 ascii iso-8859-1) (ascii unicode japanese-jisx0208 unicode chinese-gb2312 eight-bit) ((unicode 0 0 233) (japanese-jisx0208 36 34) (unicode 0 32 172)) (ascii unicode eight-bit japanese-jisx0208)) ((ascii japanese-jisx0208 iso-8859-1) unicode unicode) (iso-8859-1 unicode) ((iso-8859-2 ascii iso-8859-1) iso-8859-2 unicode unicode) (unicode unicode chinese-gb2312 (unicode 0 48 66)) (nil 4194175 nil 4194281 nil nil nil 4194175 nil 233 nil nil nil) (nil 3811744309 nil 2167439664 128 163 165 65536 1114111 nil 2097152 2217846064 65530 2217846064 19970 33088 20124 12321 19968 42048 21834 44032 12288 12288 (wrong-type-argument charsetp jisx0213-1) (wrong-type-argument charsetp jisx0213-1)))"##,
        "char-charset family",
    );
}

#[test]
fn text_property_copies_follow_add_text_properties_order() {
    // textprop.c add_properties conses each new property onto the head
    // of the interval's plist, so every copy that goes through
    // add_text_properties (Fsubstring's copy_text_properties, `concat' and
    // `mapconcat' via concat_to_string, styled_format's argument and
    // format-string intervals) reverses a span's pairs, where
    // copy_intervals (`copy-sequence', buffer insertion) keeps them;
    // editfns.c styled_format returns a string argument itself for a
    // property-less "%s" format.  The printed forms swap their quotes
    // for apostrophes so the contract's own rendering stays unambiguous.
    let program = r##"
(let ((s (propertize "x" 'a 1 'b 2))
	    (p (lambda (x) (string-replace "\"" "'" (prin1-to-string x)))))
	(list (funcall p (concat s))
	      (funcall p (substring (propertize "xy" 'a 1 'b 2) 1))
	      (funcall p (mapconcat #'identity (list s (propertize "y" 'c 3 'd 4)) (propertize "-" 'e 5 'f 6)))
	      (funcall p (copy-sequence (propertize "xy" 'a 1 'b 2)))
	      (funcall p (string-trim (propertize " x " 'a 1 'b 2)))
	      (funcall p (concat (propertize "x" 'a 1) (propertize "y" 'a 1 'b 2)))
	      (funcall p (substring (concat (propertize "xy" 'a 1 'b 2 'c 3)) 1))
	      (with-temp-buffer (insert s) (funcall p (buffer-string)))
	      (let ((c (copy-sequence "x"))) (put-text-property 0 1 'a 1 c) (put-text-property 0 1 'b 2 c) (funcall p c))
	      (let ((c (copy-sequence "x"))) (add-text-properties 0 1 '(a 1 b 2) c) (funcall p c))
	      (let ((c (copy-sequence "x"))) (set-text-properties 0 1 '(a 1 b 2) c) (funcall p c))
	      (eq s (format "%s" s)) (eq s (format "%s" s 2))
	      (funcall p (format "%s" s))
	      (funcall p (format "%s " s))
	      (funcall p (format "%5s" s))
	      (funcall p (format "%d%s" 1 s))
	      (funcall p (format (propertize "%s" 'q 9 'r 8) "x"))
	      (funcall p (format (propertize "%s" 'q 9) s))
	      (funcall p (format "%s-%s" s (propertize "y" 'c 3 'd 4)))
	      (funcall p (format "%s" (concat s (propertize "y" 'c 3))))))"##;
    assert_oracle_contract_matches_interpreter(
        program,
        r##"("#('x' 0 1 (b 2 a 1))" "#('y' 0 1 (b 2 a 1))" "#('x-y' 0 1 (b 2 a 1) 1 2 (f 6 e 5) 2 3 (d 4 c 3))" "#('xy' 0 2 (a 1 b 2))" "#('x' 0 1 (a 1 b 2))" "#('xy' 0 1 (a 1) 1 2 (b 2 a 1))" "#('y' 0 1 (a 1 b 2 c 3))" "#('x' 0 1 (a 1 b 2))" "#('x' 0 1 (b 2 a 1))" "#('x' 0 1 (b 2 a 1))" "#('x' 0 1 (a 1 b 2))" t t "#('x' 0 1 (a 1 b 2))" "#('x ' 0 1 (b 2 a 1))" "#('    x' 4 5 (b 2 a 1))" "#('1x' 1 2 (b 2 a 1))" "#('x' 0 1 (r 8 q 9))" "#('x' 0 1 (b 2 a 1 q 9))" "#('x-y' 0 1 (b 2 a 1) 2 3 (d 4 c 3))" "#('xy' 0 1 (b 2 a 1) 1 2 (c 3))")"##,
        "text property copy order",
    );
}

#[test]
fn default_file_modes_is_the_process_umask_and_temp_files_are_private() {
    // fileio.c: `set-default-file-modes' sets the process's creation mask
    // (~MODE & 0777), so `make-directory' (mkdir 0777), `write-region'
    // (0666) and every subprocess see it, and `default-file-modes' is
    // its complement; gen_tempname makes `make-temp-file' entries 0600
    // and directories 0700 regardless of the mask's generosity.  A
    // temporary directory that came out 0755 made server.el's
    // server-ensure-safe-dir refuse it ("accessible by others").  The
    // startup value is the inherited umask's complement, so it is
    // checked against `sh -c umask' rather than a literal.
    let program = r##"
(let* ((d (make-temp-file "emaxx-modes" t))
       (f (make-temp-file "emaxx-modes"))
       (sub (expand-file-name "sub" d))
       (f2 (expand-file-name "f2" d))
       (u (expand-file-name "u" d))
       (orig (default-file-modes)))
  (unwind-protect
      (list (format "%o" (file-modes d)) (format "%o" (file-modes f))
            (progn (with-file-modes #o700 (make-directory sub)) (format "%o" (file-modes sub)))
            (progn (with-file-modes #o640 (write-region "" nil f2)) (format "%o" (file-modes f2)))
            (progn (with-file-modes #o600 (call-process "sh" nil nil nil "-c" (concat "umask > " u)))
                   (with-temp-buffer (insert-file-contents u) (string-trim (buffer-string))))
            (progn (with-file-modes #o777 (make-directory (expand-file-name "sub2" d)))
                   (format "%o" (file-modes (expand-file-name "sub2" d))))
            (progn (call-process "sh" nil nil nil "-c" (concat "umask > " u))
                   (with-temp-buffer (insert-file-contents u)
                                     (= (default-file-modes)
                                        (logand (lognot (string-to-number (string-trim (buffer-string)) 8)) #o777))))
            (progn (set-default-file-modes #o600) (prog1 (format "%o" (default-file-modes)) (set-default-file-modes orig)))
            (= (default-file-modes) orig))
    (delete-directory d t) (delete-file f)))"##;
    assert_oracle_contract_matches_interpreter(
        program,
        r##"("700" "600" "700" "640" "0177" "777" t "600" t)"##,
        "default file modes",
    );
}

#[test]
fn eval_buffer_binds_lexical_binding_from_the_first_line_cookie() {
    // lread.c Feval_buffer specbinds `lexical-binding' to
    // lisp_file_lexical_cookie's answer for the whole readevalloop -- the
    // caller's buffer keeps its own value afterwards -- and that scanner
    // reads only the first line (the second after a `#!' line), which
    // must start with `;': a cookie inside a string on line two is text.
    // `load' of a source file goes through load-with-code-conversion and
    // therefore through the same binding, so `named-let' (which signals
    // without the variable) expands inside a lexical file loaded while a
    // dynamic buffer is being evaluated.  The caller's own
    // `lexical-binding' is left out: it differs between GNU's `--eval'
    // (t) and `-l' (nil) entry points and says nothing about eval-buffer.
    let program = r##"
(let ((lb (lambda () (list lexical-binding (default-value 'lexical-binding) (local-variable-p 'lexical-binding))))
      (f (make-temp-file "emaxx-lex" nil ".el"
                         (concat ";;; -*- lexical-binding: t -*-\n(require 'subr-x)\n"
                                 "(defun emaxx-lex-f () (named-let loop ((i 0)) (if (< i 3) (loop (1+ i)) i)))\n"
                                 "(setq emaxx-lex-seen lexical-binding)\n"))))
  (unwind-protect
      (list (progn (load f nil t) (list (emaxx-lex-f) emaxx-lex-seen))
            (with-temp-buffer (insert-file-contents f) (eval-buffer)
                              (list lexical-binding emaxx-lex-seen (emaxx-lex-f)))
            (with-temp-buffer (insert "(setq emaxx-lex-seen lexical-binding)") (eval-buffer) emaxx-lex-seen)
            (with-temp-buffer (insert ";; -*- lexical-binding: nil -*-\n(setq emaxx-lex-seen lexical-binding)")
                              (eval-buffer) emaxx-lex-seen)
            (with-temp-buffer (insert "#!/bin/sh\n;; -*- lexical-binding: t -*-\n(setq emaxx-lex-seen lexical-binding)")
                              (eval-buffer) emaxx-lex-seen)
            (with-temp-buffer (insert "(setq emaxx-lex-str \";;; -*- lexical-binding: t -*-\")\n(setq emaxx-lex-seen lexical-binding)")
                              (eval-buffer) emaxx-lex-seen)
            (progn (setq emaxx-lex-file f)
                   (with-temp-buffer
                     (insert ";;; -*- lexical-binding: t -*-\n(eval-and-compile (load emaxx-lex-file nil t))\n(setq emaxx-lex-outer lexical-binding)")
                     (eval-buffer) (list (emaxx-lex-f) emaxx-lex-outer (funcall lb)))))
    (delete-file f)))"##;
    assert_oracle_contract_matches_interpreter(
        program,
        r##"((3 t) (nil t 3) nil nil t nil (3 t (nil nil nil)))"##,
        "eval-buffer lexical-binding cookie",
    );
}

#[cfg(unix)]
struct FrameTestPty {
    _master: std::fs::File,
    _slave: std::fs::File,
    path: String,
}

#[cfg(unix)]
impl FrameTestPty {
    fn new() -> Self {
        use std::os::fd::FromRawFd;
        let mut master = -1;
        let mut slave = -1;
        let mut name = [0i8; 1024];
        let mut size = libc::winsize {
            ws_row: 24,
            ws_col: 80,
            ws_xpixel: 0,
            ws_ypixel: 0,
        };
        // SAFETY: openpty initializes the two owned descriptors and a device
        // name in the provided buffer. Each descriptor is closed exactly once.
        unsafe {
            assert_eq!(
                libc::openpty(
                    &mut master,
                    &mut slave,
                    name.as_mut_ptr(),
                    std::ptr::null_mut(),
                    &raw mut size
                ),
                0
            );
            Self {
                _master: std::fs::File::from_raw_fd(master),
                _slave: std::fs::File::from_raw_fd(slave),
                path: std::ffi::CStr::from_ptr(name.as_ptr())
                    .to_str()
                    .expect("valid terminal contract fixture")
                    .to_owned(),
            }
        }
    }
}

#[cfg(unix)]
#[test]
fn terminal_frames_follow_gnu_device_window_and_deletion_lifecycle() {
    let pty = FrameTestPty::new();
    let program = format!(
        r#"
        (let* ((initial (selected-frame))
               (f (make-terminal-frame '((tty . {:?}) (tty-type . "xterm"))))
               (terminal (frame-terminal f))
               (g (make-terminal-frame (list (cons 'terminal terminal))))
               (w (frame-root-window f))
               (seen nil))
          (unwind-protect
              (list
               (eq (selected-frame) initial)
               (= (length (frame-list)) 3)
               (= (length (terminal-list)) 2)
               (eq (frame-terminal g) terminal)
               (eq (frame-root-window f) (frame-root-window g))
               (eq (frame-root-window w) w)
               (eq (frame-first-window w) w)
               (eq (frame-selected-window w) w)
               (eq (window-frame w) f)
               (eq (window-frame (minibuffer-window f)) f)
               (eq (car (window-list f)) w)
               (eq (tty-top-frame terminal) g)
               (progn (set-terminal-parameter terminal 'probe 'new)
                      (terminal-parameter (frame-terminal initial) 'probe))
               (progn (select-frame f)
                      (eq (selected-window) (frame-selected-window f)))
               (progn (add-hook 'delete-frame-functions
                                (lambda (frame) (setq seen (frame-live-p frame))))
                      (delete-frame f) seen)
               (frame-live-p f)
               (window-live-p w)
               (condition-case error-data (window-frame w) (error (car error-data)))
               (terminal-live-p terminal)
               (progn (delete-frame g) (terminal-live-p terminal))
               (= (length (frame-list)) 1))
            (when (frame-live-p initial) (select-frame initial))
            (when (terminal-live-p terminal) (delete-terminal terminal t))))
    "#,
        pty.path
    );
    let expected = "(t t t t nil t t t t t t t nil t t nil nil wrong-type-argument t nil t)";
    assert_upstream_primitive_contract(&format!("(prin1 {program})"), expected);
    let mut interp = crate::test_support::initialized_gnu_early_lisp_interpreter();
    let form = Reader::new(&program)
        .read_all()
        .expect("valid terminal contract fixture")
        .remove(0);
    let result = interp
        .eval(&form, &mut crate::lisp::types::Env::new())
        .expect("terminal lifecycle");
    assert_eq!(result.to_string(), expected);
}

#[cfg(unix)]
#[test]
fn terminal_frames_preserve_other_frames_when_windows_change() {
    let pty = FrameTestPty::new();
    let program = format!(
        r#"
        (let* ((initial (selected-frame))
               (initial-window (selected-window))
               (f (make-terminal-frame '((tty . {:?}) (tty-type . "xterm"))))
               (root (frame-root-window f)))
          (unwind-protect
              (progn
                (select-frame f)
                (split-window root 10 'below)
                (let ((split-root (frame-root-window f)))
                  (list (not (eq split-root root))
                        (= (length (window-list f)) 2)
                        (= (length (window-list initial)) 1)
                        (eq (window-frame split-root) f)
                        (progn (delete-other-windows root)
                               (window-live-p initial-window))
                        (= (length (window-list f)) 1)
                        (progn (select-frame initial)
                               (eq (selected-window) initial-window)))))
            (select-frame initial)
            (delete-frame f)))
    "#,
        pty.path
    );
    let expected = "(t t t t t t t)";
    assert_upstream_primitive_contract(&format!("(prin1 {program})"), expected);
    let mut interp = crate::test_support::initialized_upstream_batch_interpreter();
    let form = Reader::new(&program)
        .read_all()
        .expect("valid terminal contract fixture")
        .remove(0);
    let result = interp
        .eval(&form, &mut crate::lisp::types::Env::new())
        .expect("independent window trees");
    assert_eq!(result.to_string(), expected);
}

#[cfg(unix)]
#[test]
fn terminal_frames_isolate_faces_keyboards_and_saved_configurations() {
    let pty = FrameTestPty::new();
    let program = format!(
        r#"
      (let* ((initial (selected-frame))
             (initial-map input-decode-map)
             (f (make-terminal-frame '((tty . {:?}) (tty-type . "xterm"))))
             (terminal (frame-terminal f))
             (g (make-terminal-frame (list (cons 'terminal terminal))))
             (configuration (current-window-configuration f))
             (client-buffer (get-buffer-create "terminal-gate-buffer")))
        (unwind-protect
            (progn
              (make-face 'terminal-gate-face)
              (set-face-attribute 'terminal-gate-face initial :foreground "red")
              (set-face-attribute 'terminal-gate-face f :foreground "blue")
              (copy-face 'terminal-gate-face 'terminal-gate-copy f g)
              (set-window-buffer (frame-selected-window g) client-buffer)
              (let ((prefix-arg 'primary))
                (select-frame f)
                (setq prefix-arg 'client)
                (list
                  (face-attribute 'terminal-gate-face :foreground initial)
                  (face-attribute 'terminal-gate-face :foreground f)
                  (face-attribute 'terminal-gate-copy :foreground g)
                  (eq (window-configuration-frame configuration) f)
                  (eq (get-buffer-window client-buffer t) (frame-selected-window g))
                  (get-buffer-window client-buffer initial)
                  (eq input-decode-map initial-map)
                  (lookup-key input-decode-map "\eOD")
                  (progn (select-frame g) prefix-arg)
                  (progn (let ((prefix-arg 'temporary)) (select-frame initial)) prefix-arg)
                  (progn (select-frame f) prefix-arg)
                  (progn (set-window-configuration configuration) (eq (selected-frame) initial))
                  (progn (select-frame f) (set-window-configuration configuration t) (eq (selected-frame) f))
                  (progn (delete-terminal terminal) (eq (selected-frame) initial))
                  (frame-live-p f) (frame-live-p g) (terminal-live-p terminal))))
          (select-frame initial)
          (when (terminal-live-p terminal) (delete-terminal terminal t))
          (kill-buffer client-buffer)))
    "#,
        pty.path
    );
    let expected =
        r#"("red" "blue" "blue" t t nil nil [left] client primary client t t t nil nil nil)"#;
    assert_upstream_primitive_contract(&format!("(prin1 {program})"), expected);
    let mut interp = crate::test_support::initialized_upstream_batch_interpreter();
    let form = Reader::new(&program)
        .read_all()
        .expect("valid terminal contract fixture")
        .remove(0);
    let mut env = crate::lisp::types::Env::new();
    let result = interp
        .eval(&form, &mut env)
        .expect("frame/keyboard isolation");
    let printed = call(&mut interp, "prin1-to-string", &[result], &mut env)
        .expect("valid terminal contract fixture");
    assert_eq!(
        printed
            .as_string()
            .expect("valid terminal contract fixture"),
        expected
    );
}

/// Run the complete contract in its own process, including GNU's control.
/// Reusing an allocator address after an earlier Rust test can make an old
/// conservative stack word retain the new object. A fresh process removes
/// that unrelated history while preserving both the suspended live roots and
/// the assertion that the same objects are reclaimed after the thread exits.
/// No production path reads this test-only environment variable.
fn reclamation_contract_runs_in_fresh_process(name: &str) -> bool {
    const CHILD: &str = "EMAXX_RECLAMATION_CONTRACT_CHILD";
    let module = module_path!()
        .strip_prefix(concat!(env!("CARGO_CRATE_NAME"), "::"))
        .expect("test module starts with its crate name");
    let test_name = format!("{module}::{name}");
    if std::env::var(CHILD).as_deref() == Ok(test_name.as_str()) {
        return false;
    }
    crate::test_support::mark_process_test();
    let output = std::process::Command::new(
        std::env::current_exe().expect("current reclamation contract executable"),
    )
    .args(["--exact", &test_name, "--test-threads=1", "--nocapture"])
    .env(CHILD, &test_name)
    .output()
    .expect("run the selected reclamation contract in a fresh process");
    let stdout = String::from_utf8_lossy(&output.stdout);
    let stderr = String::from_utf8_lossy(&output.stderr);
    assert!(
        output.status.success()
            && stdout.contains("test result: ok. 1 passed; 0 failed; 0 ignored;"),
        "{test_name} did not execute and pass in its child process\n{stdout}\n{stderr}"
    );
    true
}

#[test]
fn threads_retain_lexical_caller_roots_across_separate_callee_environments() {
    if reclamation_contract_runs_in_fresh_process(
        "threads_retain_lexical_caller_roots_across_separate_callee_environments",
    ) {
        return;
    }
    // GNU marks all live thread stacks, including an interpreted caller's
    // lexical cells which its independently scoped callee cannot access.
    // Neither backtrace display nor a captured lambda owns KEY here.
    let program = r#"
        (progn
          (defvar suspension-roots-table nil)
          (defvar suspension-roots-stage nil)
          (defun suspension-roots-wait ()
            (setq suspension-roots-stage 'parked)
            (while (eq suspension-roots-stage 'parked) (thread-yield)))
          (defun suspension-roots-run (helper)
            (setq suspension-roots-table (make-hash-table :test 'eq :weakness 'key)
                  suspension-roots-stage nil)
            (fset 'suspension-roots-helper helper)
            (let ((worker
                   (make-thread
                    (eval '(lambda ()
                             (let ((key (list 'owned-only-by-caller)))
                               (puthash key t suspension-roots-table)
                               (suspension-roots-helper)
                               (gethash key suspension-roots-table))) t))))
              (while (not (eq suspension-roots-stage 'parked)) (thread-yield))
              (garbage-collect)
              (let ((during (hash-table-count suspension-roots-table)))
                (setq suspension-roots-stage 'resume)
                (let ((result (thread-join worker)))
                  (garbage-collect)
                  (list during result (hash-table-count suspension-roots-table))))))
          (list
           (suspension-roots-run (eval '(lambda () (suspension-roots-wait)) nil))
           (suspension-roots-run (eval '(lambda () (suspension-roots-wait)) t))))"#;
    assert_oracle_contract_matches_interpreter(
        program,
        "((1 t 0) (1 t 0))",
        "live suspended caller environments",
    );
}

#[test]
fn suspended_bytecode_retains_operand_and_unwind_roots() {
    if reclamation_contract_runs_in_fresh_process(
        "suspended_bytecode_retains_operand_and_unwind_roots",
    ) {
        return;
    }
    // GNU bytecode.c:mark_bytecode marks the live operand stack, and the
    // specpdl marks pending cleanup functions. The keys are allocated at
    // runtime, not held by bytecode constants or a test-owned strong root.
    let program = r#";;; -*- lexical-binding: t; -*-
        (require 'bytecomp)
        (defvar vm-suspension-table nil)
        (defvar vm-suspension-stage nil)
        (defvar vm-suspension-observed nil)
        (defvar vm-suspension-result nil)
        (defun vm-suspension-pause (&rest _)
          (setq vm-suspension-stage 'parked)
          (while (eq vm-suspension-stage 'parked) (thread-yield)))
        (defun vm-suspension-key ()
          (let ((key (list 'runtime-key)))
            (puthash key t vm-suspension-table)
            key))
        (defun vm-suspension-cleanup ()
          (let ((key (vm-suspension-key)))
            (lambda ()
              (setq vm-suspension-observed (gethash key vm-suspension-table)))))
        (defun vm-suspension-lookup (key)
          (gethash key vm-suspension-table))
        (defun vm-suspension-run (function)
          (setq vm-suspension-table (make-hash-table :test 'eq :weakness 'key)
                vm-suspension-stage nil vm-suspension-observed nil)
          (let ((worker (make-thread function)))
            (while (not (eq vm-suspension-stage 'parked)) (thread-yield))
            (garbage-collect)
            (let ((during (hash-table-count vm-suspension-table)))
              (setq vm-suspension-stage 'resume)
              (let ((result (thread-join worker)))
                (garbage-collect)
                (list during (or result vm-suspension-observed)
                      (hash-table-count vm-suspension-table))))))
        (setq vm-suspension-result
              (list
               ;; Runtime cleanup closure held in the VM's unwind stack.
               (vm-suspension-run
                (make-byte-code
                 0
                 (unibyte-string byte-constant byte-call byte-unwind-protect
                                 (+ byte-constant 1) byte-call
                                 (+ byte-unbind 1) byte-return)
                 [vm-suspension-cleanup vm-suspension-pause] 1))
               ;; A live key below Binsert's argument while its ordinary
               ;; modification hook suspends in the dedicated opcode.
               (with-temp-buffer
                 (add-hook 'before-change-functions #'vm-suspension-pause nil t)
                 (vm-suspension-run
                  (make-byte-code
                   0
                   (unibyte-string byte-constant (+ byte-constant 1) byte-call
                                   (+ byte-constant 2) byte-insert byte-discard
                                   (+ byte-call 1) byte-return)
                   [vm-suspension-lookup vm-suspension-key "payload"] 3)))))
        (prin1 vm-suspension-result)"#;
    assert_oracle_file_contract_matches_interpreter(
        program,
        "vm-suspension-result",
        "((1 t 0) (1 t 0))",
    );
}

#[test]
fn suspended_bytecode_observes_live_constant_vector_mutation() {
    let program = r#";;; -*- lexical-binding: t; -*-
(defvar gc-vector-table (make-hash-table :test 'eq :weakness 'key))
(defvar gc-vector-ready nil)
(defvar gc-vector-resume nil)
(defvar gc-vector-constants
  (vector (lambda ()
            (setq gc-vector-ready t)
            (while (not gc-vector-resume) (thread-yield)))
          (list 'old)))
(puthash (aref gc-vector-constants 1) t gc-vector-table)
(defvar gc-vector-thread
  (make-thread
   (make-byte-code 0 (unibyte-string 192 32 136 193 135)
                   gc-vector-constants 1)))
(while (not gc-vector-ready) (thread-yield))
(aset gc-vector-constants 1 (list 'new))
(puthash (aref gc-vector-constants 1) t gc-vector-table)
(garbage-collect)
(defvar gc-vector-result (list (hash-table-count gc-vector-table)))
(setq gc-vector-resume t)
(setq gc-vector-result
      (append gc-vector-result
              (list (eq (thread-join gc-vector-thread)
                        (aref gc-vector-constants 1)))))
(setq gc-vector-thread nil gc-vector-constants nil)
"#;
    let after_load = r#"(progn
      (garbage-collect)
      (setq gc-vector-result
            (append gc-vector-result (list (hash-table-count gc-vector-table))))
      (prin1 gc-vector-result))"#;
    assert_oracle_file_contract_with_observer(
        program,
        Some(after_load),
        "gc-vector-result",
        "(1 t 0)",
    );
}

#[test]
fn dead_thread_results_are_rooted_only_through_reachable_thread_objects() {
    // thread.c removes finished threads from all_threads, but an externally
    // reachable thread still owns its result. Test retention AND release.
    // Observe release after the setup file returns: GNU's conservative
    // C-stack scan can retain the earlier thread-join result while the
    // loader is active, including across top-level forms on Linux.
    let program = r#";;; -*- lexical-binding: t; -*-
        (defvar dead-thread-roots-table (make-hash-table :test 'eq :weakness 'key))
        (defvar dead-thread-roots-worker nil)
        (defvar dead-thread-roots-result nil)
        (setq dead-thread-roots-worker
              (make-thread
               (lambda ()
                 (let ((key (list 'owned-by-thread-result)))
                   (puthash key t dead-thread-roots-table)
                   key))))
        (thread-join dead-thread-roots-worker)
        (garbage-collect)
        (setq dead-thread-roots-result (list (hash-table-count dead-thread-roots-table)))
        (setq dead-thread-roots-worker nil)"#;
    let after_load = r#"(progn
      (garbage-collect)
      (setq dead-thread-roots-result
            (append dead-thread-roots-result
                    (list (hash-table-count dead-thread-roots-table))))
      (prin1 dead-thread-roots-result))"#;
    assert_oracle_file_contract_with_observer(
        program,
        Some(after_load),
        "dead-thread-roots-result",
        "(1 0)",
    );
}

fn assert_oracle_file_contract_matches_interpreter(
    program: &str,
    result_variable: &str,
    expected: &str,
) {
    assert_oracle_file_contract_with_observer(program, None, result_variable, expected);
}

fn assert_oracle_file_contract_with_observer(
    program: &str,
    after_load: Option<&str>,
    result_variable: &str,
    expected: &str,
) {
    let path = std::env::temp_dir().join(format!(
        "emaxx-file-contract-{}-{}.el",
        std::process::id(),
        SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .expect("timestamp")
            .as_nanos(),
    ));
    fs::File::create_new(&path)
        .expect("create unique contract fixture")
        .write_all(program.as_bytes())
        .expect("write contract fixture");
    crate::test_support::mark_process_test();
    let mut command = std::process::Command::new(upstream_emacs_repo().join("src/emacs"));
    command.args(["-Q", "--batch", "-l"]).arg(&path);
    if let Some(observer) = after_load {
        command.args(["--eval", observer]);
    }
    let oracle = command.output().expect("run GNU file contract");
    assert!(
        oracle.status.success(),
        "{}",
        String::from_utf8_lossy(&oracle.stderr)
    );
    assert_eq!(String::from_utf8_lossy(&oracle.stdout), expected);
    let mut interp = crate::test_support::initialized_upstream_batch_interpreter();
    call(
        &mut interp,
        "load",
        &[
            Value::string(&path.to_string_lossy()),
            Value::Nil,
            Value::T,
            Value::T,
        ],
        &mut Env::new(),
    )
    .expect("load identical contract fixture");
    if let Some(observer) = after_load {
        for form in Reader::new(observer)
            .read_all()
            .expect("read identical post-load observer")
        {
            interp
                .eval(&form, &mut Env::new())
                .expect("evaluate identical post-load observer");
        }
    }
    let result = interp
        .lookup_var(result_variable, &Env::new())
        .expect("fixture sets its result variable");
    fs::remove_file(&path).expect("remove owned contract fixture");
    assert_eq!(result.to_string(), expected);
}

/// filelock.c:lock_file ignores the errno of a lock it cannot create
/// ("FIXME: This ignores errors when lock_if_free returns an errno
/// value"): the file stays unlocked and the caller's write goes on, which
/// is how the byte compiler writes into a directory it cannot create the
/// lock in (bytecomp's Bug#44631 test).  A lock under a plain file fails
/// with ENOTDIR for every user, root included.
#[test]
fn lock_file_ignores_a_lock_it_cannot_create() {
    let mut interp = crate::test_support::initialized_upstream_batch_interpreter();
    let mut env = crate::lisp::types::Env::new();
    let directory = std::env::temp_dir().join(format!(
        "emaxx-lock-enotdir-{}-{}",
        std::process::id(),
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .expect("system clock should be after unix epoch")
            .as_nanos()
    ));
    std::fs::create_dir(&directory).expect("create the fixture directory");
    let blocker = directory.join("x");
    std::fs::write(&blocker, b"").expect("create the blocking file");
    let under_a_file = blocker.join("y").to_string_lossy().into_owned();
    assert_eq!(
        call(
            &mut interp,
            "lock-file",
            &[Value::String(under_a_file.clone().into())],
            &mut env,
        )
        .expect("a lock that cannot be created is not an error"),
        Value::Nil
    );
    assert_eq!(
        call(
            &mut interp,
            "write-region",
            &[
                Value::String("abc".into()),
                Value::Nil,
                Value::String(blocker.to_string_lossy().into_owned().into()),
                Value::Nil,
                Value::Integer(1),
            ],
            &mut env,
        )
        .expect("write-region locks first; a lock it cannot create does not stop it"),
        Value::Nil
    );
    assert_eq!(
        std::fs::read(&blocker).expect("the written file"),
        b"abc",
        "the write reached the file"
    );
    std::fs::remove_dir_all(&directory).expect("remove the fixture directory");
}

/// Fmake_temp_file_internal reports a failed creation with
/// report_file_error: the kind's message, the errno text and PREFIX as the
/// file, under the errno's condition (file-missing for ENOENT).
#[test]
fn make_temp_file_internal_reports_a_failed_creation_as_a_file_error() {
    let mut interp = Interpreter::new();
    let mut env = crate::lisp::types::Env::new();
    let prefix = "/nonexistent-dir-emaxx-zz/prefix";
    for (dir_flag, message) in [
        (Value::Nil, "Creating file with prefix"),
        (Value::T, "Creating directory with prefix"),
    ] {
        let result = call(
            &mut interp,
            "make-temp-file-internal",
            &[
                Value::String(prefix.into()),
                dir_flag,
                Value::String("".into()),
                Value::Nil,
            ],
            &mut env,
        );
        let Err(LispErrorKind::SignalValue(data)) = result.as_ref().map_err(LispError::kind) else {
            panic!("a creation under a missing directory signals: {result:?}");
        };
        assert_eq!(
            *data,
            Value::list([
                Value::symbol("file-missing"),
                Value::String(message.into()),
                Value::String("No such file or directory".into()),
                Value::String(prefix.into()),
            ])
        );
    }
    assert!(
        call(
            &mut interp,
            "make-temp-file-internal",
            &[
                Value::String(prefix.into()),
                Value::Integer(0),
                Value::String("".into()),
                Value::Nil,
            ],
            &mut env,
        )
        .expect("naming only never touches the file system")
        .as_string()
        .is_ok_and(|name| name.starts_with(prefix)),
        "dir-flag 0 only names the file"
    );
}

/// process.c:wait_reading_process_output does not wait for output from a
/// process that is no longer running, timeout or not: a loop of
/// `(accept-process-output PROC 10)' ends when PROC exits.  The timed wait
/// used to run to its deadline after the exit.
#[test]
fn accept_process_output_with_a_timeout_returns_once_the_process_has_exited() {
    let mut interp = crate::test_support::initialized_gnu_window_lisp_interpreter();
    let mut env = crate::lisp::types::Env::new();
    let buffer = Value::Buffer(interp.buffer);
    let process = call_via_lisp(
        &mut interp,
        "start-process",
        &[
            Value::String("accept-output-exited".into()),
            buffer,
            Value::String("sh".into()),
            Value::String("-c".into()),
            Value::String("printf ready; exit 0".into()),
        ],
        &mut env,
    )
    .expect("start-process should launch a writer");
    let started = std::time::Instant::now();
    loop {
        let more = call(
            &mut interp,
            "accept-process-output",
            &[process, Value::Integer(10)],
            &mut env,
        )
        .expect("accept-process-output with a timeout");
        if more.is_nil() {
            break;
        }
        assert!(
            started.elapsed() < std::time::Duration::from_secs(8),
            "the loop must end with the process, not with the timeout"
        );
    }
    assert!(
        started.elapsed() < std::time::Duration::from_secs(8),
        "the loop must end with the process, not with the timeout"
    );
    let text = interp.buffer.borrow().full_buffer_string();
    assert!(text.starts_with("ready"), "the output was read: {text:?}");
}

/// re_search_2 with a negative range takes the latest start position at
/// or before point whose match ends at or before point, the leftmost-first
/// match from that start; GNU's answers for a buffer of 300 `a', one `b'
/// and 100 `c', searched from the end.  The windowed enumeration must give
/// the same answers whether the match lies in the first window or beyond
/// it.
#[test]
fn backward_regexp_search_takes_the_latest_start_as_gnu_does() {
    let mut interp = Interpreter::new();
    let mut env = crate::lisp::types::Env::new();
    let text = format!("{}b{}\n", "a".repeat(300), "c".repeat(100));
    call(
        &mut interp,
        "insert",
        &[Value::String(text.into())],
        &mut env,
    )
    .expect("insert");
    let end = interp.buffer.borrow().point_max() as i64;
    for (pattern, bound, expected) in [
        ("a+", Value::Nil, Some((300, 300, 301))),
        ("a+b", Value::Nil, Some((300, 300, 302))),
        ("a\\{2,5\\}", Value::Nil, Some((299, 299, 301))),
        ("^a", Value::Nil, Some((1, 1, 2))),
        ("c$", Value::Nil, Some((401, 401, 402))),
        ("a+", Value::Integer(200), Some((300, 300, 301))),
        ("[ab]+c", Value::Nil, Some((301, 301, 303))),
        ("\\(a\\)\\1", Value::Nil, Some((299, 299, 301))),
        ("x*", Value::Nil, Some((403, 403, 403))),
        ("b\\|a", Value::Integer(100), Some((301, 301, 302))),
        ("zz", Value::Nil, None),
        ("a+", Value::Integer(350), None),
    ] {
        call(&mut interp, "goto-char", &[Value::Integer(end)], &mut env).expect("goto-char");
        let found = call(
            &mut interp,
            "re-search-backward",
            &[Value::String(pattern.into()), bound, Value::T],
            &mut env,
        )
        .expect("re-search-backward");
        match expected {
            None => assert_eq!(found, Value::Nil, "{pattern} bound {bound:?}"),
            Some((point, start, finish)) => {
                assert_eq!(found, Value::Integer(point), "{pattern} bound {bound:?}");
                let beginning = call(
                    &mut interp,
                    "match-beginning",
                    &[Value::Integer(0)],
                    &mut env,
                )
                .expect("match-beginning");
                let ending = call(&mut interp, "match-end", &[Value::Integer(0)], &mut env)
                    .expect("match-end");
                assert_eq!(
                    (beginning, ending),
                    (Value::Integer(start), Value::Integer(finish)),
                    "{pattern} bound {bound:?}"
                );
            }
        }
    }
}

/// LOADHIST_ATTACH conses every definition onto `current-load-list': a
/// file that defines a name twice lists it twice, as GNU's load-history
/// shows `((defun . zz-a) (defun . zz-a) zz-v zz-v)' for such a file.
#[test]
fn load_history_lists_a_repeated_definition_twice_as_gnu_does() {
    let mut interp = crate::test_support::initialized_gnu_early_lisp_interpreter();
    let mut env = crate::lisp::types::Env::new();
    let path = std::env::temp_dir().join(format!(
        "emaxx-load-history-{}-{}.el",
        std::process::id(),
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .expect("system clock should be after unix epoch")
            .as_nanos()
    ));
    std::fs::write(
        &path,
        "(defalias 'zz-lh-a 'car)\n(defalias 'zz-lh-a 'cdr)\n(defvar zz-lh-v 1)\n(defvar zz-lh-v 2)\n(defvar zz-lh-w)\n",
    )
    .expect("write the fixture file");
    let file = path.to_string_lossy().into_owned();
    call(
        &mut interp,
        "load",
        &[Value::String(file.clone().into()), Value::Nil, Value::T],
        &mut env,
    )
    .expect("load the fixture file");
    let history = call(
        &mut interp,
        "symbol-value",
        &[Value::symbol("load-history")],
        &mut env,
    )
    .expect("load-history");
    let entry = call(
        &mut interp,
        "assoc",
        &[Value::String(file.into()), history],
        &mut env,
    )
    .expect("the file's entry");
    let definitions = call(&mut interp, "cdr", &[entry], &mut env).expect("cdr");
    let defun = |name: &str| Value::cons(Value::symbol("defun"), Value::symbol(name));
    assert_eq!(
        definitions,
        Value::list([
            defun("zz-lh-a"),
            defun("zz-lh-a"),
            Value::symbol("zz-lh-v"),
            Value::symbol("zz-lh-v"),
        ])
    );
    std::fs::remove_file(&path).expect("remove the fixture file");
}

#[test]
fn reader_distinguishes_unibyte_string_characters_from_byte8_sources() {
    assert_oracle_contract_matches_interpreter(
        r#"(let* ((plain (unibyte-string 34 255 34))
                   (raw (string-to-multibyte plain))
                   (escaped (unibyte-string 34 92 51 55 55 34)))
              (mapcar
               (lambda (source)
                 (list
                  (let ((value (read source)))
                    (list (multibyte-string-p value) (string-to-list value)))
                  (let* ((pair (read-from-string (concat "x" source "tail")
                                                 1 (1+ (length source))))
                         (value (car pair)))
                    (list (multibyte-string-p value) (string-to-list value) (cdr pair)))
                  (let ((value (read-positioning-symbols source)))
                    (list (multibyte-string-p value) (string-to-list value)))
                  (with-temp-buffer
                    (set-buffer-multibyte nil)
                    (insert source)
                    (goto-char (point-min))
                    (let ((value (read (current-buffer))))
                      (list (multibyte-string-p value) (string-to-list value) (point))))))
               (list plain raw escaped)))"#,
        "(((t (255)) (t (255) 4) (t (255)) (nil (255) 4)) ((nil (255)) (nil (255) 4) (nil (255)) (nil (255) 4)) ((nil (255)) (nil (255) 7) (nil (255)) (nil (255) 7)))",
        "string bytes, raw-byte characters, octal escapes, and buffer bytes",
    );
}

/// lread.c reads a symbol inside a vector as a symbol with position under
/// `read-positioning-symbols' just as it does inside a list; the reader's
/// placeholder used to stay in the vector, so `type-of' on the element
/// signalled and the byte compiler printed `#<reader-form>' into every
/// constants vector holding a key sequence such as `[mouse-1]'.
#[test]
fn read_positioning_symbols_positions_the_symbols_inside_vectors() {
    let mut interp = crate::test_support::initialized_upstream_batch_interpreter();
    let mut env = crate::lisp::types::Env::new();
    let form = call(
        &mut interp,
        "read-positioning-symbols",
        &[Value::String("(foo [bar] (baz))".into())],
        &mut env,
    )
    .expect("read with positions");
    let rest = call(&mut interp, "cdr", &[form], &mut env).expect("the rest");
    let vector = call(&mut interp, "car", &[rest], &mut env).expect("the vector");
    let element = call(&mut interp, "aref", &[vector, Value::Integer(0)], &mut env)
        .expect("the vector's element");
    assert_eq!(
        call(
            &mut interp,
            "symbol-with-pos-p",
            std::slice::from_ref(&element),
            &mut env
        )
        .expect("symbol-with-pos-p"),
        Value::T
    );
    assert_eq!(
        call(&mut interp, "bare-symbol", &[element], &mut env).expect("bare-symbol"),
        Value::symbol("bar")
    );

    let directory = std::env::temp_dir().join(format!(
        "emaxx-vector-constants-{}-{}",
        std::process::id(),
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .expect("system clock should be after unix epoch")
            .as_nanos()
    ));
    std::fs::create_dir(&directory).expect("create the fixture directory");
    let source = directory.join("keys.el");
    std::fs::write(
        &source,
        ";;; -*- lexical-binding: t -*-\n(defun zz-keys (m) (define-key m [mouse-1] 'ignore) [a \"s\" 1])\n",
    )
    .expect("write the fixture file");
    call_via_lisp(
        &mut interp,
        "byte-compile-file",
        &[Value::String(source.to_string_lossy().into_owned().into())],
        &mut env,
    )
    .expect("byte-compile the file");
    let compiled =
        String::from_utf8_lossy(&std::fs::read(directory.join("keys.elc")).expect("the .elc"))
            .into_owned();
    assert!(
        compiled.contains("[mouse-1]") && compiled.contains("[a \"s\" 1]"),
        "the constants vector prints the symbols bare: {compiled}"
    );
    assert!(
        !compiled.contains("reader-form"),
        "no placeholder reaches the .elc: {compiled}"
    );
    std::fs::remove_dir_all(&directory).expect("remove the fixture directory");
}

/// textprop.c splits and merges the intervals at the edges of a write and
/// leaves the rest of the buffer's intervals alone; the write path used to
/// clone and rebuild every span of the buffer per call (half a millisecond
/// in a 12,000-file dired listing).  The local rewrite keeps the observable
/// results: the neighbours are untouched, an equal neighbour merges, a
/// partly covered span splits, and undo restores the previous plists
/// (the answer is GNU's; the plists are copied because GNU hands out the
/// interval's live plist, which the later write would change in place).
#[test]
fn text_property_writes_touch_only_the_spans_they_cover() {
    let mut interp = crate::test_support::initialized_upstream_batch_interpreter();
    let mut env = crate::lisp::types::Env::new();
    let program = r#"
(with-temp-buffer
  (buffer-enable-undo)
  (dotimes (i 2000) (insert "abcd"))
  ;; 1000 disjoint spans: every other four-character group.
  (dotimes (i 1000) (put-text-property (+ 1 (* 8 i)) (+ 5 (* 8 i)) 'face 'bold))
  (undo-boundary)
  ;; A write across the middle: covers the tail of span 500, the gap, and
  ;; the head of span 501.
  (put-text-property 4003 4011 'face 'italic)
  (let ((around (mapcar (lambda (p) (copy-sequence (text-properties-at p))) '(3993 4001 4002 4003 4010 4011 4012 4013 8000)))
        (before (text-properties-at 1))
        (last (text-properties-at 7997)))
    (primitive-undo 1 buffer-undo-list)
    (list around before last
          (mapcar (lambda (p) (copy-sequence (text-properties-at p))) '(4001 4003 4006 4010 4013))
          ;; An equal write merges with its neighbour: the span's extent grows.
          (progn (put-text-property 4005 4009 'face 'bold)
                 (list (next-single-property-change 4001 'face) (previous-single-property-change 4013 'face))))))
"#;
    let read = call(
        &mut interp,
        "read-from-string",
        &[Value::String(program.into())],
        &mut env,
    )
    .expect("read the program");
    let form = call(&mut interp, "car", &[read], &mut env).expect("the form");
    let result =
        call_via_lisp(&mut interp, "eval", &[form, Value::T], &mut env).expect("run the program");
    let printed = call(&mut interp, "prin1-to-string", &[result], &mut env)
        .expect("print")
        .as_string()
        .expect("a string")
        .to_owned();
    assert_eq!(
        printed,
        "(((face bold) (face bold) (face bold) (face italic) (face italic) (face bold) (face bold) nil nil) (face bold) nil ((face bold) (face bold) (face nil) (face bold) nil) (4013 4001))"
    );
}

/// fns.c keeps an entry's hash code beside it and frees its slot onto a
/// LIFO list, so a `remhash', or a `puthash' into a freed slot, touches
/// one bucket; the runtime used to rebuild its whole bucket index by
/// hashing every remaining key on both (2 ms a `remhash' on tramp's
/// 5,000-entry cache).  The answers, the count and the `maphash' order
/// (slot order, freed slots reused last-in first-out) are GNU's for the
/// same program.
#[test]
fn equal_hash_table_answers_survive_removals_and_slot_reuse() {
    let mut interp = crate::test_support::initialized_upstream_batch_interpreter();
    let mut env = crate::lisp::types::Env::new();
    let program = r#"
(let ((table (make-hash-table :test 'equal)) (log nil))
  (dotimes (i 40) (puthash (list "key" i (* i i)) i table))
  (dotimes (i 40) (when (= (% i 3) 0) (push (remhash (list "key" i (* i i)) table) log)))
  (push (hash-table-count table) log)
  (dotimes (i 8) (puthash (format "fresh-%d" i) (- i) table))
  (push (list (gethash (list "key" 3 9) table 'missing)
              (gethash (list "key" 4 16) table 'missing)
              (gethash "fresh-2" table 'missing)
              (gethash (list "key" 39 1521) table 'missing))
        log)
  (puthash (list "key" 5 25) 'replaced table)
  (push (list (remhash "fresh-1" table) (remhash "never" table) (gethash (list "key" 5 25) table)) log)
  (let ((walk nil))
    (maphash (lambda (k v) (push (cons (if (consp k) (nth 1 k) k) v) walk)) table)
    (push (nreverse walk) log))
  (push (hash-table-count table) log)
  (nreverse log))
"#;
    let read = call(
        &mut interp,
        "read-from-string",
        &[Value::String(program.into())],
        &mut env,
    )
    .expect("read the program");
    let form = call(&mut interp, "car", &[read], &mut env).expect("the form");
    let result =
        call_via_lisp(&mut interp, "eval", &[form, Value::T], &mut env).expect("run the program");
    let printed = call(&mut interp, "prin1-to-string", &[result], &mut env)
        .expect("print")
        .as_string()
        .expect("a string")
        .to_owned();
    assert_eq!(
        printed,
        "(nil nil nil nil nil nil nil nil nil nil nil nil nil nil 26 (missing 4 -2 missing) (nil nil replaced) ((1 . 1) (2 . 2) (4 . 4) (5 . replaced) (7 . 7) (8 . 8) (10 . 10) (11 . 11) (13 . 13) (14 . 14) (16 . 16) (17 . 17) (\"fresh-7\" . -7) (19 . 19) (20 . 20) (\"fresh-6\" . -6) (22 . 22) (23 . 23) (\"fresh-5\" . -5) (25 . 25) (26 . 26) (\"fresh-4\" . -4) (28 . 28) (29 . 29) (\"fresh-3\" . -3) (31 . 31) (32 . 32) (\"fresh-2\" . -2) (34 . 34) (35 . 35) (37 . 37) (38 . 38) (\"fresh-0\" . 0)) 33)"
    );
}

#[test]
fn quoted_objects_survive_only_while_reachable() {
    if reclamation_contract_runs_in_fresh_process("quoted_objects_survive_only_while_reachable") {
        return;
    }
    // eval.c:Fquote adds no root. One freshly read quoted graph is held
    // in a Lisp variable; the other is held only by a weak key. Both
    // must be collectible after the variable is cleared. The same
    // program and post-load observer run in GNU and in this runtime.
    let program = r#"(progn
  (setq quote-retention-table (make-hash-table :test 'eq :weakness 'key))
  (setq quote-retention-result nil)
  (defun quote-retention-create ()
    (let* ((form (read "'(freshly-read unretained graph)"))
           (object (eval form)))
      (puthash object t quote-retention-table))
    nil)
  (quote-retention-create)
  (setq quote-retention-live (eval (read "'(live shared graph)")))
  (puthash quote-retention-live t quote-retention-table))"#;
    let observer = r#"(progn
  (dotimes (index 4096) (cons index index))
  (garbage-collect)
  (setq quote-retention-result
        (list (hash-table-count quote-retention-table)
              (gethash quote-retention-live quote-retention-table)))
  (setq quote-retention-live nil)
  (dotimes (index 4096) (cons index index))
  (garbage-collect)
  (garbage-collect)
  (setq quote-retention-result
        (append quote-retention-result
                (list (hash-table-count quote-retention-table))))
  (prin1 quote-retention-result))"#;
    assert_oracle_file_contract_with_observer(
        program,
        Some(observer),
        "quote-retention-result",
        "(1 t 0)",
    );
}

#[test]
fn interpreted_closures_keep_their_argument_body_and_environment_objects() {
    let source = include_str!("../../../tests/fixtures/closure-object-sharing.el");
    assert_oracle_contract_matches_interpreter(
        source,
        "(((t t t t 19) 73) (t 73 73) (4 73 19) t t 73 (constructed invalid-function t) ((19 73) nil) 73 (wrong-number-of-arguments t (let unlet)) 73 (t 19) (wrong-number-of-arguments function 2))",
        "authoritative closure objects",
    );
    let renamed = source
        .replace("closure-audit", "alternate-check")
        .replace("parameter", "fruit")
        .replace("replacement", "substitute")
        .replace("19", "41")
        .replace("73", "101");
    assert_oracle_contract_matches_interpreter(
        &renamed,
        "(((t t t t 41) 101) (t 101 101) (4 101 41) t t 101 (constructed invalid-function t) ((41 101) nil) 101 (wrong-number-of-arguments t (let unlet)) 101 (t 41) (wrong-number-of-arguments function 2))",
        "renamed authoritative closure objects",
    );
}

#[test]
fn interpreted_closure_bodies_survive_only_while_reachable() {
    if reclamation_contract_runs_in_fresh_process(
        "interpreted_closure_bodies_survive_only_while_reachable",
    ) {
        return;
    }
    let setup = r#"(progn
      (setq closure-retention-table (make-hash-table :test 'eq :weakness 'key))
      (setq closure-retention-result nil)
      (defun closure-retention-create ()
        (let* ((body (list 73))
               (closure (make-interpreted-closure nil body '(t))))
          (puthash body t closure-retention-table)
          closure))
      (setq closure-retention-live (closure-retention-create))
      (closure-retention-create)
      nil)"#;
    let observer = r#"(progn
      (dotimes (index 4096) (cons index index))
      (garbage-collect)
      (setq closure-retention-result
            (list (hash-table-count closure-retention-table)
                  (gethash (aref closure-retention-live 1) closure-retention-table)
                  (funcall closure-retention-live)))
      (setq closure-retention-live nil)
      (dotimes (index 4096) (cons index index))
      (garbage-collect)
      (garbage-collect)
      (setq closure-retention-result
            (append closure-retention-result (list (hash-table-count closure-retention-table))))
      (prin1 closure-retention-result))"#;
    assert_oracle_file_contract_with_observer(
        setup,
        Some(observer),
        "closure-retention-result",
        "(1 t 73 0)",
    );
}

